    let (rep_a, rep_b) = (w(clube_a, 0x80), w(clube_b, 0x80));
    let rodando = byte(m, 0x8ea5) != 0;
    // a forca de cada lado (so os 16 bits contam, como no original)
    let (mut proprio, mut outro) = (rep_a, rep_b);
