            crate::comparacao::ramo("desfecho empate tardio");
            let a = contar_ativos(m, outro as i8) as i8;
            let b = contar_ativos(m, lado) as i8;
            let bl = if a < b { byte(m, 4 + outro as usize) } else { -1 };
