            *w(p, 0x35) = (*w(p, 0x35)).wrapping_add(0x113);
            if sortear(byte(p, 0x17) as i32 * 20 + 0x32) == 0 {
                let r = sortear(4);
                ajustar(p, r);
            }
            let piso = ftol((ub(p, 0x10) as f64 * f32_em(0x968f18) as f64 + f64_em(0x96afa0)) * f64_em(0x968908)) as i16;
