    let n7 = |chamar: &mut dyn FnMut(usize, usize, [u32; 5]) -> u32, codigo: u32, a3: u32, a4: u32, a5: u32, a6: u32| narrar_finalizacao(chamar, m, codigo, a3, a4, a5, a6, 0);
