// ---------- centesima quinquagesima nona leva: a formacao (formation.cpp), posicoes do jogador e casas no campo ----------

/// { 0x5b7d20 } (cdecl, formation.cpp): a máscara das posições fortes do jogador `p` pelas notas de
/// posição (bytes com sinal): a partir de 15, descendo até 10, o primeiro nível em que alguma passa
/// dá os bits do setor (+0xf goleiro 1, +0x10 líbero 2, +0x11 zagueiro 4, +0x12 volante 8 ou, sem
/// ele, +0x14 meia 0x20 ou +0x13 0x10, +0x15 atacante 0x40); os lados (+0x17 0x800, +0x18 0x80,
/// +0x19 0x200) só contam com nota 15 ou mais (a original repete o mesmo teste a cada nível).
/// Devolve só `ax` (os chamadores usam 16 bits). `p` nulo: a original (caixa de erro e 0).
unsafe extern "C" fn mascara_de_posicoes(p: usize) -> u16 {
    if p == 0 {
        return orig::<unsafe extern "C" fn(usize) -> u16>(349)(p);
    }
    let b = |o: usize| *((p + o) as *const i8);
    let mut m = 0u16;
    let mut nivel = 15i8;
    loop {
        if b(0xf) >= nivel {
            m |= 1;
        }
        if b(0x11) >= nivel {
            m |= 4;
        }
        if b(0x10) >= nivel {
            m |= 2;
        }
        if b(0x12) >= nivel {
            m |= 8;
        } else if b(0x14) >= nivel {
            m |= 0x20;
        } else if b(0x13) >= nivel {
            m |= 0x10;
        }
        if b(0x15) >= nivel {
            m |= 0x40;
        }
        nivel -= 1;
        if nivel < 10 || m != 0 {
            break;
        }
    }
    if b(0x17) >= 15 {
        m |= 0x800;
    }
    if b(0x18) >= 15 {
        m |= 0x80;
    }
    if b(0x19) >= 15 {
        m |= 0x200;
    }
    m
}

/// { 0x5b7e60 } (cdecl, formation.cpp): a casa no campo (`saida[0]` = coluna 0..26, `saida[1]` =
/// linha 0..35) da posição `mascara` (separada pela 0x5b73a0 em setor e lado), com `ataque` 0/1 e
/// `faixa` = palavra baixa 0..2 (esquerda, meio, direita) e palavra alta 0..3 (a altura na
/// formação). A linha vem do setor (tabelas de 4 pela altura; no ataque, os laterais 0x80/0x800
/// sobem 1, ou 1/4 nos setores 2 e 4); a coluna, do lado (tabelas de 5); depois os encostos nas
/// faixas e os limites. Argumentos fora da faixa: a original (caixa de erro e 0). Devolve 1.
unsafe extern "C" fn casa_no_campo(mascara: u32, ataque: i8, faixa: u32, saida: *mut i16) -> u32 {
    let baixo = faixa as u16 as i16;
    let alto = (faixa >> 16) as u16 as i16;
    if !(0..=1).contains(&ataque) || !(0..=2).contains(&baixo) || !(0..=3).contains(&alto) {
        return orig::<unsafe extern "C" fn(u32, i8, u32, *mut i16) -> u32>(350)(mascara, ataque, faixa, saida);
    }
    let separar: unsafe extern "C" fn(u32, *mut u16, *mut u16) -> u32 = core::mem::transmute(0x5b73a0usize);
    let (mut setor, mut lado) = (0u16, 0u16);
    separar(mascara, &mut setor, &mut lado);
    let a = alto as usize;
    let lateral = lado & 0x80 != 0 || lado & 0x800 != 0;
    let at = ataque != 0;
    // a linha (saida[1])
    let linha: i16 = if setor & 1 != 0 {
        if at { [0, 2, 4, 6][a] } else { [0, 1, 2, 3][a] }
    } else if setor & 2 != 0 {
        if !at {
            [1, 3, 5, 9][a]
        } else {
            let v = [2, 4, 13, 15][a];
            if lateral { v + if alto != 3 { 1 } else { 4 } } else { v }
        }
    } else if setor & 4 != 0 {
        if !at {
            [2, 7, 9, 13][a]
        } else {
            let v = [4, 9, 17, 17][a];
            if lateral { v + if alto != 3 { 1 } else { 4 } } else { v }
        }
    } else {
        let (sem, com): ([i16; 4], [i16; 4]) = if setor & 8 != 0 {
            ([4, 9, 13, 18], [7, 11, 20, 22])
        } else if setor & 0x10 != 0 {
            ([6, 11, 16, 22], [9, 14, 23, 26])
        } else if setor & 0x20 != 0 {
            ([9, 13, 19, 26], [12, 19, 27, 30])
        } else {
            ([13, 15, 23, 31], [15, 24, 31, 34])
        };
        if !at {
            sem[a]
        } else if lateral {
            com[a] + 1
        } else {
            com[a]
        }
    };
    *saida.add(1) = linha;
    // a coluna (saida[0]), pelo lado
    let l = if lado & 0x80 != 0 {
        0
    } else if lado & 0x100 != 0 {
        1
    } else if lado & 0x200 != 0 {
        2
    } else if lado & 0x400 != 0 {
        3
    } else {
        4
    };
    let tabela: [i16; 5] = if setor & 1 != 0 {
        [13; 5]
    } else if setor & 6 != 0 || setor & 0x38 != 0 {
        match (at, alto == 0, setor & 6 != 0) {
            (false, true, _) => [9, 11, 13, 15, 17],
            (false, false, _) => [7, 11, 13, 15, 19],
            (true, true, true) => [6, 11, 13, 15, 20],
            (true, _, _) => [3, 10, 13, 16, 23],
        }
    } else if !at {
        [7, 11, 13, 15, 19]
    } else if alto == 0 || alto == 1 {
        [2, 8, 13, 18, 24]
    } else if alto == 2 {
        [3, 10, 13, 16, 23]
    } else {
        [6, 11, 13, 15, 20]
    };
    *saida = tabela[l];
    // os encostos: com `perto`, um passo na faixa; sem, cinco (fora do goleiro)
    let perto = (setor & 1 != 0 && alto > 0)
        || (setor & 6 != 0 && alto == 0)
        || (setor & 0x40 != 0 && lado & 0x700 != 0 && alto == 3 && ataque == 1);
    let passo = if perto { 1 } else if setor & 1 == 0 { 5 } else { 0 };
    if passo != 0 {
        let v = *saida as i32;
        if baixo == 0 {
            *saida = (v - passo).clamp(2, 0x11) as i16;
        } else if baixo == 2 {
            *saida = (v + passo).clamp(9, 0x18) as i16;
        }
    }
    *saida = (*saida).clamp(0, 0x1a);
    *saida.add(1) = (*saida.add(1)).clamp(0, 0x23);
    1
}

/// { 0x5b8960 } (thiscall, formation.cpp): as 11 vagas da formação `this` sem conflito: devolve 0
/// se alguma vaga com lado aberto (0x880 na casa +0x12d ou +0x14e, ver 0x5b2ae0) é também de
/// atacante (0x40, nas duas), de meia (0x20 na +0x12d e na +0x14e pela 0x5b2ae0) ou de volante e
/// meia-atacante pela 0x5b2ae0 (8 e 0x10); senão 1. Devolve só `al`.
unsafe extern "thiscall" fn vagas_sem_conflito(this: usize) -> u8 {
    let casa: unsafe extern "thiscall" fn(usize, u32, u32) -> u16 = core::mem::transmute(0x5b2ae0usize);
    let w = |o: usize| core::ptr::read_unaligned((this + o) as *const u16);
    for i in 0..=10u32 {
        let a = w(0x12d + 2 * i as usize);
        let b = w(0x14e + 2 * i as usize);
        if a & 0x880 != 0 && a & 0x40 != 0 {
            return 0;
        }
        if b & 0x880 != 0 && b & 0x40 != 0 {
            return 0;
        }
        if a & 0x880 != 0 && a & 0x20 != 0 {
            return 0;
        }
        if b & 0x880 != 0 && casa(this, i, 1) & 0x20 != 0 {
            return 0;
        }
        if casa(this, i, 0) & 0x880 != 0 && casa(this, i, 0) & 8 != 0 {
            return 0;
        }
        if casa(this, i, 0) & 0x880 != 0 && casa(this, i, 0) & 0x10 != 0 {
            return 0;
        }
        if casa(this, i, 1) & 0x880 != 0 && casa(this, i, 1) & 0x10 != 0 {
            return 0;
        }
    }
    1
}

unsafe extern "C" fn comparar_mascara_de_posicoes(p: usize) -> u16 {
    let r = orig::<unsafe extern "C" fn(usize) -> u16>(349)(p);
    let n = mascara_de_posicoes(p);
    PLACAR.registrar(r == n, || format!("mascara_de_posicoes({:#x}) original={:#x} rust={:#x}", p, r, n));
    r
}

unsafe extern "C" fn comparar_casa_no_campo(mascara: u32, ataque: i8, faixa: u32, saida: *mut i16) -> u32 {
    let o = orig::<unsafe extern "C" fn(u32, i8, u32, *mut i16) -> u32>(350);
    let reg = [(saida as usize, 4)];
    let (r, v, igual, mo, mr) = crate::comparacao::lado_a_lado_leve(&reg, || o(mascara, ataque, faixa, saida), || casa_no_campo(mascara, ataque, faixa, saida));
    PLACAR.registrar(igual && r == v, || format!("casa_no_campo({:#x}, {}, {:#x}) original={} {:x?} rust={} {:x?}", mascara, ataque, faixa, r, mo, v, mr));
    r
}

comparar_valor!(comparar_vagas_sem_conflito, vagas_sem_conflito, 351, () -> u8);

// ---------- centesima sexagesima leva: estatisticas do jogador (player_stats.cpp) e zagueiros na formacao ----------

/// { 0x7c2150 } (stdcall, ret 0xc, player_stats.cpp): a estatística `qual` do registro `r` (jogos
/// em +0, bytes +2..+0xd, palavras +0xe..+0x1a, +0x1c inteiro), como a original a deixa no x87:
/// 1..12 os bytes; 13 e 16 as porcentagens (+0x12/+0x10 e +0x1a/+0x18, vezes 100.0f); 14, 15, 17 e
/// 21 as médias por jogo; 18 a média de +0xe com menos de 20 jogos completada por `peso` (vezes
/// 0.05f); 20 a nota (2×+9 − +0xa + jogos, completada por 1.5 com menos de 20 jogos; 1.5f sem
/// jogos); 22 o inteiro. Sem divisor: 0.0. `r` nulo, 19 ou fora de 1..22: a original (caixa de erro).
unsafe extern "stdcall" fn estatistica_do_jogador(r: *const u8, qual: i8, peso: f32) -> f64 {
    if r.is_null() || !(1..=22).contains(&qual) || qual == 19 {
        return orig::<unsafe extern "stdcall" fn(*const u8, i8, f32) -> f64>(352)(r, qual, peso);
    }
    let b = |o: usize| *r.add(o) as f64;
    let w = |o: usize| core::ptr::read_unaligned(r.add(o) as *const i16) as f64;
    let jogos = *r;
    let cem = f32_em(0x968960) as f64;
    let vinte_avos = f32_em(0x96d61c) as f64;
    match qual {
        1 => b(0),
        2..=4 => b(qual as usize),
        5..=12 => b(qual as usize + 1),
        13 | 16 => {
            let (n, d) = if qual == 13 { (0x12, 0x10) } else { (0x1a, 0x18) };
            if core::ptr::read_unaligned(r.add(d) as *const i16) > 0 {
                w(n) / w(d) * cem
            } else {
                0.0
            }
        }
        14 | 15 | 17 | 21 => {
            let o = match qual { 14 => 0x14, 15 => 0x16, 17 => 0xe, _ => 0x18 };
            if jogos != 0 { w(o) / jogos as f64 } else { 0.0 }
        }
        18 => {
            if jogos < 20 {
                ((20 - jogos as i32) as f64 * peso as f64 + w(0xe)) * vinte_avos
            } else {
                w(0xe) / jogos as f64
            }
        }
        20 => {
            if jogos == 0 {
                return f32_em(0x96b004) as f64;
            }
            let nota = (*r.add(9) as i32 * 2 - *r.add(10) as i32 + jogos as i32) as f64;
            if jogos < 20 {
                (nota + (20 - jogos as i32) as f64 * f64_em(0x968940)) * vinte_avos
            } else {
                nota / jogos as f64
            }
        }
        _ => core::ptr::read_unaligned(r.add(0x1c) as *const i32) as f64,
    }
}

/// { 0x7c1950 } (thiscall, ret 4, player_stats.cpp): a média das cinco notas de 4 bits do registro
/// `*indice` (0x27 bytes cada, a partir de [this+0x30]): os dois meios de +0x24 e de +0x25 e o meio
/// baixo de +0x26, cada um ×4 (zero conta 27), somados em 16 bits e divididos por 4 (truncando).
/// `indice` nulo: a original (caixa de erro).
unsafe extern "thiscall" fn media_das_notas(this: usize, indice: *const i32) -> i32 {
    if indice.is_null() {
        return orig::<unsafe extern "thiscall" fn(usize, *const i32) -> i32>(353)(this, indice);
    }
    let reg = (*indice).wrapping_mul(0x27).wrapping_add(*((this + 0x30) as *const i32)) as usize;
    let nota = |n: u8| if n == 0 { 0x1b } else { n as u16 * 4 };
    let (a, c, e) = (*((reg + 0x24) as *const u8), *((reg + 0x25) as *const u8), *((reg + 0x26) as *const u8));
    let soma = nota(a & 0xf)
        .wrapping_add(nota(a >> 4))
        .wrapping_add(nota(c & 0xf))
        .wrapping_add(nota(c >> 4))
        .wrapping_add(nota(e & 0xf));
    soma as i16 as i32 / 4
}

/// { 0x5b8dc0 } (thiscall, formation.cpp): como a 0x5b8960, para os zagueiros: devolve 0 se alguma
/// das 11 vagas com lado aberto (0x880) é de zagueiro (4, na casa +0x12d ou +0x14e) ou de volante
/// (8 na +0x12d; na +0x14e pela 0x5b2ae0); senão 1. Devolve só `al`.
unsafe extern "thiscall" fn zagueiros_sem_conflito(this: usize) -> u8 {
    let casa: unsafe extern "thiscall" fn(usize, u32, u32) -> u16 = core::mem::transmute(0x5b2ae0usize);
    let w = |o: usize| core::ptr::read_unaligned((this + o) as *const u16);
    for i in 0..=10u32 {
        let a = w(0x12d + 2 * i as usize);
        let b = w(0x14e + 2 * i as usize);
        if a & 0x880 != 0 && a & 4 != 0 {
            return 0;
        }
        if b & 0x880 != 0 && b & 4 != 0 {
            return 0;
        }
        if a & 0x880 != 0 && a & 8 != 0 {
            return 0;
        }
        if b & 0x880 != 0 && casa(this, i, 1) & 8 != 0 {
            return 0;
        }
    }
    1
}

unsafe extern "stdcall" fn comparar_estatistica_do_jogador(r: *const u8, qual: i8, peso: f32) -> f64 {
    let o = orig::<unsafe extern "stdcall" fn(*const u8, i8, f32) -> f64>(352)(r, qual, peso);
    let n = estatistica_do_jogador(r, qual, peso);
    PLACAR.registrar(o.to_bits() == n.to_bits(), || format!("estatistica_do_jogador({:p}, {}, {}) original={} rust={}", r, qual, peso, o, n));
    o
}

comparar_valor!(comparar_media_das_notas, media_das_notas, 353, (indice: *const i32) -> i32);
comparar_valor!(comparar_zagueiros_sem_conflito, zagueiros_sem_conflito, 354, () -> u8);

// ---------- centesima sexagesima primeira leva: lista de observacao, codigo da posicao e criterio da comissao ----------

/// { 0x844300 } (stdcall, ret 8, shortlist_manager.cpp): o jogador `j` (ficha em [j+0x61]) serve
/// para a vaga `vaga` 0..15 da lista de observação: 0..14 pedem nota 15 nas posições da vaga
/// (setor e lado: +0xf..+0x16 e +0x17..+0x19); 15 pede ficha de contrato ([j+0x69]), id abaixo de
/// [0xae2364]−16 e, com treinador em [j+0x39] de função 11, 13 ou 15 em +0x3d, a 0x600a50 em zero.
/// Sem ficha (fora a vaga 15): 0. Vaga fora de 0..15: a original (caixa de erro). Devolve só `al`.
unsafe extern "stdcall" fn serve_para_a_vaga(j: usize, vaga: i8) -> u8 {
    let ficha = core::ptr::read_unaligned((j + 0x61) as *const usize);
    if ficha == 0 && vaga != 15 {
        return 0;
    }
    if !(0..=15).contains(&vaga) {
        return orig::<unsafe extern "stdcall" fn(usize, i8) -> u8>(355)(j, vaga);
    }
    let n = |o: usize| *((ficha + o) as *const i8) >= 15;
    // (setor, lado): 0 = so o setor
    let (setor, lado): (usize, usize) = match vaga {
        0 => (0xf, 0),
        1 => (0x10, 0x19),
        2 => (0x11, 0x18),
        3 => (0x11, 0x17),
        4 => (0x11, 0x19),
        5 => (0x16, 0x18),
        6 => (0x12, 0x19),
        7 => (0x16, 0x17),
        8 => (0x13, 0x18),
        9 => (0x13, 0x19),
        10 => (0x13, 0x17),
        11 => (0x14, 0x18),
        12 => (0x14, 0x19),
        13 => (0x14, 0x17),
        14 => (0x15, 0),
        _ => {
            let tecnico = core::ptr::read_unaligned((j + 0x39) as *const usize);
            if tecnico != 0 && matches!(*((j + 0x3d) as *const u8), 0xb | 0xf | 0xd) {
                let f: unsafe extern "C" fn(usize, u32, u32, u32, u32) -> u32 = core::mem::transmute(0x600a50usize);
                if f(tecnico, 0, 1, 0, 0) != 0 {
                    return 0;
                }
            }
            let contrato = core::ptr::read_unaligned((j + 0x69) as *const usize);
            return (contrato != 0 && *(j as *const i32) < (*(0xae2364 as *const i32)).wrapping_sub(0x10)) as u8;
        }
    };
    (n(setor) && (lado == 0 || n(lado))) as u8
}

/// { 0x83bd00 } (stdcall, ret 4, shortlist_manager.cpp): o código da posição (0..13, 0x11..0x15)
/// da máscara `m` de um bit de setor com um de lado (0x80, 0x100, 0x200, 0x400, 0x800); fora das
/// combinações conhecidas, 0xe. Devolve só `al`.
unsafe extern "stdcall" fn codigo_da_posicao(m: i16) -> u8 {
    match m {
        1 => 0,
        2 => 1,
        4 => 0x11,
        8 => 0x13,
        0x10 => 0x12,
        0x20 => 0x15,
        0x40 => 0x14,
        0x84 => 2,
        0x88 => 5,
        0x90 => 8,
        0xa0 => 0xb,
        0x104 | 0x204 | 0x404 => 4,
        0x108 | 0x208 | 0x408 => 6,
        0x110 | 0x210 | 0x410 => 9,
        0x120 | 0x220 | 0x420 => 0xc,
        0x804 => 3,
        0x808 => 7,
        0x810 => 0xa,
        0x820 => 0xd,
        _ => 0xe,
    }
}

/// { 0x866f60 } (thiscall, staff_contracts.cpp): o critério da comissão técnica `t` (pessoa [t] em
/// [0xae23bc], 0x6e bytes; clube [t+4] em [0xae23b4], 0x245 bytes; funções em [t+0x45]): 0 se a
/// pessoa é o técnico ou o auxiliar do clube (+0xcf, +0xd3) ou não tem função; senão uma nota em 8
/// bits (id mod 7 + +0x59 + +0x5a + +0x5b, descontos pelas notas baixas e pela idade, +0x44 em
/// faixas, a reputação do clube, e menos o número de funções acima de uma) decide pelas funções e
/// pelas notas se devolve 1.
unsafe extern "thiscall" fn criterio_da_comissao(t: usize) -> u32 {
    let p = (*(0xae23bc as *const usize)).wrapping_add((*(t as *const i32) as usize).wrapping_mul(0x6e));
    let clube = (*(0xae23b4 as *const usize)).wrapping_add((*((t + 4) as *const i32) as usize).wrapping_mul(0x245));
    let u = |a: usize| core::ptr::read_unaligned(a as *const usize);
    let tecnico = u(clube + 0xcf);
    if tecnico != 0 && p == tecnico {
        return 0;
    }
    let auxiliar = u(clube + 0xd3);
    if auxiliar != 0 && p == auxiliar {
        return 0;
    }
    let funcoes = u(t + 0x45) as u32;
    if funcoes == 0 {
        return 0;
    }
    let b = |o: usize| *((p + o) as *const i8);
    let (b59, b5a, b5b, b5d) = (b(0x59), b(0x5a), b(0x5b), b(0x5d));
    let b44 = *((t + 0x44) as *const i8);
    let mut nota = ((*(p as *const i32) % 7) as u8).wrapping_add(b59 as u8).wrapping_add(b5a as u8).wrapping_add(b5b as u8);
    if b5a == 1 {
        nota = nota.wrapping_sub(2);
    }
    if b59 == 1 {
        nota = nota.wrapping_sub(3);
    } else if b59 < 6 {
        nota = nota.wrapping_sub(1);
    }
    if b5b == 1 {
        nota = nota.wrapping_sub(3);
    } else if b5b < 6 {
        nota = nota.wrapping_sub(1);
    }
    if b5d == 1 {
        nota = nota.wrapping_sub(2);
    }
    if b44 > 0x4b {
        nota = nota.wrapping_add(10);
    } else if b44 > 0x32 {
        nota = nota.wrapping_add(5);
    } else if b44 > 0 {
        nota = nota.wrapping_add(2);
    }
    let ficha = u(p + 0x61);
    if ficha != 0 {
        let rep = core::ptr::read_unaligned((ficha + 0xb) as *const i16);
        if rep > 0x1c52 {
            nota = nota.wrapping_sub(5);
        } else if rep > 0x1676 {
            nota = nota.wrapping_sub(3);
        }
    }
    let tecnica = *((t + 0x40) as *const u32) & 8 != 0;
    let m1 = funcoes & 0x1000002;
    let mut k = 0u8;
    for bits in [0x20000u32, 0x40000, 0x1000002, 0x200600, 0x2840, 0x14] {
        if funcoes & bits != 0 {
            k += 1;
        }
    }
    if tecnica || funcoes & 0x4582208 != 0 {
        k += 1;
    }
    if k > 1 {
        nota = nota.wrapping_sub(3);
        if b5b < 6 {
            nota = nota.wrapping_sub(k);
        }
        if b5d < 6 {
            nota = nota.wrapping_sub(k);
        }
        if b59 == 1 {
            nota = nota.wrapping_add((k as i8).wrapping_mul(-2) as u8);
        } else if b59 < 6 {
            nota = nota.wrapping_sub(k);
        }
        if b5a < 6 {
            nota = nota.wrapping_sub(k);
        }
    }
    let nota = nota as i8;
    let sim = (b59 < 15 && *((t + 0x4e) as *const u8) & 1 != 0)
        || (m1 != 0 && b59 < 10 && nota < 25)
        || (funcoes & 0x20020 != 0 && nota < 25)
        || (funcoes & 0x200 != 0 && nota < 18)
        || (funcoes & 4 != 0 && b(0x57) > 15 && b5b < 10)
        || (funcoes & 0x2808 != 0 && b59 < 10 && b5a < 6 && nota < 30)
        || ((funcoes & 0x82200 != 0 || tecnica) && b5b < 10 && nota < 20)
        || funcoes & 0x111 != 0
        || (b44 as i32) < -0x46 - b59 as i32;
    sim as u32
}

