unsafe extern "C" fn comparar_limpar_pasta_temporaria(padrao: usize) {
    orig::<unsafe extern "C" fn(usize)>(561)(padrao)
}

// ---------- 218a leva: o contêiner do save: ler, gravar e fechar um item (o RLE do tipo 4) (zipdir.cpp) ----------
//
// O ZFILE (0xa3191 bytes, do zopen 0x9326e0): +0 o FILE da CRT, +4 modo (1 gravando), +8 posição
// lógica (bytes descomprimidos), +0xc o item, +0x10/+0x14 repetição do RLE (entregues/contagem),
// +0x18 o byte da repetição, +0x19 cabeçalho (tipo +0x19, a4 +0x1d, quantos +0x21) e índice
// (+0x25, 0x10c por item: posição, tamanho descomprimido, nome), buffer de leitura +0x41705 e de
// escrita +0x72445 (0x30d40 cada), cursores +0xa3185 (leitura), +0xa3189 (escrita), +0xa318d (lidos).
// RLE: byte <= 0x80 sai como está; > 0x80 = (byte − 0x80) cópias do byte seguinte (1 a 0x7f).

/// Lê um dword sem alinhamento no ZFILE.
unsafe fn zf_u(z: usize, o: usize) -> i32 {
    core::ptr::read_unaligned((z + o) as *const i32)
}

/// Grava um dword sem alinhamento no ZFILE.
unsafe fn zf_por(z: usize, o: usize, v: i32) {
    core::ptr::write_unaligned((z + o) as *mut i32, v)
}

/// O próximo byte comprimido do item: do buffer de leitura (+0x41705, cursor +0xa3185 até +0xa318d)
/// ou, acabado, de um `fread` de 0x30d40 bytes (o primeiro byte do bloco novo, mesmo se veio vazio).
unsafe fn zf_proximo_byte(z: usize) -> u8 {
    let ler: unsafe extern "C" fn(usize, u32, u32, usize) -> i32 = core::mem::transmute(0x945bfeusize);
    let c = zf_u(z, 0xa3185);
    if c < zf_u(z, 0xa318d) {
        let b = *((z + 0x41705 + c as usize) as *const u8);
        zf_por(z, 0xa3185, c + 1);
        return b;
    }
    // ponytail: o ramo marca o bloco, nao cada chamada (a zread roda milhoes de vezes na carga)
    crate::comparacao::ramo("save zread bloco");
    zf_por(z, 0xa318d, ler(z + 0x41705, 1, 0x30d40, zf_u(z, 0) as usize));
    let b = *((z + 0x41705) as *const u8);
    zf_por(z, 0xa3185, 1);
    b
}

/// { 0x932c30 } (cdecl, zipdir.cpp): `zread(buf, tam, quantos, z)` como o `fread`, dentro do item
/// aberto para leitura (senão 0): o pedido (`tam × quantos`, int) é cortado no fim do item e soma à
/// posição lógica. Tipo 3: `fread` direto de `pedido / tam` itens. Tipo 4: decodifica o RLE; uma
/// repetição pode atravessar chamadas (+0x10 de +0x14). Devolve `pedido / tam` (divisão com sinal,
/// como a original: `tam` 0 derruba as duas).
unsafe extern "C" fn ler_do_conteiner(buf: *mut u8, tam: i32, quantos: i32, z: usize) -> i32 {
    let ler: unsafe extern "C" fn(*mut u8, i32, i32, usize) -> i32 = core::mem::transmute(0x945bfeusize);
    if z == 0 || zf_u(z, 4) != 0 {
        return 0;
    }
    let tamanho_do_item = zf_u(z, 0x29 + 0x10c * zf_u(z, 0xc) as usize);
    let mut pedido = tam.wrapping_mul(quantos);
    let pos = zf_u(z, 8);
    if pos > tamanho_do_item.wrapping_sub(pedido) {
        pedido = tamanho_do_item.wrapping_sub(pos);
        if pedido <= 0 {
            return 0;
        }
    }
    let fim = zf_u(z, 8).wrapping_add(pedido);
    zf_por(z, 8, fim);
    if zf_u(z, 0x19) != 4 {
        crate::comparacao::ramo("save zread tipo 3");
        let q = pedido / tam;
        zf_por(z, 8, tam.wrapping_mul(q).wrapping_sub(pedido).wrapping_add(fim));
        return ler(buf, tam, q, zf_u(z, 0) as usize);
    }
    let mut k = 0i32;
    if pedido > 0 {
        'fora: loop {
            // o resto da repetição pendente
            let n = zf_u(z, 0x14);
            if n != 0 && zf_u(z, 0x10) < n {
                loop {
                    if k >= pedido {
                        break 'fora;
                    }
                    *buf.add(k as usize) = *((z + 0x18) as *const u8);
                    k += 1;
                    let e = zf_u(z, 0x10) + 1;
                    zf_por(z, 0x10, e);
                    if e >= zf_u(z, 0x14) {
                        break;
                    }
                }
            }
            if k >= pedido {
                break;
            }
            zf_por(z, 0x14, 0);
            zf_por(z, 0x10, 0);
            loop {
                let b = zf_proximo_byte(z);
                if b <= 0x80 {
                    *buf.add(k as usize) = b;
                    k += 1;
                } else {
                    zf_por(z, 0x14, b as i32 - 0x80);
                    *((z + 0x18) as *mut u8) = zf_proximo_byte(z);
                }
                if zf_u(z, 0x14) == 0 {
                    if k >= pedido {
                        break 'fora;
                    }
                    continue;
                }
                if k < pedido {
                    continue 'fora;
                }
                break 'fora;
            }
        }
    }
    pedido / tam
}

// ponytail: lê do arquivo e anda o cursor do FILE e do item; não roda duas vezes. A prova do save
// (carga, --sav) e a gravação (o zseek relê pela zread) passam por aqui.
unsafe extern "C" fn comparar_ler_do_conteiner(buf: *mut u8, tam: i32, quantos: i32, z: usize) -> i32 {
    orig::<unsafe extern "C" fn(*mut u8, i32, i32, usize) -> i32>(562)(buf, tam, quantos, z)
}

/// Um byte comprimido para o buffer de escrita (+0x72445, cursor +0xa3189); cheio, grava o buffer
/// inteiro (`fwrite`) e o byte vai para o começo.
unsafe fn zf_soltar(z: usize, b: u8) {
    let escrever: unsafe extern "C" fn(usize, u32, i32, usize) -> u32 = core::mem::transmute(0x945ce6usize);
    let p = zf_u(z, 0xa3189);
    if p < 0x30d40 {
        *((z + 0x72445 + p as usize) as *mut u8) = b;
        zf_por(z, 0xa3189, p + 1);
        return;
    }
    // ponytail: o ramo marca o bloco, nao cada chamada (a zwrite roda milhoes de vezes no save)
    crate::comparacao::ramo("save zwrite bloco");
    escrever(z + 0x72445, 1, p, zf_u(z, 0) as usize);
    zf_por(z, 0xa3189, 1);
    *((z + 0x72445) as *mut u8) = b;
}

/// { 0x932e10 } (cdecl, zipdir.cpp): `zwrite(buf, tam, quantos, z)` como o `fwrite`, no item aberto
/// para gravar (senão 0): soma `tam × quantos` ao tamanho do item no índice e à posição lógica.
/// Tipo 3: `fwrite` direto (devolve o que ele devolver). Tipo 4: codifica o RLE byte a byte,
/// guardando a repetição em +0x18/+0x14 entre as chamadas; byte diferente fecha a repetição (1 com
/// byte <= 0x80 sai literal, senão o par 0x80 + n, byte); a 0x7f sai o par e recomeça. Devolve `quantos`.
unsafe extern "C" fn gravar_no_conteiner(buf: *const u8, tam: i32, quantos: i32, z: usize) -> i32 {
    let escrever: unsafe extern "C" fn(*const u8, i32, i32, usize) -> i32 = core::mem::transmute(0x945ce6usize);
    if z == 0 || zf_u(z, 4) != 1 {
        return 0;
    }
    let item = 0x29 + 0x10c * zf_u(z, 0xc) as usize;
    let total = tam.wrapping_mul(quantos);
    zf_por(z, item, zf_u(z, item).wrapping_add(total));
    zf_por(z, 8, zf_u(z, 8).wrapping_add(total));
    if zf_u(z, 0x19) != 4 {
        crate::comparacao::ramo("save zwrite tipo 3");
        return escrever(buf, tam, quantos, zf_u(z, 0) as usize);
    }
    let repetido = (z + 0x18) as *mut u8;
    let mut k = 0i32;
    while k < total {
        let n = zf_u(z, 0x14);
        if n != 0 {
            let c = *repetido;
            if *buf.add(k as usize) == c {
                if n.wrapping_add(0x80) < 0xff {
                    zf_por(z, 0x14, n + 1);
                    k += 1;
                    continue;
                }
                // 0x7f cópias: sai o par e recomeça
                crate::comparacao::ramo("save zwrite par 0x7f");
                zf_soltar(z, (n as u8).wrapping_add(0x80));
                zf_soltar(z, *repetido);
            } else if n <= 1 && c <= 0x80 {
                zf_soltar(z, c);
            } else {
                let contagem = (n as u8).wrapping_add(0x80);
                zf_soltar(z, contagem);
                zf_soltar(z, *repetido);
            }
        }
        zf_por(z, 0x14, 1);
        *repetido = *buf.add(k as usize);
        k += 1;
    }
    quantos
}

// ponytail: grava no arquivo (buffer e fwrite) e muda o índice; não roda duas vezes. A prova do save
// compara o .qst tipo 4 gravado com e sem a leva.
unsafe extern "C" fn comparar_gravar_no_conteiner(buf: *const u8, tam: i32, quantos: i32, z: usize) -> i32 {
    orig::<unsafe extern "C" fn(*const u8, i32, i32, usize) -> i32>(563)(buf, tam, quantos, z)
}

/// { 0x932b00 } (cdecl, zipdir.cpp): `zclose(&z)`. Gravando: esvazia o buffer de escrita; se o item
/// tem tamanho, no tipo 4 fecha a repetição pendente direto no arquivo (literal ou par, como no
/// zwrite) e regrava cabeçalho + índice inteiros (0x416ec bytes) no começo (`fseek` 0). Lendo: zera
/// os cursores de leitura. Fecha o FILE, libera o ZFILE e zera o ponteiro.
unsafe extern "C" fn fechar_conteiner(zz: *mut usize) {
    let escrever: unsafe extern "C" fn(usize, u32, i32, usize) -> u32 = core::mem::transmute(0x945ce6usize);
    let buscar: unsafe extern "C" fn(usize, i32, i32) -> i32 = core::mem::transmute(0x946a22usize);
    let fechar: unsafe extern "C" fn(usize) -> i32 = core::mem::transmute(0x945a09usize);
    let liberar: unsafe extern "C" fn(usize) = core::mem::transmute(0x944c94usize);
    let z = *zz;
    if z == 0 {
        return;
    }
    crate::comparacao::ramo("save zclose");
    let f = || zf_u(z, 0) as usize;
    if zf_u(z, 4) == 1 {
        let n = zf_u(z, 0xa3189);
        if n > 0 {
            escrever(z + 0x72445, 1, n, f());
            zf_por(z, 0xa3189, 0);
        }
    } else {
        zf_por(z, 0xa318d, 0);
        zf_por(z, 0xa3185, 0);
    }
    if zf_u(z, 4) == 1 && zf_u(z, 0x29 + 0x10c * zf_u(z, 0xc) as usize) != 0 {
        let n = zf_u(z, 0x14);
        if zf_u(z, 0x19) == 4 && n != 0 {
            if n <= 1 && *((z + 0x18) as *const u8) <= 0x80 {
                escrever(z + 0x18, 1, 1, f());
            } else {
                let marca = (n as u8).wrapping_add(0x80);
                escrever(&marca as *const u8 as usize, 1, 1, f());
                escrever(z + 0x18, 1, 1, f());
            }
        }
        buscar(f(), 0, 0);
        escrever(z + 0x19, 0x416ec, 1, f());
    }
    fechar(f());
    zf_por(z, 0, 0);
    liberar(z);
    *zz = 0;
}

// ponytail: grava, fecha o arquivo e libera; efeito único. A prova do save compara o .qst gravado.
unsafe extern "C" fn comparar_fechar_conteiner(zz: *mut usize) {
    orig::<unsafe extern "C" fn(*mut usize)>(564)(zz)
}

// ---------- 217a leva: o fim das estatísticas da partida: o construtor (com a conferência do CD) e o destrutor (match_stats.cpp) ----------

/// { 0x729000 } (thiscall, ret 8, match_stats.cpp): o construtor das estatísticas da partida.
/// Confere o CD: entre as unidades (GetLogicalDriveStringsA, 200) a primeira de CD (GetDriveTypeA 5)
/// com "<raiz>cm0102.exe" (0x4c0aa0; nas outras fecha a busca, 0x4c0c10); sem ela, a caixa "Insert
/// CD" e tenta de novo, para sempre. Com `zip` e a carga do save (0x72aa80) pronto; senão o índice de
/// `n` entradas (+4, [this] com n × 12 bytes; sem memória, erro 0x62 e o jogo fecha), +0x1c = n, os
/// quatro cursores dos baldes (+8: k × n / 4) e o "match_stats_matches.tmp" (CM3_TEMP, "wb") com `n`
/// registros zerados de 0xd7a bytes (erro 0x71 sem abrir, 0x7e se a escrita falha), +0x18 = 0. O
/// registro local nasce e morre pelos iteradores de vetor do runtime (0x9463af/0x9462bb) como na
/// original. Devolve `this`.
unsafe extern "thiscall" fn montar_estatisticas_da_partida(estat: usize, zip: usize, n: i32) -> usize {
    crate::comparacao::ramo("estatisticas montar");
    let vetor: unsafe extern "stdcall" fn(usize, u32, u32, usize, usize) = core::mem::transmute(0x9463afusize);
    let fim_do_vetor: unsafe extern "stdcall" fn(usize, u32, u32, usize) = core::mem::transmute(0x9462bbusize);
    let unidades: unsafe extern "system" fn(u32, *mut u8) -> u32 = core::mem::transmute(*(0x9670f8 as *const usize));
    let tipo: unsafe extern "system" fn(usize) -> u32 = core::mem::transmute(*(0x967100 as *const usize));
    let formatar: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(0x944c9fusize);
    let procurar: unsafe extern "C" fn(usize, usize, u32) -> i32 = core::mem::transmute(0x4c0aa0usize);
    let fechar_busca: unsafe extern "C" fn(usize) -> i32 = core::mem::transmute(0x4c0c10usize);
    let texto: unsafe extern "C" fn(usize, usize, ...) -> i32 = core::mem::transmute(0x66f4e0usize);
    let caixa: unsafe extern "C" fn(usize, usize, u32) = core::mem::transmute(0x5e8290usize);
    let carregar: unsafe extern "thiscall" fn(usize, usize) -> u32 = core::mem::transmute(0x72aa80usize);
    let novo: unsafe extern "C" fn(u32) -> usize = core::mem::transmute(0x944cf1usize);
    let caminho: unsafe extern "C" fn(usize, usize) -> usize = core::mem::transmute(0x90bde0usize);
    let abrir: unsafe extern "C" fn(usize, usize) -> usize = core::mem::transmute(0x945b00usize);
    let escrever: unsafe extern "C" fn(usize, u32, u32, usize) -> u32 = core::mem::transmute(0x945ce6usize);
    let fechar: unsafe extern "C" fn(usize) -> i32 = core::mem::transmute(0x945a09usize);
    let d = |o: usize| (estat + o) as *mut i32;

    let mut registro = [0u8; 0xd7a];
    let r = registro.as_mut_ptr() as usize;
    vetor(r + 0x11f, 0x625, 2, 0x453c30, 0x453c10);

    // o exe de trabalho (cm0102-1080) vem sem a exigência do CD: o jne do tipo da unidade (0x729089)
    // virou nop e o test do achado (0x7290cb, 85 c0) virou xor (31 c0 no cm0102-1080; 33 c0 é a outra
    // codificação); a cópia lê os bytes do próprio exe
    let qualquer_unidade = *(0x729089 as *const u8) == 0x90;
    let sempre_achou = *(0x7290cb as *const u8) != 0x85; // o original tem `test eax, eax` (85 c0); qualquer outra coisa é patch sem CD (xor 31 c0 ou 33 c0)
    'cd: loop {
        // ponytail: o buffer nasce zerado; a original só leria lixo com mais de 200 bytes de unidades
        // (mais de 50 letras), impossível
        let mut lista = [0u8; 0x100];
        if unidades(200, lista.as_mut_ptr()) != 0 && lista[0] != 0 {
            let mut i = 0usize;
            loop {
                let raiz = lista.as_ptr() as usize + i;
                if qualquer_unidade || tipo(raiz) == 5 {
                    let mut nome = [0u8; 0x104];
                    let mut achado = [0u8; 0x114];
                    let nm = nome.as_mut_ptr() as usize;
                    formatar(nm, 0x987e00, raiz, 0x63u32, 0x6du32, 0x30u32, 0x31u32, 0x30u32, 0x32u32, 0x2eu32, 0x65u32, 0x78u32, 0x65u32);
                    let ach = achado.as_mut_ptr() as usize;
                    if procurar(nm, ach, 0) == 0 || sempre_achou {
                        break 'cd;
                    }
                    fechar_busca(ach);
                }
                // ponytail: a original anda com um i8 (passos de 4): só passaria de 127 com mais de 32 unidades
                i += 4;
                if lista[i] == 0 {
                    break;
                }
            }
        }
        let mut titulo = [0u8; 0x100];
        let mut msg = [0u8; 0x100];
        texto(titulo.as_mut_ptr() as usize, 0x987df4);
        texto(msg.as_mut_ptr() as usize, 0x987dc4);
        caixa(titulo.as_ptr() as usize, msg.as_ptr() as usize, 1);
    }

    if zip != 0 && carregar(estat, zip) != 0 {
        fim_do_vetor(r + 0x11f, 0x625, 2, 0x453c10);
        return estat;
    }
    *d(4) = n;
    let t = novo((n as u32).wrapping_mul(12));
    *(estat as *mut usize) = t;
    if t == 0 {
        erro_em(0xa17ba0, 0x62);
    }
    *d(0x1c) = n;
    let mut soma = 0i32;
    for k in 0..4 {
        *d(8 + 4 * k) = soma / 4;
        soma = soma.wrapping_add(n);
    }
    let f = abrir(caminho(0x987da0, 0xa17b88), 0x9a7f28);
    if f == 0 {
        aviso_em(0xa17ba0, 0x71);
    } else {
        core::ptr::write_bytes(r as *mut u8, 0, 0xd7a);
        let mut ok = true;
        let mut i = 0;
        while i < n {
            if escrever(r, 0xd7a, 1, f) != 1 {
                aviso_em(0xa17ba0, 0x7e);
                fechar(f);
                ok = false;
                break;
            }
            i += 1;
        }
        if ok {
            fechar(f);
            *d(0x18) = 0;
        }
    }
    fim_do_vetor(r + 0x11f, 0x625, 2, 0x453c10);
    estat
}

/// { 0x7293c0 } (thiscall, match_stats.cpp): o destrutor das estatísticas da partida: libera o índice
/// ([this]) e zera o ponteiro e a quantidade (+4).
unsafe extern "thiscall" fn desmontar_estatisticas_da_partida(estat: usize) {
    crate::comparacao::ramo("estatisticas desmontar");
    let liberar: unsafe extern "C" fn(usize) = core::mem::transmute(0x944c94usize);
    let t = *(estat as *const usize);
    if t != 0 {
        liberar(t);
        *(estat as *mut usize) = 0;
        *((estat + 4) as *mut u32) = 0;
    }
}

