// ---------- 200a leva: as telas da partida (9): a cópia do bloco do time e da linha do jogador e o placar ao vivo (match_screens.cpp) ----------

/// Copia de `s` para `d` os campos de `tam` bytes (1, 2 ou 4) de `ini` a `fim`, em ordem crescente, como a original.
unsafe fn copiar_campos(d: usize, s: usize, ini: usize, fim: usize, tam: usize) {
    let mut k = ini;
    while k < fim {
        match tam {
            1 => *((d + k) as *mut u8) = *((s + k) as *const u8),
            2 => core::ptr::write_unaligned((d + k) as *mut u16, core::ptr::read_unaligned((s + k) as *const u16)),
            _ => core::ptr::write_unaligned((d + k) as *mut u32, core::ptr::read_unaligned((s + k) as *const u32)),
        }
        k += tam;
    }
}

/// { 0x71dd70 } (thiscall, match_screens.cpp): copia o bloco do time da partida (0x625 bytes) campo a
/// campo: bytes 0..0x11, palavras 0x11..0x1f, os quatro vetores de 5 bytes e os bytes 0x33/0x34, as duas
/// listas de 11 palavras (0x35, 0x4b), as duplas 0x61/0x65, as palavras 0x69..0x71 e as 20 linhas de
/// jogador de 0x49 bytes (0x71df00). Devolve `this`.
unsafe extern "thiscall" fn atribuir_bloco_do_time(this: usize, src: usize) -> usize {
    copiar_campos(this, src, 0, 0x11, 1);
    copiar_campos(this, src, 0x11, 0x1f, 2);
    copiar_campos(this, src, 0x1f, 0x35, 1);
    copiar_campos(this, src, 0x35, 0x61, 2);
    copiar_campos(this, src, 0x61, 0x69, 4);
    copiar_campos(this, src, 0x69, 0x71, 2);
    let linha: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(0x71df00usize);
    for i in 0..20 {
        linha(this + 0x71 + i * 0x49, src + 0x71 + i * 0x49);
    }
    this
}

unsafe extern "thiscall" fn comparar_atribuir_bloco_do_time(this: usize, src: usize) -> usize {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize) -> usize>(472);
    let (r, n, igual, _, _) = crate::comparacao::lado_a_lado(&[(this, 0x625)], || o(this, src), || atribuir_bloco_do_time(this, src));
    PLACAR.registrar(igual && r == n, || format!("atribuir_bloco_do_time({:#x} <- {:#x}): igual {} devolve {:#x}/{:#x}", this, src, igual, r, n));
    r
}

/// { 0x71df00 } (thiscall, match_screens.cpp): copia a linha de jogador do bloco do time (0x49 bytes):
/// duplas 0..0x14, a data em +0x14 pela Date::operator= (0x417c10, com o retorno numa local), bytes
/// 0x1c..0x36, palavras 0x36..0x3e e bytes 0x3e..0x49. Devolve `this`.
unsafe extern "thiscall" fn atribuir_linha_do_jogador(this: usize, src: usize) -> usize {
    copiar_campos(this, src, 0, 0x14, 4);
    let atribuir_data: unsafe extern "thiscall" fn(usize, *mut [u8; 8], usize) -> usize = core::mem::transmute(0x417c10usize);
    let mut volta = [0u8; 8];
    atribuir_data(this + 0x14, &mut volta, src + 0x14);
    copiar_campos(this, src, 0x1c, 0x36, 1);
    copiar_campos(this, src, 0x36, 0x3e, 2);
    copiar_campos(this, src, 0x3e, 0x49, 1);
    this
}

unsafe extern "thiscall" fn comparar_atribuir_linha_do_jogador(this: usize, src: usize) -> usize {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize) -> usize>(473);
    let (r, n, igual, _, _) = crate::comparacao::lado_a_lado(&[(this, 0x49)], || o(this, src), || atribuir_linha_do_jogador(this, src));
    PLACAR.registrar(igual && r == n, || format!("atribuir_linha_do_jogador({:#x} <- {:#x}): igual {} devolve {:#x}/{:#x}", this, src, igual, r, n));
    r
}

/// { 0x728e90 } (cdecl, match_screens.cpp): conta no resultado `res` os gols da partida `indice` do dia
/// ([[0xb67a50]+0x19] + 0x69 x indice + 0x5f; lances de 4 bytes a partir de +0x57, até 50 ou lado 0xff)
/// até o minuto atual da partida `partida` ([[partida+0x5f]+0x4d], 16 bits com sinal; sem partida ao vivo,
/// [partida+0x67] = 0xff ou [partida+0x5f] nulo, não conta nada). Tipo 1/3: gol do lado (0 vai a +0x43,
/// senão +0x44); 2: gol contra (invertido); 7: gol nos pênaltis (+0x49/+0x4a, que começam em 0xff e vão
/// a 1 no primeiro); 8 e os outros: nada. Zera antes +0x43..+0x46 e +0x4b/+0x4c. Resultado ou partida
/// nulos: nada.
unsafe extern "C" fn contar_placar_ao_vivo(partida: usize, indice: u32, res: usize) {
    if res == 0 || partida == 0 {
        return;
    }
    let b = |k: usize| (res + k) as *mut u8;
    for k in [0x43, 0x44, 0x4b, 0x4c] {
        *b(k) = 0;
    }
    *b(0x49) = 0xff;
    *b(0x4a) = 0xff;
    *b(0x46) = 0;
    *b(0x45) = 0;
    let dia = core::ptr::read_unaligned((*(0xb67a50 as *const usize) + 0x19) as *const u32);
    let jogo = core::ptr::read_unaligned(dia.wrapping_add(indice.wrapping_mul(0x69)).wrapping_add(0x5f) as usize as *const usize);
    if jogo == 0 {
        return;
    }
    let mut lance = jogo + 0x59;
    for _ in 0..0x32 {
        let lado = *((lance - 2) as *const u8);
        if lado == 0xff {
            break;
        }
        let ao_vivo = core::ptr::read_unaligned((partida + 0x5f) as *const usize);
        if *((partida + 0x67) as *const u8) != 0xff
            && ao_vivo != 0
            && *((lance + 1) as *const u8) as i16 <= core::ptr::read_unaligned((ao_vivo + 0x4d) as *const i16)
        {
            let tipo = *(lance as *const u8);
            let campo = match tipo {
                1 | 3 => Some(if lado == 0 { 0x43 } else { 0x44 }),
                2 => Some(if lado == 0 { 0x44 } else { 0x43 }),
                _ => None,
            };
            if let Some(k) = campo {
                *b(k) = (*b(k)).wrapping_add(1);
            } else if tipo == 7 {
                let k = if lado == 0 { 0x49 } else { 0x4a };
                *b(k) = if *b(k) == 0xff { 1 } else { *b(k) + 1 };
            }
        }
        lance += 4;
    }
}

unsafe extern "C" fn comparar_contar_placar_ao_vivo(partida: usize, indice: u32, res: usize) {
    let o = orig::<unsafe extern "C" fn(usize, u32, usize)>(474);
    if res == 0 {
        return o(partida, indice, res);
    }
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado(&[(res + 0x43, 0xa)], || o(partida, indice, res), || contar_placar_ao_vivo(partida, indice, res));
    PLACAR.registrar(igual, || format!("contar_placar_ao_vivo(partida {:#x}, indice {}): {:02x?} / {:02x?}", partida, indice, mo.0, mr.0));
}

// ---------- 199a leva: as estatísticas da partida: a estatística de liga do jogador, a entrada do jogo e o balde do registro (player_stats.cpp, match_stats.cpp) ----------

/// { 0x7c47b0 } (thiscall, ret 8, player_stats.cpp): a estatística de liga do jogador no clube, como
/// float (fild): campo 1 as partidas (palavra +0x20) e campo 2 os gols (palavra +0x22) do registro de
/// 39 bytes em [this+0x30] + id × 39. Jogador nulo ou outro campo: a original (caixa de erro).
unsafe extern "thiscall" fn estatistica_da_liga_do_jogador(estat: usize, jogador: usize, campo: i8) -> f32 {
    if jogador == 0 || !(1..=2).contains(&campo) {
        return orig::<unsafe extern "thiscall" fn(usize, usize, i8) -> f32>(469)(estat, jogador, campo);
    }
    let registro = (*((estat + 0x30) as *const usize) as isize + *(jogador as *const i32) as isize * 39) as usize;
    let deslocamento = if campo == 1 { 0x20 } else { 0x22 };
    core::ptr::read_unaligned((registro + deslocamento) as *const i16) as f32
}

/// { 0x729500 } (thiscall, ret 0x14, match_stats.cpp): a entrada `k` (12 bytes em [this]) tem os dois
/// clubes em qualquer ordem (+0/+4) e as datas (+8/+0xa, palavras) dadas? Índice −1: não; abaixo de −1
/// ou além de [this+0x1c]: a original (caixa de erro).
unsafe extern "thiscall" fn entrada_do_jogo_bate(estat: usize, k: i32, a: i32, b: i32, data_a: i16, data_b: i16) -> i32 {
    if k < -1 || k > (*((estat + 0x1c) as *const i32)).wrapping_sub(1) {
        return orig::<unsafe extern "thiscall" fn(usize, i32, i32, i32, i16, i16) -> i32>(470)(estat, k, a, b, data_a, data_b);
    }
    if k == -1 {
        return 0;
    }
    let e = (*(estat as *const usize) as isize + k as isize * 12) as usize;
    let d = |o: usize| *((e + o) as *const i32);
    let w = |o: usize| *((e + o) as *const i16);
    let clubes = (d(0) == a && d(4) == b) || (d(0) == b && d(4) == a);
    (clubes && w(8) == data_a && w(0xa) == data_b) as i32
}

/// { 0x729bd0 } (stdcall, ret 8, match_stats.cpp): o balde (0..3) do registro de estatística do jogo:
/// 0 se um dos clubes (+0x1c/+0x20) tem a ficha ([+0xcf]) entre as 16 últimas da base com +0x5f; 3 se o
/// registro tem +0x4c e [0xa5a390]; sem +0x40, 3 se o tipo (+0x3a) é 1, senão 2; com +0x40 e clube de
/// seleção (0x53b900): 0 se a palavra +0x80 do clube passa de 4999 ou de 0x157b, senão 2; senão pelo tipo
/// (tabela de saltos em 0x729d38) e as tabelas de bytes do exe em 0x729d64 e 0x729d94.
unsafe extern "stdcall" fn balde_do_registro(jogo: usize, registro: usize) -> u8 {
    let limite = *(0xae2364 as *const i32);
    for o in [0x1c, 0x20] {
        let p = core::ptr::read_unaligned((*((jogo + o) as *const usize) + 0xcf) as *const usize);
        if p != 0 {
            let id = *(p as *const i32);
            if id >= limite.wrapping_sub(0x10) && id < limite && *((p + 0x5f) as *const u8) != 0 {
                return 0;
            }
        }
    }
    if *((registro + 0x4c) as *const u8) != 0 && *(0xa5a390 as *const u8) != 0 {
        return 3;
    }
    if *((jogo + 0x40) as *const u8) == 0 {
        return (*((jogo + 0x3a) as *const u8) == 1) as u8 + 2;
    }
    let selecao: unsafe extern "C" fn(usize) -> u32 = core::mem::transmute(0x53b900usize);
    if selecao(*((jogo + 0x1c) as *const usize)) != 0 {
        if *((jogo + 0x40) as *const u8) == 0 {
            return 2;
        }
        let v = core::ptr::read_unaligned((*((jogo + 0x1c) as *const usize) + 0x80) as *const i16);
        return if v as i32 * 2 >= 10000 || v >= 0x157c { 0 } else { 2 };
    }
    let w = |o: usize| core::ptr::read_unaligned((jogo + o) as *const i16) as i32;
    // ponytail: as duas tabelas de bytes dos saltos são lidas do próprio exe (o desvio só troca o começo da rotina)
    let tabela = |end: usize, i: i32| *((end + i as usize) as *const u8);
    match (*((jogo + 0x3a) as *const i8) as i32).wrapping_sub(1) {
        0 => 3,
        4 | 8 => 1,
        5 => {
            let c = w(0x30);
            if c as u32 > 0x9b {
                return 1;
            }
            match tabela(0x729d94, c) {
                0 => 0,
                1 => (core::ptr::read_unaligned((*((jogo + 0x14) as *const usize) + 0x69) as *const i16) <= 0xc) as u8,
                _ => 1,
            }
        }
        7 => {
            if (0x41f..=0x426).contains(&w(0x32)) {
                return 0;
            }
            let c = w(0x30) - 0x78;
            if c as u32 > 0x23 { 1 } else { (tabela(0x729d64, c) != 0) as u8 }
        }
        _ => {
            let n = *((*((jogo + 0x14) as *const usize) + 0x69) as *const i8);
            if n > 0xd { 1 } else { (n <= 6) as u8 + 2 }
        }
    }
}

unsafe extern "thiscall" fn comparar_estatistica_da_liga_do_jogador(estat: usize, jogador: usize, campo: i8) -> f32 {
    let r = orig::<unsafe extern "thiscall" fn(usize, usize, i8) -> f32>(469)(estat, jogador, campo);
    if jogador == 0 || !(1..=2).contains(&campo) {
        return r;
    }
    let n = estatistica_da_liga_do_jogador(estat, jogador, campo);
    PLACAR.registrar(r.to_bits() == n.to_bits(), || format!("estatistica_da_liga_do_jogador({}) original={} rust={}", campo, r, n));
    r
}

unsafe extern "thiscall" fn comparar_entrada_do_jogo_bate(estat: usize, k: i32, a: i32, b: i32, data_a: i16, data_b: i16) -> i32 {
    let o = orig::<unsafe extern "thiscall" fn(usize, i32, i32, i32, i16, i16) -> i32>(470);
    if k < -1 || k > (*((estat + 0x1c) as *const i32)).wrapping_sub(1) {
        return o(estat, k, a, b, data_a, data_b);
    }
    let r = o(estat, k, a, b, data_a, data_b);
    let n = entrada_do_jogo_bate(estat, k, a, b, data_a, data_b);
    PLACAR.registrar(r == n, || format!("entrada_do_jogo_bate({}, {}, {}, {}, {}) original={} rust={}", k, a, b, data_a, data_b, r, n));
    r
}

unsafe extern "stdcall" fn comparar_balde_do_registro(jogo: usize, registro: usize) -> u8 {
    let r = orig::<unsafe extern "stdcall" fn(usize, usize) -> u8>(471)(jogo, registro);
    let n = balde_do_registro(jogo, registro);
    PLACAR.registrar(r == n, || format!("balde_do_registro original={} rust={}", r, n));
    r
}

// ---------- 198a leva: as telas da partida (6): a tela dos jogos do dia e o capitão padrão (match_screens.cpp) ----------

/// { 0x717cc0 } (cdecl, match_screens.cpp): abre a tela dos jogos do dia na vaga `vaga` (0x7fe4a0 com a
/// montagem 0x717db0 e a resposta 0x718930, sem fechamento) e grava os parâmetros dela (0x7ff130): 1 o
/// grupo de jogos, 2 e 3 zero, 4 um. Grupo nulo: a original (caixa de erro e [0xb67a34] = 0).
unsafe extern "C" fn abrir_jogos_do_dia(vaga: u32, grupo: usize) {
    if grupo == 0 {
        return orig::<unsafe extern "C" fn(u32, usize)>(466)(vaga, grupo);
    }
    crate::comparacao::ramo("telas abrir os jogos do dia");
    let abrir: unsafe extern "thiscall" fn(usize, u32, usize, usize, u32, usize, u32) -> u32 = core::mem::transmute(0x7fe4a0usize);
    if abrir(GERENTE_DE_TELAS, vaga, 0x717db0, 0x718930, 0, 0, 0) == 0 {
        return;
    }
    let gravar: unsafe extern "thiscall" fn(usize, u32, u32, usize, u32) = core::mem::transmute(0x7ff130usize);
    for (k, v) in [(1u32, grupo), (2, 0), (3, 0), (4, 1)] {
        gravar(GERENTE_DE_TELAS, vaga, k, v, 0);
    }
}

/// { 0x718930 } (cdecl, match_screens.cpp): a resposta da tela dos jogos do dia ao item `item` (−1 =
/// nenhum). Com item: o parâmetro 2 recebe 0x803320 do parâmetro 3. Pelo id do item (0 vira o padrão
/// [0xdd6bde]): 1 abre outro grupo de jogos (0x717cc0 na vaga [0xb74c26] do humano da vez com o dado
/// +0xba9a6 do item) e 2 o andamento da competição (0x49b830 com o dado), ambos −11; senão a barra de
/// menu (0x7615d0, senão 0x7643d0). O item vai inteiro (32 bits) para a barra, como na original.
unsafe extern "C" fn responder_jogos_do_dia(item: u32) -> i32 {
    crate::comparacao::ramo("telas responder aos jogos do dia");
    let i = item as i16;
    let id = |i: i16| if i == -1 { *(0xdd6bde as *const u16) } else { id_do_item(i) };
    let dado = |i: i16| {
        if i == -1 {
            return 0usize;
        }
        let display = *((0xb74c4c + *(0xb77c7a as *const i16) as isize * 0x300) as *const usize);
        core::ptr::read_unaligned((display as isize + i as isize * 0x18c + 0xba9a6) as *const usize)
    };
    if i != -1 {
        let converter: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(0x803320usize);
        gravar_parametro_da_tela(2, converter(GERENTE_DE_TELAS, parametro_da_tela(3)));
    }
    match id(i) {
        1 => {
            let vaga = *((0xb74c26 + *(0xb77c7a as *const i16) as isize * 0x300) as *const u32);
            let abrir: unsafe extern "C" fn(u32, usize) = core::mem::transmute(0x717cc0usize);
            abrir(vaga, dado(i));
            -11
        }
        2 => {
            let andamento: unsafe extern "C" fn(usize) = core::mem::transmute(0x49b830usize);
            andamento(dado(i));
            -11
        }
        _ => {
            let comando: unsafe extern "C" fn(u32) -> i32 = core::mem::transmute(0x7615d0usize);
            let r = comando(item);
            if r != 0 {
                return r;
            }
            let ligacao: unsafe extern "C" fn(u32) -> i32 = core::mem::transmute(0x7643d0usize);
            ligacao(item)
        }
    }
}

/// { 0x727e20 } (cdecl, match_screens.cpp): a vaga (0..10) dos onze da tática `tatica` com a maior nota
/// da comissão (0x8968f0 em [0xde1d08] com `contexto`, nota 0x6e1cf0(pessoa, 0, tatica), comparação i16;
/// no empate fica a primeira), o capitão padrão; −1 (0xff) sem ninguém. Tática nula: a original (caixa
/// de erro). Quem chama só usa `al`.
unsafe extern "C" fn vaga_do_mais_bem_avaliado(tatica: usize, contexto: i32) -> u8 {
    if tatica == 0 {
        return orig::<unsafe extern "C" fn(usize, i32) -> u8>(468)(tatica, contexto);
    }
    let da_tatica: unsafe extern "thiscall" fn(usize, usize, u32, i32) -> usize = core::mem::transmute(0x8968f0usize);
    let avaliar: unsafe extern "C" fn(usize, usize, usize) -> i16 = core::mem::transmute(0x6e1cf0usize);
    let mut vaga = 0xffu8;
    let mut melhor = 0i16;
    for k in 0..11u32 {
        let p = da_tatica(*(0xde1d08 as *const usize), tatica, k, contexto);
        if p != 0 {
            let n = avaliar(p, 0, tatica);
            if vaga == 0xff || n > melhor {
                vaga = k as u8;
                melhor = n;
            }
        }
    }
    vaga
}

