// ---------- 181a leva: as notícias do jogador na mídia e a importância da partida de copa ----------

/// O registro de notícias da mídia (`this`: +0 os registros de 0x17 bytes, +8 quantos): algum com o
/// jogador em +8 que `aceita`?
unsafe fn alguma_noticia(midia: usize, id: i32, aceita: impl Fn(usize) -> bool) -> bool {
    let n = *((midia + 8) as *const i32);
    let base = *(midia as *const usize);
    (0..n.max(0) as usize).any(|k| {
        let r = base + k * 0x17;
        core::ptr::read_unaligned((r + 8) as *const i32) == id && aceita(r)
    })
}

/// { 0x735780 } (thiscall, ret 4, media.cpp): o jogador `*id` tem uma notícia com a resposta 2 (+0x10)?
unsafe extern "thiscall" fn noticia_com_resposta_2(midia: usize, id: *const i32) -> u32 {
    alguma_noticia(midia, *id, |r| *((r + 0x10) as *const u8) == 2) as u32
}

/// { 0x735840 } (thiscall, ret 4, media.cpp): o jogador `*id` tem alguma notícia? Devolve só `al`.
unsafe extern "thiscall" fn tem_noticia(midia: usize, id: *const i32) -> u8 {
    alguma_noticia(midia, *id, |_| true) as u8
}

/// { 0x5221f0 } (thiscall, ret 0xc, Cup.cpp): a importância da partida da copa (a fase +0x34 da
/// partida menos +0x3c mais +0x51 da copa, pelo menos 1) e em `margem` a diferença do placar da ida
/// (+0x4b/+0x4c, 0xff sem ida) para o lado `segundo`, mais 1 (0xff abaixo de 1). Devolve só `al`.
unsafe extern "thiscall" fn importancia_da_partida(copa: usize, partida: usize, segundo: u8, margem: *mut u8) -> u8 {
    let b = |p: usize, o: usize| *((p + o) as *const u8);
    let mut al = b(partida, 0x34).wrapping_sub(b(copa, 0x3c)).wrapping_add(b(copa, 0x51));
    if (al as i8) < 1 {
        al = 1;
    }
    let ida = b(partida, 0x4b);
    if ida != 0xff {
        let volta = b(partida, 0x4c);
        *margem = if segundo == 0 { volta.wrapping_sub(ida) } else { ida.wrapping_sub(volta) }.wrapping_add(1);
        if (*margem as i8) < 1 {
            *margem = 0xff;
        }
    }
    al
}

unsafe extern "thiscall" fn comparar_noticia_com_resposta_2(midia: usize, id: *const i32) -> u32 {
    let r = orig::<unsafe extern "thiscall" fn(usize, *const i32) -> u32>(415)(midia, id);
    let n = noticia_com_resposta_2(midia, id);
    PLACAR.registrar(r == n, || format!("noticia_com_resposta_2({}) original={} rust={}", *id, r, n));
    r
}

unsafe extern "thiscall" fn comparar_tem_noticia(midia: usize, id: *const i32) -> u8 {
    let r = orig::<unsafe extern "thiscall" fn(usize, *const i32) -> u8>(416)(midia, id);
    let n = tem_noticia(midia, id);
    PLACAR.registrar(r == n, || format!("tem_noticia({}) original={} rust={}", *id, r, n));
    r
}

unsafe extern "thiscall" fn comparar_importancia_da_partida(copa: usize, partida: usize, segundo: u8, margem: *mut u8) -> u8 {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize, u8, *mut u8) -> u8>(417);
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado(&[(margem as usize, 1)], || o(copa, partida, segundo, margem), || importancia_da_partida(copa, partida, segundo, margem));
    PLACAR.registrar(igual && r == n, || format!("importancia_da_partida(lado {}) original={} rust={} {:x?} x {:x?}", segundo, r, n, mo, mr));
    r
}

// ---------- 180a leva: as telas da partida (1): o rótulo do controle, fechar a tela e a espera (match_screens.cpp) ----------

/// { 0x725a70 } (cdecl, match_screens.cpp): o rótulo do botão de controle da partida para o estado
/// `estado` (1 esperando, 2 começar, 3 recomeçar, 4 pausar/retomar, 5 continuar ou esperar os
/// jogadores) em `saida` pela 0x66f4e0 (o texto passa pelo idioma), com as marcas 0x1021 (mais 0x40
/// quando o botão fica desligado). Sem partida, sem saída, com menos de 100 bytes ou estado fora: a
/// original (caixa de erro). Devolve 1.
unsafe extern "C" fn rotulo_do_controle(estado: u8, m: usize, saida: *mut u8, tam: i32, marcas: *mut u32) -> u32 {
    let o = orig::<unsafe extern "C" fn(u8, usize, *mut u8, i32, *mut u32) -> u32>(412);
    if m == 0 || saida.is_null() || tam < 100 || !(1..=5).contains(&estado) {
        return o(estado, m, saida, tam, marcas);
    }
    let texto: unsafe extern "C" fn(*mut u8, usize, ...) -> i32 = core::mem::transmute(0x66f4e0usize);
    *saida = 0;
    *marcas = 0x1021;
    let humano = *(0xb77c7a as *const i16) as isize;
    let (formato, desligado) = match estado {
        1 => (0xa16d8c, false),
        2 => (0xa16d7c, false),
        3 => (0xa16d6c, false),
        4 => {
            if core::ptr::read_unaligned((m as isize + 0xc5 + 4 * humano) as *const u32) != 0 {
                (0xa16d5c, false)
            } else if *((m + 0x108) as *const u8) != 0 {
                (0xa16d54, true)
            } else {
                (0xa16d48, false)
            }
        }
        _ => {
            let esperando: unsafe extern "thiscall" fn(usize, u32) -> u32 = core::mem::transmute(0x7ffe40usize);
            let jogador = *((0xb74c26 + humano * 0x300) as *const u32);
            if esperando(0xb74450, jogador) != 0 { (0xa16d34, true) } else { (0xa16d24, false) }
        }
    };
    crate::comparacao::ramo("telas rotulo do controle");
    texto(saida, formato);
    if desligado {
        *marcas |= 0x40;
    }
    1
}

/// { 0x71b120 } (cdecl, match_screens.cpp): fecha a tela da partida: os parâmetros 0x2d e 0x1d do
/// gerente de telas [0xb74450] (0x7ff010), se houver, são destruídos (0x5a8f60 e 0x453bc0), liberados
/// (0x944c94) e zerados (0x7ff270).
unsafe extern "C" fn fechar_tela_da_partida() {
    crate::comparacao::ramo("telas fechar a partida");
    let ler: unsafe extern "thiscall" fn(usize, u32) -> usize = core::mem::transmute(0x7ff010usize);
    let gravar: unsafe extern "thiscall" fn(usize, u32, usize, u32) = core::mem::transmute(0x7ff270usize);
    let liberar: unsafe extern "C" fn(usize) = core::mem::transmute(0x944c94usize);
    for (k, destrutor) in [(0x2du32, 0x5a8f60usize), (0x1d, 0x453bc0)] {
        if ler(0xb74450, k) == 0 {
            continue;
        }
        let p = ler(0xb74450, k);
        if p != 0 {
            let destruir: unsafe extern "thiscall" fn(usize) = core::mem::transmute(destrutor);
            destruir(p);
            liberar(p);
        }
        gravar(0xb74450, k, 0, 0);
    }
}

/// { 0x727f00 } (cdecl, match_screens.cpp): abre a tela de espera na vaga `vaga` do gerente de telas
/// (0x7fe4a0 com o desenho 0x727fa0 e a resposta 0x727fb0). Vaga 0: a original (caixa de erro).
unsafe extern "C" fn abrir_tela_de_espera(vaga: u32) {
    if vaga == 0 {
        return orig::<unsafe extern "C" fn(u32)>(414)(vaga);
    }
    crate::comparacao::ramo("telas abrir a espera");
    let abrir: unsafe extern "thiscall" fn(usize, u32, usize, usize, u32, u32, u32) = core::mem::transmute(0x7fe4a0usize);
    abrir(0xb74450, vaga, 0x727fa0, 0x727fb0, 0, 0, 0);
}

unsafe extern "C" fn comparar_rotulo_do_controle(estado: u8, m: usize, saida: *mut u8, tam: i32, marcas: *mut u32) -> u32 {
    let o = orig::<unsafe extern "C" fn(u8, usize, *mut u8, i32, *mut u32) -> u32>(412);
    if m == 0 || saida.is_null() || tam < 100 || marcas.is_null() {
        return o(estado, m, saida, tam, marcas);
    }
    let reg = [(saida as usize, tam.min(0x100) as usize), (marcas as usize, 4)];
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(estado, m, saida, tam, marcas), || rotulo_do_controle(estado, m, saida, tam, marcas));
    PLACAR.registrar(igual && r == n, || format!("rotulo_do_controle(estado {}) original={} rust={} {:x?} x {:x?}", estado, r, n, mo, mr));
    r
}

