// ---------- 174a leva: a pessoa na lista do tecnico, a ficha de contrato e o desgaste diario ----------

/// { 0x69fc60 } (thiscall, ret 4, manager_manager.cpp): a pessoa `*p` está na lista [this+8]
/// (palavra da quantidade em +0, iterador 0x68d1b0 com posição em +0xa, recomeçada de +2 e
/// devolvida no fim)? Lista que acaba antes da quantidade: a original (caixa de erro). Devolve só `al`.
unsafe extern "thiscall" fn pessoa_na_lista(t: usize, p: *const i32) -> u8 {
    let proximo: unsafe extern "thiscall" fn(usize) -> usize = core::mem::transmute(0x68d1b0usize);
    let lista = *((t + 8) as *const usize);
    let guardado = core::ptr::read_unaligned((lista + 0xa) as *const u32);
    core::ptr::write_unaligned((lista + 0xa) as *mut u32, core::ptr::read_unaligned((lista + 2) as *const u32));
    let mut i = 0i32;
    while i < *(lista as *const i16) as i32 {
        let e = proximo(lista);
        if e == 0 {
            core::ptr::write_unaligned((lista + 0xa) as *mut u32, guardado);
            return orig::<unsafe extern "thiscall" fn(usize, *const i32) -> u8>(394)(t, p);
        }
        if core::ptr::read_unaligned((e + 6) as *const i32) == *p {
            core::ptr::write_unaligned((lista + 0xa) as *mut u32, guardado);
            return 1;
        }
        i += 1;
    }
    core::ptr::write_unaligned((lista + 0xa) as *mut u32, guardado);
    0
}

/// { 0x4cf6d0 } (thiscall, ret 4, contract_manager.cpp): a ficha de contrato (0x50 bytes, a partir de
/// [this]) da pessoa `*p`, pelo índice em +4 do registro de 79 bytes em [0xae2d0c]; 0 sem pessoa, com
/// id fora de [0xae2364] ou índice negativo.
unsafe extern "thiscall" fn ficha_de_contrato(t: usize, p: *const i32) -> usize {
    if p.is_null() {
        return 0;
    }
    let id = *p;
    if id >= *(0xae2364 as *const i32) {
        return 0;
    }
    let k = core::ptr::read_unaligned((*(0xae2d0c as *const usize)).wrapping_add((id as usize).wrapping_mul(79)).wrapping_add(4) as *const i32);
    if k < 0 {
        return 0;
    }
    (*(t as *const usize)).wrapping_add(k as usize * 0x50)
}

/// { 0x62c2f0 } (thiscall, ret 4, injury.cpp): o desgaste do dia na palavra +0xc do registro de 31
/// bytes da pessoa `id` (a partir de [this]): abaixo de −1000 desce 1; abaixo de 19 anos (+0x18 da
/// pessoa em [0xae23bc]) e negativo, zera; senão, de −500 para cima e com idade ≥ sorteio(25), desce
/// 13, e nos outros casos desce sorteio(13); goleiro (posição +0xf da ficha = 20) fica até 1050.
/// Id fora de [0xae2364]: nada.
unsafe extern "thiscall" fn desgaste_diario(t: usize, id: i32) {
    if id >= *(0xae2364 as *const i32) {
        return;
    }
    let sorteio: unsafe extern "C" fn(i32) -> i32 = core::mem::transmute(0x90cfc0usize);
    let e = (*(t as *const usize)).wrapping_add((id as usize).wrapping_mul(31)).wrapping_add(0xc) as *mut i16;
    let v = core::ptr::read_unaligned(e);
    if v < -1000 {
        core::ptr::write_unaligned(e, v.wrapping_sub(1));
    }
    let p = (*(0xae23bc as *const usize)).wrapping_add((id as usize).wrapping_mul(0x6e));
    let idade = *((p + 0x18) as *const i8);
    if idade < 0x13 && core::ptr::read_unaligned(e) < 0 {
        core::ptr::write_unaligned(e, 0);
    } else if core::ptr::read_unaligned(e) >= -500 && idade as i32 >= sorteio(0x19) {
        core::ptr::write_unaligned(e, core::ptr::read_unaligned(e).wrapping_sub(0xd));
    } else {
        let r = sorteio(0xd) as i16;
        core::ptr::write_unaligned(e, core::ptr::read_unaligned(e).wrapping_sub(r));
    }
    let ficha = core::ptr::read_unaligned((p + 0x61) as *const usize);
    if ficha != 0 && *((ficha + 0xf) as *const u8) == 0x14 && core::ptr::read_unaligned(e) >= 0x41a {
        core::ptr::write_unaligned(e, 0x41a);
    }
}

comparar_valor!(comparar_pessoa_na_lista, pessoa_na_lista, 394, (p: *const i32) -> u8);
comparar_valor!(comparar_ficha_de_contrato, ficha_de_contrato, 395, (p: *const i32) -> usize);

unsafe extern "thiscall" fn comparar_desgaste_diario(t: usize, id: i32) {
    let o = orig::<unsafe extern "thiscall" fn(usize, i32)>(396);
    let mut reg = crate::aleatorio::REGIOES_DO_ESTADO.to_vec();
    if id < *(0xae2364 as *const i32) {
        reg.push(((*(t as *const usize)).wrapping_add((id as usize).wrapping_mul(31)).wrapping_add(0xc), 2));
    }
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(t, id), || crate::aleatorio::sem_contar(|| desgaste_diario(t, id)));
    PLACAR.registrar(igual, || format!("desgaste_diario({:#x}, {}) {:x?} x {:x?}", t, id, mo, mr));
}

// ---------- 173a leva: o fechamento do motor (7): a regra do elenco e as notas do jogador (match_man.cpp) ----------

/// { 0x6e8910 } (cdecl, match_man.cpp): cumpre a `regra` do elenco (byte 0: 1 estrangeiro de fora da
/// comunidade, 2 estrangeiro, 3 acima da idade em +1; +2 máximo em campo, +3 máximo no banco, +4 e +5
/// o permitido e o atual) na escalação do `clube` (nação +0x53; 0x53d980/0x53d740): tira os restritos
/// da lista de reserva (`reserva`, `nr`); se há mais restritos em campo que o máximo (+2), escolhe entre
/// os titulares restritos e os candidatos (banco não restrito + reserva) pela 0x6e2000 e troca, um a
/// um, o de menor perda na nota (0x6e2f20), refazendo o banco (0x6e2000) se um titular saiu dele;
/// depois faz o mesmo no banco (`saida` + `nt`) com o máximo +3 (ou +4 − +5).
#[allow(clippy::too_many_arguments)]
unsafe extern "C" fn cumprir_regra_do_elenco(
    clube: usize, tecnico: usize, regra: usize, modo: u32, nt: u32, nb: u32, nr: u32, titulares: usize, banco: usize, reserva: usize,
    saida: usize, codigos: usize, curtos: usize, marcas: usize, bytes: usize, lado: usize,
) {
    let r = |k: usize| *((regra + k) as *const i8);
    if r(0) == 0 || r(5) >= r(4) {
        return;
    }
    let escalar: Escalar = core::mem::transmute(0x6e2000usize);
    let nota: unsafe extern "C" fn(usize, usize, usize, u32, u32, usize, usize, u32, u32, u32, u32, u32, u32, u32, u32) -> i32 =
        core::mem::transmute(0x6e2f20usize);
    let restrito = |p: usize| -> bool {
        let estrangeiro: unsafe extern "C" fn(usize, u32, u32) -> u32 = core::mem::transmute(0x53d980usize);
        let comunitario: unsafe extern "C" fn(usize, u32) -> u32 = core::mem::transmute(0x53d740usize);
        let nacao = *((clube + 0x53) as *const u32);
        match r(0) {
            1 => p != 0 && estrangeiro(p, nacao, 1) != 0 && comunitario(p, nacao) == 0,
            2 => p != 0 && estrangeiro(p, nacao, 1) != 0,
            3 => p != 0 && r(1) < *((p + 0x18) as *const i8),
            _ => false,
        }
    };
    let (nt, nb) = (nt as u8 as i8, nb as u8 as i8);
    let mut nr = nr as u8 as i8;
    let res = |k: i8| (reserva as isize + 4 * k as isize) as *mut usize;
    let sai = |k: i32| (saida as isize + 4 * k as isize) as *mut usize;
    let w = |base: usize, k: i32| *((base as isize + 2 * k as isize) as *const u16);
    // tira `alvo` (ou a posição `k`) da reserva, pondo o último no lugar
    let tirar = |k: i8, nr: &mut i8| {
        if (k as i32) < *nr as i32 - 1 {
            *res(k) = *res(*nr - 1);
            *res(*nr - 1) = 0;
        } else {
            *res(k) = 0;
        }
        *nr -= 1;
    };
    let tirar_alvo = |alvo: usize, nr: &mut i8| {
        let mut k = 0i8;
        if 0 < *nr {
            loop {
                if *res(k) == alvo {
                    tirar(k, nr);
                    break;
                }
                k += 1;
                if k >= *nr {
                    break;
                }
            }
        }
    };
    let marca = if lado != 0 { *((*((lado + 0x2b) as *const usize) + 0x584) as *const u32) } else { 0 };
    let mut k = 0i8;
    if 0 < nr {
        loop {
            if reserva == 0 {
                break;
            }
            if restrito(*res(k)) {
                let ultimo = (k as i32) < nr as i32 - 1;
                tirar(k, &mut nr);
                if ultimo {
                    k -= 1;
                }
            }
            k += 1;
            if k >= nr {
                break;
            }
        }
    }
    let mut vaga = [0i8; 52];
    let mut cod = [0u16; 50];
    let mut cod2 = [0u16; 50];
    let mut m8 = [0u32; 100];
    let mut b1 = [0u8; 52];
    let mut cand = [0usize; 50];
    let mut escolha = [0usize; 50];
    let mut falta = r(5);
    if falta < r(2) {
        let mut trocas = r(2) - falta;
        falta = r(3);
        if trocas != 0 {
            let mut nv = 0i8;
            let mut k = 0i8;
            while k < nt {
                if restrito(*((titulares + 4 * k as usize) as *const usize)) {
                    let i = nv as usize;
                    vaga[i] = k;
                    cod[i] = w(codigos, k as i32);
                    cod2[i] = if curtos == 0 { 0 } else { w(curtos, k as i32) };
                    (m8[2 * i], m8[2 * i + 1]) = if marcas == 0 { (0, 0) } else { (*((marcas + 8 * k as usize) as *const u32), *((marcas + 8 * k as usize + 4) as *const u32)) };
                    b1[i] = if bytes == 0 { 0 } else { *((bytes + k as usize) as *const u8) };
                    nv += 1;
                }
                k += 1;
            }
            let mut nc = 0i8;
            for k in 0..nb.max(0) as usize {
                let q = *((banco + 4 * k) as *const usize);
                if q != 0 && !restrito(q) {
                    cand[nc as usize] = q;
                    nc += 1;
                }
            }
            let mut k = 0i8;
            if 0 < nr {
                loop {
                    if reserva == 0 {
                        break;
                    }
                    cand[nc as usize] = *res(k);
                    nc += 1;
                    k += 1;
                    if k >= nr {
                        break;
                    }
                }
            }
            if nc != 0 {
                escalar(cand.as_ptr() as usize, nc as u8 as u32, cod.as_ptr() as usize, nv as u8 as u32, 0, escolha.as_mut_ptr() as usize, modo, clube, lado,
                    tecnico as u32, 0, m8.as_ptr() as usize, b1.as_ptr() as usize, marca, cod2.as_ptr() as usize);
                let mut melhor = 0i32;
                let mut saiu_do_banco = false;
                loop {
                    if nv == 0 || nv < 1 {
                        break;
                    }
                    let mut esc = -1i32;
                    for k in 0..nv as usize {
                        if vaga[k] == -1 {
                            continue;
                        }
                        let atual = *sai(vaga[k] as i32);
                        if atual == 0 {
                            continue;
                        }
                        let valer = |p: usize| nota(p, *((p + 0x61) as *const usize), 0, cod[k] as u32, modo, clube, lado, tecnico as u32, u32::MAX,
                            m8[2 * k], m8[2 * k + 1], b1[k] as u32, marca, cod2[k] as u32, 0);
                        let a = valer(atual);
                        let b = if escolha[k] == 0 { -1000000 } else { valer(escolha[k]) };
                        if esc == -1 || a.wrapping_sub(b) < melhor {
                            melhor = a.wrapping_sub(b);
                            esc = k as i32;
                        }
                    }
                    if esc < 0 {
                        break;
                    }
                    let e = esc as usize;
                    *sai(vaga[e] as i32) = escolha[e];
                    tirar_alvo(escolha[e], &mut nr);
                    for k in 0..nb.max(0) as usize {
                        let q = (banco + 4 * k) as *mut usize;
                        if escolha[e] != 0 && *q == escolha[e] {
                            saiu_do_banco = true;
                            *q = 0;
                        }
                    }
                    vaga[e] = -1;
                    trocas -= 1;
                    if trocas == 0 {
                        break;
                    }
                }
                if saiu_do_banco {
                    let mut n = 0i8;
                    for k in 0..nb.max(0) as usize {
                        let q = *((banco + 4 * k) as *const usize);
                        if q != 0 {
                            escolha[n as usize] = q;
                            n += 1;
                        }
                    }
                    for k in 0..nr.max(0) {
                        if *res(k) != 0 {
                            escolha[n as usize] = *res(k);
                            n += 1;
                        }
                    }
                    if n != 0 {
                        escalar(escolha.as_ptr() as usize, n as u8 as u32, codigos + 2 * nt as isize as usize, nb as u8 as u32, 0, sai(nt as i32) as usize, modo,
                            clube, lado, tecnico as u32, 0, 0, 0, 0, curtos.wrapping_add(2 * nt as isize as usize));
                    }
                }
            }
        }
    } else {
        falta = r(4) - falta;
    }
    if falta == 0 {
        return;
    }
    let mut nv = 0i8;
    let mut k = 0i8;
    while k < nb {
        let j = nt as i32 + k as i32;
        if restrito(*sai(j)) {
            let i = nv as usize;
            cod[i] = w(codigos, j);
            cod2[i] = w(curtos, j);
            vaga[i] = k;
            nv += 1;
        }
        k += 1;
    }
    let mut nc = 0i8;
    let mut k = 0i8;
    if 0 < nr {
        loop {
            if reserva == 0 {
                break;
            }
            let q = *res(k);
            if !(0..nb.max(0) as i32).any(|j| q == *sai(j + nt as i32)) {
                cand[nc as usize] = q;
                nc += 1;
            }
            k += 1;
            if k >= nr {
                break;
            }
        }
        if nc != 0 {
            escalar(cand.as_ptr() as usize, nc as u8 as u32, cod.as_ptr() as usize, nv as u8 as u32, 0, escolha.as_mut_ptr() as usize, modo, clube, lado,
                tecnico as u32, 0, 0, 0, 0, cod2.as_ptr() as usize);
            let mut melhor = 0i32;
            loop {
                if nv == 0 || nv < 1 {
                    return;
                }
                let mut esc = -1i32;
                for k in 0..nv as usize {
                    if vaga[k] == -1 {
                        continue;
                    }
                    let atual = *sai(vaga[k] as i32 + nt as i32);
                    if atual == 0 {
                        continue;
                    }
                    let valer = |p: usize| nota(p, *((p + 0x61) as *const usize), 0, cod[k] as u32, modo, clube, lado, tecnico as u32, u32::MAX, 0, 0, 0, 0, cod2[k] as u32, 0);
                    let a = valer(atual);
                    let b = if escolha[k] == 0 { -1000000 } else { valer(escolha[k]) };
                    if esc == -1 || a.wrapping_sub(b) < melhor {
                        melhor = a.wrapping_sub(b);
                        esc = k as i32;
                    }
                }
                if esc < 0 {
                    return;
                }
                let e = esc as usize;
                *sai(vaga[e] as i32 + nt as i32) = escolha[e];
                tirar_alvo(escolha[e], &mut nr);
                vaga[e] = -1;
                falta -= 1;
                if falta == 0 {
                    break;
                }
            }
        }
    }
}

#[allow(clippy::too_many_arguments)]
unsafe extern "C" fn comparar_cumprir_regra_do_elenco(
    clube: usize, tecnico: usize, regra: usize, modo: u32, nt: u32, nb: u32, nr: u32, titulares: usize, banco: usize, reserva: usize,
    saida: usize, codigos: usize, curtos: usize, marcas: usize, bytes: usize, lado: usize,
) {
    let o = orig::<unsafe extern "C" fn(usize, usize, usize, u32, u32, u32, u32, usize, usize, usize, usize, usize, usize, usize, usize, usize)>(391);
    if gravando_no_topo() {
        return o(clube, tecnico, regra, modo, nt, nb, nr, titulares, banco, reserva, saida, codigos, curtos, marcas, bytes, lado);
    }
    let n = |v: u32| (v as u8 as i8).max(0) as usize;
    let mut reg = crate::aleatorio::REGIOES_DO_ESTADO.to_vec();
    reg.push((saida, 4 * (n(nt) + n(nb))));
    if banco != 0 {
        reg.push((banco, 4 * n(nb)));
    }
    if reserva != 0 {
        reg.push((reserva, 4 * n(nr)));
    }
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado(
        &reg,
        || o(clube, tecnico, regra, modo, nt, nb, nr, titulares, banco, reserva, saida, codigos, curtos, marcas, bytes, lado),
        || crate::aleatorio::sem_contar(|| cumprir_regra_do_elenco(clube, tecnico, regra, modo, nt, nb, nr, titulares, banco, reserva, saida, codigos, curtos, marcas, bytes, lado)),
    );
    PLACAR.registrar(igual, || format!("cumprir_regra_do_elenco(regra {:x?}) {:x?} x {:x?}", core::slice::from_raw_parts(regra as *const u8, 6), mo, mr));
}
// ---- as notas do jogador do match_man.cpp (0x6e6340 fora da partida, 0x6e2f20 para uma vaga): partes comuns ----

/// A data (dia +0, ano +2) de `a` vem antes da de `b`? (comparação do ano sem sinal, do dia com sinal)
unsafe fn data_antes(a: usize, b: usize) -> bool {
    let (aa, ab) = (*((a + 2) as *const u16), *((b + 2) as *const u16));
    aa < ab || (aa == ab && *(a as *const i16) < *(b as *const i16))
}

/// Os dias desde a data de `p` (+0x3e) até hoje ([0xae2c90]), contando 365 por ano.
unsafe fn dias_desde(p: usize) -> i32 {
    let anos = *(0xae2c92 as *const u16) as i32 - *((p + 0x40) as *const u16) as i32;
    anos * 365 - *((p + 0x3e) as *const i16) as i32 + *(0xae2c90 as *const i16) as i32
}

/// O observador `o` (+0x3e) chegou antes da data do jogador `p` (+0x3e) e esta data é de mais de um
/// ano atrás (0x54c8e0 com 365)?
unsafe fn observado_ha_mais_de_um_ano(o: usize, p: usize) -> bool {
    if !data_antes(o + 0x3e, p + 0x3e) {
        return false;
    }
    let datar: unsafe extern "thiscall" fn(usize, *mut [u8; 8], u32) -> *const [u8; 8] = core::mem::transmute(0x54c8e0usize);
    let mut d = [0u8; 8];
    let r = datar(0xae2c90, &mut d, 0x16d);
    data_antes(r as usize, p + 0x3e)
}

/// Byte com sinal em `p + k`.
unsafe fn sb(p: usize, k: usize) -> i32 {
    *((p + k) as *const i8) as i32
}

/// A 0x7c1e30 das notas ([0xb74350]) da ficha `f`.
unsafe fn nota_externa(f: usize, k: u32, c: u32, x: f32) -> f64 {
    let g: unsafe extern "thiscall" fn(usize, usize, u32, u32, f32) -> f64 = core::mem::transmute(0x7c1e30usize);
    g(*(0xb74350 as *const usize), f, k, c, x)
}

/// A nota da posição (máscara `m`) pelos atributos da ficha `f` na tabela `tab` (0xa15d50 ou
/// 0xa15cfc). A posição principal tem os casos de `m` igual a 8 ou 0x10 e a exceção de lateral
/// (0x800/0x80) na faixa 0x10; a secundária da 0x6e2f20 não.
unsafe fn nota_da_posicao(f: usize, m: u32, masc: u32, tab: usize, principal: bool) -> i32 {
    let fb = |k: usize| sb(f, k);
    let t = |k: i32| *((tab as isize + 4 * k as isize) as *const i32);
    let m16 = m as u16;
    let sem_ala = m & 0x800 == 0 && m & 0x80 == 0;
    if m & 1 != 0 {
        fb(0xf) * fb(0xf) - 300
    } else if masc & 1 != 0 {
        -200
    } else if m & 2 != 0 {
        t(fb(0x10))
    } else if m & 4 != 0 {
        t(fb(0x11))
    } else if principal && m16 == 8 {
        t(fb(0x16).max(fb(0x11)).max(fb(0x12)).max(fb(0x13)))
    } else if m & 8 != 0 {
        t(if sem_ala { fb(0x12) } else { fb(0x16) })
    } else if m & 0x10 != 0 {
        if !principal || sem_ala {
            if principal && m16 == 0x10 {
                t(fb(0x14).max(fb(0x12)).max(fb(0x13)))
            } else {
                let (a, c, d) = (fb(0x14) - 5, fb(0x13), fb(0x12) - 5);
                let al = if a.max(c) > d { if a > c { a } else { c } } else { d };
                t(al as i8 as i32)
            }
        } else {
            t(fb(0x14).max(fb(0x13)))
        }
    } else if m & 0x20 != 0 {
        if sem_ala {
            let a = fb(0x14) as f64;
            let meio = (fb(0x14) + fb(0x1a)) as f64 * f64_em(0x968968);
            t(ftol(if a <= meio { meio } else { a }))
        } else {
            t(fb(0x14))
        }
    } else if m & 0x40 != 0 {
        t(fb(0x15))
    } else {
        100
    }
}

/// O ajuste da posição (máscara `m`) pelos atributos de jogo da ficha `f`; 100 sem nenhum.
unsafe fn ajuste_da_posicao(f: usize, m: u32) -> i32 {
    let fb = |k: usize| sb(f, k);
    if m & 0x1000 != 0 {
        (fb(0x1a) - 10) * 10
    } else if m & 0x80 != 0 {
        (fb(0x18) - 10) * 10
    } else if m & 0x100 != 0 {
        fb(0x30) + ((fb(0x18) / 2).max(fb(0x19)) * 5 - 0x3c) * 2
    } else if m & 0x200 != 0 {
        (fb(0x19) - 10) * 10
    } else if m & 0x400 != 0 {
        fb(0x3b) + ((fb(0x17) / 2).max(fb(0x19)) * 5 - 0x3c) * 2
    } else if m & 0x800 != 0 {
        (fb(0x17) - 10) * 10
    } else {
        100
    }
}

/// O acréscimo da média das notas (0x7c1950 x 0,2; com o observador `quem` de mais de um ano no
/// clube do jogador, pesada pelos dias) à soma, por `cont`.
unsafe fn bonus_da_media(p: usize, f: usize, clube: usize, quem: usize, cont: i8) -> i32 {
    let media: unsafe extern "thiscall" fn(usize, usize) -> i8 = core::mem::transmute(0x7c1950usize);
    let mut x = (media(*(0xb74350 as *const usize), f) as f64 * f64_em(0x968918)) as f32;
    if clube == *((p + 0x39) as *const usize) && quem != 0 && observado_ha_mais_de_um_ano(quem, p) {
        let d = dias_desde(p) as f64;
        x = (((f64_em(0x969070) - d) * f64_em(0x968eb0) + d * x as f64) * f64_em(0x968e10)) as f32;
    }
    let x = x as f64;
    if x > f64_em(0x968998) {
        ftol((x * f64_em(0x96d638) - f64_em(0x96d630)) * cont as f64) as i8 as i32
    } else if x > f64_em(0x9689a0) {
        ftol((x * f64_em(0x96d628) - f64_em(0x96d620)) * cont as f64) as i8 as i32
    } else {
        0
    }
}

/// O acréscimo da forma (flag 2) à soma: a nota 0x7c1e30(6) de um teto pela média (ou por `l3c`),
/// limitado para os de mais de 33 anos quando `teto_veterano`, pesado pelos dias com o observador
/// `quem`, e as notas 0x7c1e30(1) e 0x7c1e30(6, 0x14, `ultimo`) no clube (ou mesma nação).
#[allow(clippy::too_many_arguments)]
unsafe fn bonus_da_forma(p: usize, f: usize, clube: usize, quem: usize, idade: i8, cont: i8, soma: i32, l3c: i32, teto_veterano: bool, ultimo: u32) -> i32 {
    let notas = *(0xb74350 as *const usize);
    let teto = |v: i32| {
        let y = v as f64 * f32_em(0x96d61c) as f64 + f32_em(0x96d618) as f64;
        (if y > f64_em(0x96d610) { f64_em(0x96d610) } else { y }) as f32
    };
    let razao = || {
        let (m10, m18) = (*((notas + 0x10) as *const f64), *((notas + 0x18) as *const f64));
        if m18 == f64_em(0x9689a0) { f64_em(0x968998) } else { m10 / m18 }
    };
    let mut x = f32::from_bits(0x40d9999a);
    if cont != 0 && soma / cont as i32 > 0x96 {
        x = teto(soma / cont as i32 - 0x96);
    } else if l3c as i16 > 0x96 {
        x = teto(l3c as i16 as i32 - 0x96);
    }
    let mut x = nota_externa(f, 6, 0x12, x) as f32;
    if teto_veterano && idade > 0x21 {
        let r = razao() + f64_em(0x968fd0);
        if (x as f64) > r {
            x = r as f32;
        }
    }
    if clube == *((p + 0x39) as *const usize) && quem != 0 && observado_ha_mais_de_um_ano(quem, p) {
        let d = dias_desde(p) as f64;
        x = (((f64_em(0x969070) - d) * f64_em(0x968eb0) + x as f64 * d) * f64_em(0x968e10)) as f32;
        let fb_p = sb(*((p + 0x61) as *const usize), 0xf);
        if idade as i32 > fb_p / 10 + 0x22 && x as f64 > razao() {
            x = ((razao() + x as f64) * f32_em(0x968f18) as f64) as f32;
        }
    }
    let xf = x as f64;
    let c = cont as f64;
    let mut soma = soma;
    if xf > f64_em(0x968f10) || (xf <= f64_em(0x968998) && xf > f64_em(0x9689a0)) {
        soma += ftol((xf * f32_em(0x96af88) as f64 - f32_em(0x96d608) as f64) * c) as i8 as i32;
    } else if xf > f64_em(0x968998) {
        soma += ftol((xf * f64_em(0x96afc8) - f64_em(0x96d510)) * c) as i8 as i32;
    }
    let dono = *((p + 0x39) as *const usize);
    if clube != 0 && (clube == dono || (dono != 0 && *((clube + 0x53) as *const usize) == *((dono + 0x53) as *const usize))) {
        let xk = (xf * f64_em(0x9689d8)) as f32;
        let r = nota_externa(f, 1, 0x12, xk);
        if r > f64_em(0x968998) {
            soma += ftol((r * f64_em(0x96d628) - f64_em(0x96d600)) * c) as i8 as i32;
        } else if r < xk as f64 {
            soma += ftol((r * f32_em(0x96d5f8) as f64 / xk as f64 - f32_em(0x96d5f8) as f64) * c) as i8 as i32;
        }
        soma += ftol((nota_externa(f, 6, 0x14, f32::from_bits(ultimo)) * f64_em(0x968e30) - f64_em(0x96d5f0)) * c);
    }
    soma
}

/// O desconto do histórico do jogador (0x62ed70, +0x28).
unsafe fn desconto_do_historico(p: usize, l4c: i32) -> i32 {
    let historico: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(0x62ed70usize);
    let h = historico(*(0xb63d28 as *const usize), p);
    if h == 0 {
        return l4c;
    }
    let w = core::ptr::read_unaligned((h + 0x28) as *const i16) as i32;
    l4c + if w <= 10 { -2 * w } else { -20 - w }
}

/// A reputação do jogador (0x62c3d0 pelo id).
unsafe fn reputacao(p: usize) -> i16 {
    let g: unsafe extern "thiscall" fn(usize, u32) -> i16 = core::mem::transmute(0x62c3d0usize);
    g(*(0xb63d28 as *const usize), *(p as *const u32))
}

/// O fim da flag 0x4000 (comum às duas notas): a idade com +0x100, a soma das metades dos
/// atributos (sem goleiro), +0x2f e o fator do estrangeiro (0x7c6830 e a tabela por continente).
#[allow(clippy::too_many_arguments)]
unsafe fn fim_da_idade(p: usize, f: usize, clube: usize, flags: u32, pos: u32, masc: u32, idade: i8, cont: i8, mut l4c: i32) -> i32 {
    let fb = |k: usize| sb(f, k);
    if flags & 0x100 != 0 {
        let cl = if masc & 1 != 0 { 0x1d } else { 0x19 };
        let y = f64_em(0x968e38) - cont as f64 * f64_em(0x968f80);
        if idade as i32 > cl && y > f64_em(0x9689a0) {
            l4c -= ftol((idade as i32 - cl) as f64 * y);
        }
    }
    if pos & 1 == 0 {
        let s: i32 = (0x10..=0x19).map(|k| fb(k) / 2).sum();
        if s > 0x23 {
            l4c += (s - 20) * (s - 20) / 250;
        }
    }
    l4c += ftol((fb(0x2f) - 10) as f64 * f64_em(0x96a670));
    let nac = *((clube + 0x53) as *const usize);
    let pais = *((p + 0x1a) as *const usize);
    if nac == 0 || *((nac + 0x77) as *const u8) == *((pais + 0x77) as *const u8) {
        return l4c;
    }
    let g: unsafe extern "thiscall" fn(usize, usize, usize, u32, u32) -> u32 = core::mem::transmute(0x7c6830usize);
    let mut c = g(*(0xb74350 as *const usize), p, clube, (nac as u32 & !0xff) | *((nac + 0x77) as *const u8) as u32, 1) as u8 as i8;
    if flags & 0x100 != 0 {
        let k = (idade as u8).wrapping_sub((*((p + 0x56) as *const i8) / 2) as u8).wrapping_add(5) as i8;
        let m = f64_em(0x96d5d0) - k as f64 * f64_em(0x96d0e8);
        c = ftol(if c as f64 > m { c as f64 } else { m }) as i8;
    } else {
        let y = l4c as f64 * f64_em(0x96d1e0) - f64_em(0x9688a0);
        if (c as f64) < y {
            c = ftol(y) as i8;
        }
    }
    let b22 = *((p + 0x22) as *const u8) as i32;
    if b22 != 0 && b22 * b22 + core::ptr::read_unaligned((pais + 0x8e) as *const i16) as i32 > 5000 && c <= 5 {
        c = 5;
    }
    if (0..=9).contains(&c) {
        const IGUAL: [usize; 10] = [0x96a6a8, 0x96d588, 0x96d590, 0x96d598, 0x96d5a0, 0x96d5a8, 0x96d5b0, 0x96d5b8, 0x96d5c0, 0x96d5c8];
        const OUTRO: [usize; 10] = [0x96d588, 0x96d590, 0x96d598, 0x96d5a0, 0x96d5a8, 0x96d5b0, 0x96d5b8, 0x96d5c0, 0x96d5c8, 0x968e50];
        let t = if *((pais + 0x76) as *const u8) == 0xe { &IGUAL } else { &OUTRO };
        l4c = ftol(l4c as f64 * f64_em(t[c as usize]));
    }
    l4c
}

/// O ajuste pelo contrato (flag 0x2000000): sem clube (+0x39) há mais de 60 dias, o salário (+0x80)
/// do clube contra o do dono e a satisfação (+0x3d do contrato), a idade e o goleiro, a lesão
/// (0x5444a0) e a idade com os jogos (+0x22).
unsafe fn ajuste_do_contrato(p: usize, f: usize, clube: usize, contrato: usize, idade: i8, mut l4c: i32) -> i32 {
    let fb = |k: usize| sb(f, k);
    let mul = |l: i32, k: f64| ftol(l as f64 * k);
    let dono = *((p + 0x39) as *const usize);
    if dono == 0 {
        let dias: unsafe extern "thiscall" fn(usize, u32, u32) -> i32 = core::mem::transmute(0x54cdb0usize);
        if dias(0xae2c90, *((p + 0x3e) as *const u32), *((p + 0x42) as *const u32)) > 0x3c {
            l4c = mul(l4c, f64_em(0x969040));
        }
    } else {
        let lim = core::ptr::read_unaligned((dono + 0x80) as *const i16) as i32 - 0x4e2;
        let dx = core::ptr::read_unaligned((clube + 0x80) as *const i16);
        let ax = *((contrato + 0x3d) as *const i8) as i16;
        let cl = idade;
        let k = if dx as i32 > lim {
            let ax = ax.wrapping_add(0x64);
            if ax >= 0x7d {
                None
            } else {
                let mut st = f32_em(0x96d248) as f64;
                if dx != 0 {
                    st = lim as f64 / dx as f64 * ax as f64 * f32_em(0x96d5d8) as f64;
                    if st > f64_em(0x967890) {
                        st = f32_em(0x968e70) as f64;
                    } else if st < f64_em(0x969040) {
                        st = f32_em(0x96d248) as f64;
                    }
                }
                if cl > 0x22 {
                    st *= f64_em(0x969040);
                } else if cl > 0x1e {
                    st *= f64_em(0x969520);
                } else if cl > 0x1b {
                    st *= f64_em(0x9689d0);
                }
                if fb(0xf) == 0x14 {
                    st *= f64_em(if cl < 0x12 { 0x969040 } else if cl < 0x14 { 0x969520 } else { 0x9689d0 });
                }
                Some(st)
            }
        } else if ax >= 0x19 || cl <= 0x1e {
            None
        } else {
            let mut st = f32_em(if cl > 0x25 { 0x968f18 } else if cl > 0x22 { 0x96d248 } else { 0x96d364 }) as f64;
            if dx > 0x1482 && cl < 0x14 {
                if ax < -0x4b {
                    st = f32_em(0x968f18) as f64;
                } else if ax < -0x19 {
                    st = f32_em(0x96d320) as f64;
                } else if ax < 0 {
                    st = f32_em(0x96d364) as f64;
                }
            }
            if fb(0xf) == 0x14 {
                st *= f64_em(if cl < 0x12 { 0x969040 } else if cl < 0x15 { 0x969520 } else { 0x9689d0 });
            }
            Some(st)
        };
        if let Some(st) = k {
            l4c = mul(l4c, st);
        }
        let lesao: unsafe extern "C" fn(usize, u32) -> u32 = core::mem::transmute(0x5444a0usize);
        if lesao(p, 0) != 0 {
            l4c = mul(l4c, f64_em(0x9689d0));
        }
    }
    let (cl, al) = (idade, *((p + 0x22) as *const u8));
    // Some(0): a nota vira 5
    let fator: Option<usize> = if cl > 0x22 {
        if al == 0 {
            Some(0x9689e0)
        } else if al < 8 {
            Some(0x968968)
        } else if cl > 0x23 && al < 0x19 {
            Some(0x96a5d0)
        } else if al < 0xf {
            Some(0x969040)
        } else if al < 0x23 {
            Some(0x969520)
        } else {
            None
        }
    } else if cl > 0x1b {
        if al == 0 {
            Some(0x968968)
        } else if al < 8 {
            Some(0x96a5d0)
        } else if al < 0xf {
            Some(0x9689b0)
        } else {
            None
        }
    } else if cl > 0x18 {
        if al == 0 {
            Some(0x96a5d0)
        } else if al < 8 {
            Some(0x969040)
        } else if al < 0xf {
            Some(0x969520)
        } else if al > 0x14 {
            Some(0)
        } else {
            None
        }
    } else if cl > 0x15 {
        if al == 0 {
            Some(0x969520)
        } else if al < 6 {
            Some(0x9689d8)
        } else if al < 0xa {
            Some(0x9689d0)
        } else if al > 0x14 {
            Some(0)
        } else {
            None
        }
    } else if al > 0xa {
        Some(0)
    } else {
        None
    };
    match fator {
        Some(0) => 5,
        Some(k) => mul(l4c, f64_em(k)),
        None => l4c,
    }
}

/// O bônus do observador (flag 0x1000): o conhecimento `conhece` (+0x22 dos jovens, +0x14, +0x0e,
/// +0x1a, +0x1f, +0x13), o gosto do jogador pelo clube e por `quem`, e os atributos de cada faixa de
/// posição; `craque_meia` liga o bônus dos craques também na faixa 0x20 (só na 0x6e6340).
#[allow(clippy::too_many_arguments)]
unsafe fn bonus_do_observador(p: usize, f: usize, clube: usize, conhece: usize, obs: usize, quem: usize, pos: u32, masc: u32, idade: i8, mut l4c: i32, craque_meia: bool) -> i32 {
    let fb = |k: usize| sb(f, k);
    let kb = |k: usize| sb(conhece, k);
    if idade <= 0x17 {
        l4c += ftol((kb(0x22) - 10) as f64 * f64_em(0x96a670));
    }
    let g = |a: usize| -> unsafe extern "C" fn(usize, usize) -> u32 { core::mem::transmute(a) };
    if g(0x547d30)(p, clube) != 0 {
        let m = l4c as f64 * f64_em(0x969040);
        let x = (l4c - 10) as f64;
        l4c = ftol(if x < m { x } else { m });
    } else if g(0x547d60)(p, clube) != 0 {
        let m = l4c as f64 * f64_em(0x9689c0);
        let x = (l4c + 10) as f64;
        l4c = ftol(if x > m { x } else { m });
    }
    if g(0x547840)(p, quem) != 0 {
        l4c -= 50;
    } else if g(0x547810)(p, quem) != 0 {
        let x = l4c as f64 * f64_em(0x968928);
        let m = (l4c + 20) as f64;
        l4c = ftol(if x > m { x } else { m });
    }
    let f44 = fb(0x44);
    let k14 = kb(0x14);
    let mut ecx = (k14 * (f44 - 10) / 3).min(10) + ((sb(p, 0x5b) - 10) * k14 / 3).min(10) + ((sb(p, 0x59) - 10) * sb(obs, 0x59) / 3).min(10);
    if pos & 1 == 0 {
        let fora = pos & 0x80 == 0 && pos & 0x800 == 0;
        let e = kb(0xe);
        let k1a = kb(0x1a) * fb(0x32);
        let k1f = kb(0x1f) * (f44 - 10);
        // os craques: (+0x26 / 3) x +0x1b x +0x36 / 1500, com +0x26 > 30 e +0x36 > 15
        let craque = |ecx: i32| if fb(0x26) > 0x1e && fb(0x36) > 0xf { ecx + fb(0x26) / 3 * fb(0x1b) * fb(0x36) / 1500 } else { ecx };
        if pos & 6 != 0 {
            ecx += k1a / 40 + (fb(0x28) - 10) * e / 10 + fb(0x26) * e / 500 + fb(0x27) * e / 350 + fb(0x43) * e / 250 + k1f / 8 - 10;
            if fora {
                ecx += fb(0x2e) - 15;
            }
        } else if pos & 8 != 0 {
            ecx += k1a / 40 + (fb(0x28) - 10) * e / 8 + fb(0x26) * e / 325 + fb(0x43) * e / 150 + k1f / 6 + fb(0x27) / 15 - 10;
            if fora {
                ecx += fb(0x3e) / 15 + f44 - 15;
            }
        } else if pos & 0x10 != 0 {
            ecx += k1a / 60 + (fb(0x28) - 10) * e / 5 + fb(0x26) * e / 150 + fb(0x43) * e / 100 + k1f / 6 + fb(0x27) / 10 - 10;
            if fora {
                ecx += fb(0x3e) / 15 + fb(0x37) / 15 + f44 - 15;
            } else {
                ecx += fb(0x23) / 15;
            }
        } else if pos & 0x20 != 0 {
            ecx += k1a / 150 + (fb(0x28) - 10) * e / 4 + k1f / 8 + fb(0x43) * e / 75 + fb(0x26) * e / 150 + fb(0x27) / 8 - 10;
            if fora {
                ecx += fb(0x43) / 15 + fb(0x1a) - 15;
            } else {
                ecx += fb(0x23) / 15;
            }
            if craque_meia {
                ecx = craque(ecx);
            }
        } else if pos & 0x40 != 0 {
            ecx += k1a / 400 + (fb(0x28) - 10) * e / 3 + fb(0x43) * e / 200 + k1f / 10 + fb(0x26) * e / 175 + fb(0x27) / 5 - 10;
            if fora {
                ecx += fb(0x33) / 15 + fb(0x36) + fb(0x40) + fb(0x27) / 15 - 0x14;
                ecx = craque(ecx);
            }
        }
    }
    if masc & 0x40 != 0 && pos & 0x40 != 0 {
        ecx += (fb(0x36) * fb(0x2e) - 200) * kb(0x13) / 500;
    }
    if ecx != 0 {
        l4c += ftol((f64_em(0x967890) - l4c as f64 * f64_em(0x96d580)) * ecx as f64).clamp(-0x50, 0x50);
    }
    l4c
}

/// Na lista de transferências ([0xde1f54], 0x8c7260/0x8c7560 com o clube do contrato, que fica em
/// [0xae1080]): a porcentagem +4 / (+4 + +6) em byte (0 sem nenhum); None fora da lista ou de 70 em
/// diante.
unsafe fn na_lista_de_transferencias(p: usize) -> Option<i8> {
    let lista = *(0xde1f54 as *const usize);
    let busca: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(0x8c7260usize);
    let x = busca(lista, p);
    if x == 0 {
        return None;
    }
    let contrato_de: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(0x4cf5a0usize);
    let c = contrato_de(*(0xae1050 as *const usize), p);
    *(0xae1080 as *mut usize) = c;
    let dono = if c == 0 { 0 } else { *(0xae23b4 as *const usize) + *((c + 4) as *const usize) * 0x245 };
    let pode: unsafe extern "thiscall" fn(usize, usize, usize, u32) -> u32 = core::mem::transmute(0x8c7560usize);
    if pode(lista, p, dono, 1) == 0 {
        return None;
    }
    let (a, b) = (*((x + 4) as *const u16) as i32, *((x + 6) as *const u16) as i32);
    if a + b == 0 {
        return Some(0);
    }
    let bl = (a * 100 / (a + b)) as i8;
    if bl >= 0x46 { None } else { Some(bl) }
}

/// O extra do contrato (flag 0x10000): +0x44 pelas bandeiras +0x45, o tipo (+0x4f >> 4) e a lista
/// de transferências.
unsafe fn extra_do_contrato(p: usize, contrato: usize, flags: u32, l28: i32) -> i32 {
    let e = *((contrato + 0x45) as *const u32);
    let s44 = *((contrato + 0x44) as *const i8) as f64;
    let mut extra = 0i32;
    if e & 0x2808 != 0 {
        let x = s44 * f64_em(0x96a670);
        extra = ftol(if f64_em(0x96d578) < x { f64_em(0x96d578) } else { x });
    } else if e != 0 {
        let x = s44 * f64_em(0x968e00);
        extra = ftol(if f64_em(0x96d410) < x { f64_em(0x96d410) } else { x });
    }
    let t = (*((contrato + 0x4f) as *const u8) >> 4) as i8 as i32 - 1;
    let lista = match t {
        0 | 1 => {
            extra += if t == 0 { 0x19 } else { 0xf };
            flags & 0x800000 == 0
        }
        2 => {
            if flags & 0x800000 != 0 {
                extra += 10;
                false
            } else {
                let d = (*((contrato + 0x3e) as *const i8) as i32 - *((contrato + 0x3f) as *const i8) as i32) * 5;
                extra += ftol(d as f64 + (l28 as i16 as f64 * f64_em(0x968e18) - f64_em(0x96d570)));
                true
            }
        }
        6 => {
            extra -= 0x14;
            false
        }
        _ => false,
    };
    if lista {
        if let Some(bl) = na_lista_de_transferencias(p) {
            extra += 0x32 - bl as i32 / 2;
        }
    }
    extra
}

/// O vínculo (flag 0x20000) pelo tipo do contrato `c`: -25 a +25, ou pela lista de transferências.
unsafe fn vinculo(p: usize, c: usize, flags: u32) -> i32 {
    let t = (*((c + 0x4f) as *const u8) >> 4) as i8 as i32 - 1;
    match t {
        0..=2 => {
            if flags & 0x800000 != 0 {
                -25
            } else {
                match na_lista_de_transferencias(p) {
                    Some(bl) => bl as i32 / 2 - 0x4b,
                    None => -25,
                }
            }
        }
        3 | 4 | 7 => 25,
        _ => 0,
    }
}

/// O ajuste pela reputação (0x62c3d0) abaixo de -1000 ou acima de 500.
unsafe fn ajuste_da_reputacao(p: usize, l4c: i32) -> i32 {
    if reputacao(p) < -1000 {
        l4c - ftol(reputacao(p) as f64 * f64_em(0x96a740) + f64_em(0x96afc8))
    } else if reputacao(p) > 0x1f4 {
        l4c + ftol(f64_em(0x968890) - reputacao(p) as f64 * f64_em(0x967888))
    } else {
        l4c
    }
}

/// Os jogos (+0x22, flag 0x100000) ou o clube (flag 4: o dono +0x39 e o +0x69 do treinador dele).
unsafe fn ajuste_dos_jogos(p: usize, f: usize, flags: u32, da_base: bool, l4c: i32) -> i32 {
    if flags & 0x100000 != 0 {
        return l4c - (*((p + 0x22) as *const u8) as i32 * 5).min(0x32);
    }
    if flags & 4 == 0 || !da_base {
        return l4c;
    }
    let dono = *((p + 0x39) as *const usize);
    if dono == 0 {
        return if core::ptr::read_unaligned((f + 9) as *const i16) < 0x1388 { l4c - 0x1e } else { l4c };
    }
    let s = *((dono + 0x57) as *const usize);
    if s == 0 {
        return l4c;
    }
    l4c + ftol((core::ptr::read_unaligned((s + 0x69) as *const i16) as i32 - 0x10) as f64 * f64_em(0x9688a0))
}

/// No próprio clube (+0x39): a nota sobe 5 ou 5%.
unsafe fn no_proprio_clube(p: usize, clube: usize, l4c: i32) -> i32 {
    if *((p + 0x39) as *const usize) != clube {
        return l4c;
    }
    let x = (l4c + 5) as f64;
    let m = l4c as f64 * f64_em(0x9689b8);
    ftol(if x > m { x } else { m })
}

/// A combinação da nota da posição `l40` com o ajuste `l4c` (só `l40` com as flags 0x800 sozinhas).
fn combinar_nota(flags: u32, l40: i32, l4c: i32) -> i32 {
    if flags == 0x800 {
        l40
    } else if l40 < 0 {
        (500 - l4c) * l40
    } else if l4c < 1 {
        l4c + l40
    } else {
        l40 * l4c
    }
}

/// { 0x6e6340 } (cdecl, match_man.cpp): a nota do jogador `p` para a posição `pos` fora da partida
/// (transferências, observação), pelas `flags`, para o `clube`, com o `limite` de corte e o
/// observador `o`: a nota da posição (tabela 0xa15d50) vezes o ajuste da reputação, forma,
/// habilidade vista, idade, contrato e conhecimento do observador. -10000 sem ficha (+0x61) ou
/// abaixo do limite.
unsafe extern "C" fn nota_fora_da_partida(p: usize, pos: u32, flags: u32, clube: usize, limite: i32, o: usize) -> i32 {
    if p == 0 {
        return -10000;
    }
    let f = *((p + 0x61) as *const usize);
    if f == 0 {
        return -10000;
    }
    let fb = |k: usize| sb(f, k);
    let bd = *(0xb63d28 as *const usize);
    let da_base = *(p as *const i32) < *(0xae2364 as *const i32);
    let ativo = limite > -1;
    let mut l24: i32 = 10000;
    let mut l28: i32 = 100;
    let sem_valor = flags & 0x800;
    if sem_valor == 0 || flags & 0x210000 != 0 {
        let valor: unsafe extern "thiscall" fn(usize, usize, u32) -> i32 = core::mem::transmute(0x62c590usize);
        l24 = valor(bd, p, 0);
        l28 = l24 as i16 as i32 / 100;
    }
    let idade = *((p + 0x18) as *const i8);
    let contrato_com: unsafe extern "thiscall" fn(usize, usize, usize) -> usize = core::mem::transmute(0x4cf5f0usize);
    let contrato = if *(0xae1050 as *const usize) != 0 { contrato_com(*(0xae1050 as *const usize), p, clube) } else { 0 };
    let (conhece, obs) = if o != 0 {
        (*((o + 0x69) as *const usize), o)
    } else if clube != 0 && *((clube + 0xcf) as *const usize) != 0 {
        let t = *((clube + 0xcf) as *const usize);
        (*((t + 0x69) as *const usize), t)
    } else {
        (0, 0)
    };
    let relacao: unsafe extern "C" fn(usize, usize, u32) -> i32 = core::mem::transmute(0x5407e0usize);
    let mut l3c = relacao(p, obs, 0);
    let mascara: unsafe extern "C" fn(usize) -> u32 = core::mem::transmute(0x5b7d20usize);
    let masc = mascara(f);
    let mut edi: i32 = if masc as u16 == 0 { -100 } else { 0 };
    edi += if flags & 0x400 != 0 { 100 } else { nota_da_posicao(f, pos, masc, 0xa15d50, true) };
    let l40 = edi + if flags & 0x200 != 0 { 100 } else { ajuste_da_posicao(f, pos) };
    let mut cont: i8 = 0;
    let mut soma: i32 = 0;
    let corte = |soma: i32, cont: i8| ativo && soma * 200 / (cont as i32) < limite;
    if flags & 0x40 != 0 {
        cont = 1;
        soma = core::ptr::read_unaligned((f + 0xb) as *const i16) as i32 / 50;
        if clube == *((p + 0x39) as *const usize) && o != 0 && observado_ha_mais_de_um_ano(o, p) {
            soma = ftol((f64_em(0x968fa8) - dias_desde(p) as f64 * f64_em(0x96a350)) * soma as f64);
        }
        if ativo && soma * 200 < limite {
            return -10000;
        }
    }
    if flags & 0x10 != 0 {
        cont += 1;
        let a = core::ptr::read_unaligned((f + 9) as *const i16) as f64;
        let b = core::ptr::read_unaligned((*((p + 0x1a) as *const usize) + 0x8e) as *const i16) as f64;
        soma += ftol(a / ((f64_em(0x96d640) - b * f64_em(0x96a5c0)) * f64_em(0x968ff8)));
        if corte(soma, cont) {
            return -10000;
        }
    }
    if flags & 0x20 != 0 {
        cont += 1;
        soma += core::ptr::read_unaligned((f + 0xd) as *const i16) as i32 / 50;
        if corte(soma, cont) {
            return -10000;
        }
    }
    if flags & 4 != 0 && da_base {
        let v = ftol(nota_externa(f, 5, 0x12, f32::from_bits(0x40d00000)) * f64_em(0x968ea8));
        if v != 0 {
            cont += 1;
            soma += v;
        }
    }
    let habilidade: unsafe extern "C" fn(usize, usize, usize, i8, i16) -> i16 = core::mem::transmute(0x6e86d0usize);
    let mut l34: i32 = -1;
    if flags & 0x80 != 0 {
        if cont != 0 {
            l3c = soma * 50 / cont as i32;
        }
        l34 = habilidade(obs, p, clube, 2, l3c as i16) as u16 as i32;
        cont += 1;
        soma += l34 as i16 as i32;
        if corte(soma, cont) {
            return -10000;
        }
    }
    if flags & 0x100 != 0 {
        if cont != 0 {
            l3c = do_contrato_ou_media(p, f, clube, soma, cont);
        }
        let mut r = habilidade(obs, p, clube, 1, l3c as i16);
        if l34 as i16 > -1 && r < l34 as i16 {
            r = l34 as i16;
        }
        cont += 1;
        soma += r as i32;
        if corte(soma, cont) {
            return -10000;
        }
    }
    // daqui em diante o original reaproveita o lugar do limite para contas: não corta mais
    if flags & 0x40000 != 0 && da_base {
        soma += bonus_da_media(p, f, clube, o, cont);
    }
    if flags & 2 != 0 && da_base {
        soma = bonus_da_forma(p, f, clube, o, idade, cont, soma, l3c, false, 0x3fb66666);
    }
    let mut l4c: i32 = 0;
    if cont != 0 {
        l4c = soma / cont as i32;
        if l4c > 0x96 {
            l4c = ftol((l4c - 0x96) as f64 * f64_em(0x968940) + f64_em(0x968f50));
        }
    }
    if flags & 8 != 0 && da_base {
        l4c += ftol(fb(0x45) as f64 * f64_em(0x968940) - f64_em(0x968e08));
    }
    if flags & 0x4000 != 0 {
        let q = (0x1b58 - core::ptr::read_unaligned((clube + 0x80) as *const i16) as i32) / 100;
        let k = (if q < 10 { 10 } else { q }) as i8 as i32;
        let lim = if fb(0xf) == 0x14 { 0x24 } else if fb(0x15) == 0x14 || fb(0x14) == 0x14 { 0x22 } else { 0x23 };
        if idade as i32 > lim {
            let y = (f64_em(0x967890) - (idade as i32 - lim) as f64 / k as f64) * l4c as f64;
            let m = (l4c - 5) as f64;
            l4c = ftol(if y < m { y } else { m });
        }
        let historico: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(0x62ed70usize);
        let h = historico(bd, p);
        if h != 0 {
            l4c -= core::ptr::read_unaligned((h + 0x2c) as *const i16) as i32;
        }
        l4c = fim_da_idade(p, f, clube, flags, pos, masc, idade, cont, l4c);
    }
    if contrato != 0 && clube != 0 && flags & 0x2000000 != 0 && da_base {
        l4c = ajuste_do_contrato(p, f, clube, contrato, idade, l4c);
    }
    if sem_valor == 0 {
        let mut v = l24 as i16 as i32;
        if flags & 0x200000 == 0 && reputacao(p) > 1000 {
            v += 500 - reputacao(p) as i32;
        }
        if v < 5000 {
            return v + (l40 * 5 - 10000) * 20;
        }
        l4c += if v < 9000 { v * 3 / 100 - 0x118 } else { (10000 - v) / -100 };
        l4c = desconto_do_historico(p, l4c);
    }
    if flags & 0x200000 != 0 {
        l4c = ajuste_da_fama(f, p, l28, l4c);
    }
    if flags & 0x1000 != 0 && conhece != 0 && clube != 0 && l40 >= 0x64 {
        l4c = bonus_do_observador(p, f, clube, conhece, obs, o, pos, masc, idade, l4c, true);
    }
    l4c = fora_da_nacao(p, clube, flags, l4c);
    if flags & 0x10000 != 0 {
        if contrato != 0 {
            l4c += extra_do_contrato(p, contrato, flags, l28);
        }
    } else if flags & 0x20000 != 0 {
        let c = contrato_com(*(0xae1050 as *const usize), p, clube);
        if c != 0 {
            l4c += vinculo(p, c, flags);
        }
        if sem_valor == 0 {
            l4c = ajuste_da_reputacao(p, l4c);
        }
    }
    l4c = ajuste_dos_jogos(p, f, flags, da_base, l4c);
    if !da_base {
        l4c -= 0x1e;
    }
    l4c = no_proprio_clube(p, clube, l4c);
    combinar_nota(flags, l40, l4c)
}

/// O valor para a habilidade potencial (flag 0x100): no clube do contrato (0x4cf5a0, que fica em
/// [0xae1080]) a média x 25 mais o potencial (+7) x 25 (em 16 bits); fora dele, a média x 50.
unsafe fn do_contrato_ou_media(p: usize, f: usize, clube: usize, soma: i32, cont: i8) -> i32 {
    let contrato_de: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(0x4cf5a0usize);
    let c = contrato_de(*(0xae1050 as *const usize), p);
    *(0xae1080 as *mut usize) = c;
    let dono = if c == 0 { 0 } else { *(0xae23b4 as *const usize) + *((c + 4) as *const usize) * 0x245 };
    if dono == clube {
        let q = soma * 25 / cont as i32;
        let _ = f;
        let pot = core::ptr::read_unaligned((*((p + 0x61) as *const usize) + 7) as *const i16).wrapping_mul(0x19) as u16 as u32;
        q.wrapping_add(((q as u32 & 0xffff0000) | pot) as i32)
    } else {
        soma * 50 / cont as i32
    }
}

/// A fama (flag 0x200000): -200 para os famosos (valor/100 >= 99) de +0x3c alto, +0x2d baixo e
/// reputação abaixo de 500; senão 100 - valor/100.
unsafe fn ajuste_da_fama(f: usize, p: usize, l28: i32, l4c: i32) -> i32 {
    let v = l28 as i16 as i32;
    if v >= 0x63 && sb(f, 0x3c) > 0xe && sb(f, 0x2d) < 8 && reputacao(p) < 0x1f4 {
        l4c - 200
    } else {
        l4c + 100 - v
    }
}

/// Fora da nação do clube (flag 0x1000000): -50 sem nenhuma das duas nacionalidades (+0x1a, +0x1e).
unsafe fn fora_da_nacao(p: usize, clube: usize, flags: u32, l4c: i32) -> i32 {
    if flags & 0x1000000 == 0 || clube == 0 {
        return l4c;
    }
    let nac = *((clube + 0x53) as *const usize);
    if *((p + 0x1a) as *const usize) != nac && *((p + 0x1e) as *const usize) != nac {
        l4c - 50
    } else {
        l4c
    }
}

/// { 0x6e2f20 } (cdecl, match_man.cpp): a nota do jogador `p` (ficha `f`) para uma vaga da escalação
/// (`pos`, e a segunda posição `pos2` com peso 1/3), pelas `flags`, no `clube`, com o lado `lado`
/// (+0x1b observador, +0x1f conhecimento), o técnico `tecnico`, o `limite`, as marcas da tática
/// (`marca` e `bytes`, `tatica`) e a lista das férias `ferias` (16 pares id, posição). Como a
/// 0x6e6340 (tabela 0xa15cfc), mais a condição na partida (`reg`, o jogador da partida), a tática,
/// a idade dos veteranos e o bônus das férias. -10000 sem pessoa ou ficha; -1000000 vetado.
#[allow(clippy::too_many_arguments)]
unsafe extern "C" fn nota_para_a_vaga(
    p: usize, f: usize, reg: usize, pos: u32, flags: u32, clube: usize, lado: usize, tecnico: usize, limite: i32, marca: u32, _marca_alta: u32,
    bytes: u32, tatica: u32, pos2: u32, ferias: usize,
) -> i32 {
    if p == 0 || f == 0 {
        return -10000;
    }
    let fb = |k: usize| sb(f, k);
    let bd = *(0xb63d28 as *const usize);
    let da_base = *(p as *const i32) < *(0xae2364 as *const i32);
    let idade = *((p + 0x18) as *const i8);
    let contrato_com: unsafe extern "thiscall" fn(usize, usize, usize) -> usize = core::mem::transmute(0x4cf5f0usize);
    let contrato = if *(0xae1050 as *const usize) != 0 { contrato_com(*(0xae1050 as *const usize), p, clube) } else { 0 };
    let sem_valor = flags & 0x800;
    let mut l24: i32 = 10000;
    let mut l28: i32 = 100;
    if sem_valor == 0 || flags & 0x210000 != 0 {
        let valor: unsafe extern "thiscall" fn(usize, usize, u32) -> i32 = core::mem::transmute(0x62c590usize);
        l24 = valor(bd, p, 0);
        l28 = l24 as i16 as i32 / 100;
    }
    let limite = if ferias != 0 { 0 } else { limite };
    let ativo = ferias != 0 || limite > -1;
    let (conhece, obs) = if lado != 0 {
        (*((lado + 0x1f) as *const usize), *((lado + 0x1b) as *const usize))
    } else if tecnico != 0 {
        (*((tecnico + 0x69) as *const usize), tecnico)
    } else if clube != 0 && *((clube + 0xcf) as *const usize) != 0 {
        let t = *((clube + 0xcf) as *const usize);
        (*((t + 0x69) as *const usize), t)
    } else {
        (0, 0)
    };
    let relacao: unsafe extern "C" fn(usize, usize, u32) -> i32 = core::mem::transmute(0x5407e0usize);
    let mut l3c = relacao(p, obs, 0);
    let mascara: unsafe extern "C" fn(usize) -> u32 = core::mem::transmute(0x5b7d20usize);
    let masc = mascara(f);
    let segunda = pos2 as u16 != 0 && pos2 as u16 != pos as u16;
    let mut edi: i32 = if masc as u16 == 0 { -100 } else { 0 };
    let mut ebp: i32 = 0;
    if flags & 0x400 != 0 {
        edi += 100;
    } else {
        edi += nota_da_posicao(f, pos, masc, 0xa15cfc, true);
        if segunda {
            ebp = nota_da_posicao(f, pos2, masc, 0xa15cfc, false);
        }
    }
    let l40 = if flags & 0x200 != 0 {
        edi + 100
    } else {
        edi += ajuste_da_posicao(f, pos);
        if segunda { (ebp + ajuste_da_posicao(f, pos2) + 2 * edi) / 3 } else { edi }
    };
    let mut cont: i8 = 0;
    let mut soma: i32 = 0;
    let corte = |soma: i32, cont: i8| ativo && soma * 200 / (cont as i32) < limite;
    if flags & 0x40 != 0 {
        cont = 1;
        soma = core::ptr::read_unaligned((f + 0xb) as *const i16) as i32 / 50;
        if clube == *((p + 0x39) as *const usize) && tecnico != 0 && observado_ha_mais_de_um_ano(tecnico, p) {
            soma = ftol((f64_em(0x968fa8) - dias_desde(p) as f64 * f64_em(0x96a350)) * soma as f64);
        }
        if ativo && soma * 200 < limite {
            return -10000;
        }
    }
    if flags & 0x10 != 0 {
        cont += 1;
        let a = core::ptr::read_unaligned((f + 9) as *const i16) as f64;
        let b = core::ptr::read_unaligned((*((p + 0x1a) as *const usize) + 0x8e) as *const i16) as f64;
        soma += ftol(a / ((f64_em(0x968950) - b * f64_em(0x96a5c0)) * f64_em(0x968ff8)));
        if corte(soma, cont) {
            return -10000;
        }
    }
    if flags & 0x20 != 0 {
        cont += 1;
        soma += core::ptr::read_unaligned((f + 0xd) as *const i16) as i32 / 50;
        if corte(soma, cont) {
            return -10000;
        }
    }
    if flags & 1 != 0 && reg != 0 && masc & 1 == 0 {
        cont += 1;
        soma += (core::ptr::read_unaligned((reg + 0x35) as *const i16) as i32 - folego_na_partida(reg, fb(0xf))) / 50;
    }
    if flags & 4 != 0 && da_base {
        let v = ftol(nota_externa(f, 5, 0x12, f32::from_bits(0x40d00000)) * f64_em(0x968ea8));
        if v != 0 {
            cont += 1;
            soma += v;
        }
    }
    let habilidade: unsafe extern "C" fn(usize, usize, usize, i8, i16) -> i16 = core::mem::transmute(0x6e86d0usize);
    let mut l34: i32 = -1;
    if flags & 0x80 != 0 {
        if cont != 0 {
            l3c = soma * 50 / cont as i32;
        }
        l34 = habilidade(obs, p, clube, 2, l3c as i16) as u16 as i32;
        cont += 1;
        soma += l34 as i16 as i32;
        if corte(soma, cont) {
            return -10000;
        }
    }
    if flags & 0x100 != 0 {
        if cont != 0 {
            l3c = do_contrato_ou_media(p, f, clube, soma, cont);
        }
        let mut r = habilidade(obs, p, clube, 1, l3c as i16);
        if l34 as i16 > -1 && r < l34 as i16 {
            r = l34 as i16;
        }
        let fp = *((p + 0x61) as *const usize);
        if fp != 0 {
            let (d, c) = (*((fp + 0x1b) as *const i8), *((fp + 0x36) as *const i8));
            r = r.wrapping_sub(if d < 6 { 10 } else if d < 10 { 5 } else { 0 });
            r = r.wrapping_sub(if c < 6 { 15 } else if c < 10 { 10 } else { 0 });
        }
        cont += 1;
        soma += r as i32;
        if corte(soma, cont) {
            return -10000;
        }
    }
    if flags & 0x40000 != 0 && da_base {
        soma += bonus_da_media(p, f, clube, tecnico, cont);
    }
    if flags & 2 != 0 && da_base {
        soma = bonus_da_forma(p, f, clube, tecnico, idade, cont, soma, l3c, true, 0x3faccccd);
    }
    let mut l4c: i32 = 0;
    if cont != 0 {
        l4c = soma / cont as i32;
        if l4c > 0x96 {
            l4c = ftol((l4c - 0x96) as f64 * f64_em(0x968940) + f64_em(0x968f50));
        }
    }
    if flags & 8 != 0 && da_base {
        l4c += ftol((fb(0x45) - 10) as f64 * f64_em(0x9689b0));
    }
    let marcada = marca & 0x8000 != 0 || (marca & 0x2000 != 0 && tatica & 0x100 != 0);
    if flags & 0x8000 != 0 {
        l4c = ajuste_da_tatica(f, marca, bytes as u8, tatica, marcada, l4c);
    }
    if contrato != 0 && clube != 0 && flags & 0x2000000 != 0 && da_base {
        l4c = ajuste_do_contrato(p, f, clube, contrato, idade, l4c);
    }
    if flags & 0x4000 != 0 {
        l4c = desconto_do_historico_2c(p, l4c);
        let id = *(p as *const i32);
        let mut edi = l4c;
        if *((*(0xae2d0c as *const usize) as isize + id as isize * 79 + 0xb) as *const u8) & 0x30 != 0 {
            if idade > 0x28 {
                return -1000000;
            }
            edi -= if idade > 0x22 { 0x4b } else { 0x19 };
            l4c = edi;
            if sb(*((p + 0x61) as *const usize), 0x3c) < 0xa {
                edi -= 0x32;
                l4c = edi;
            }
        }
        if idade > 0x2a {
            return -1000000;
        }
        let i = idade as i32;
        if i > 0x22 && masc & 1 == 0 {
            l4c = edi + (0x22 - i) * 10;
        } else if i < 0x17 && masc & 1 != 0 {
            l4c = edi + (i - 0x17) * 10;
        } else if i > 0x20 && pos & 0x40 != 0 {
            l4c = edi + (0x20 - i) * 5;
        }
        l4c = fim_da_idade(p, f, clube, flags, pos, masc, idade, cont, l4c);
    }
    let mut valor: i32 = 0;
    if sem_valor == 0 {
        let mut v: i32;
        if reg != 0 {
            if *((reg + 0x19) as *const i8) == -2 {
                return -1000000;
            }
            let x = core::ptr::read_unaligned((reg + 0x59) as *const f32) as f64;
            v = ftol(x + x + core::ptr::read_unaligned((reg + 0x4d) as *const f32) as f64) as i16 as i32;
            if core::ptr::read_unaligned((*((reg + 0x19e) as *const usize) + 0x8ed4) as *const i16) == 0x1ef {
                v = (v + 0x5dc).min(0x2710);
            }
        } else {
            v = l24 as i16 as i32;
        }
        if flags & 0x200000 == 0 && reputacao(p) > 1000 {
            v += 500 - reputacao(p) as i32;
        }
        if v < 0x1676 {
            let r = v + (l40 * 5 - 0x4e2) * 20;
            return if v >= 0xdac { r } else { r - 0x7a120 };
        }
        if marcada {
            v = ftol(v as f64 * f64_em(0x96a5c0) * v as f64);
        }
        l4c += if v < 9000 { v * 3 / 100 - 0x118 } else { (10000 - v) / -100 };
        l4c = desconto_do_historico(p, l4c);
        valor = v;
    }
    if flags & 0x200000 != 0 {
        l4c = ajuste_da_fama(f, p, l28, l4c);
    }
    if flags & 0x1000 != 0 && conhece != 0 && clube != 0 && l40 >= 0x64 {
        l4c = bonus_do_observador(p, f, clube, conhece, obs, tecnico, pos, masc, idade, l4c, false);
    }
    if flags & 0x2000 != 0 && lado != 0 && *((lado + 0x3b) as *const usize) == p {
        l4c += 100;
    }
    l4c = fora_da_nacao(p, clube, flags, l4c);
    if flags & 0x80000 != 0 && lado != 0 {
        let em = |o: usize| *((lado + o) as *const usize) == p;
        l4c += if em(6) { 0x1e } else if em(0xa) { 0x14 } else if em(0xe) { 0xa } else { 0 };
    }
    // o cansaço do minuto da partida reduz o extra
    let pelo_minuto = |v: i32| {
        if reg == 0 {
            v
        } else {
            let minuto = core::ptr::read_unaligned((*((reg + 0x19e) as *const usize) + 0x8ed0) as *const i16) as f64;
            ftol((f64_em(0x967890) - minuto * f64_em(0x96d268)) * v as f64)
        }
    };
    if flags & 0x10000 != 0 {
        if contrato != 0 {
            let mut extra = pelo_minuto(extra_do_contrato(p, contrato, flags, l28));
            if ferias != 0 {
                extra = ftol(extra as f64 * f64_em(0x9689e0));
            }
            l4c += extra;
        }
    } else if flags & 0x20000 != 0 {
        if contrato != 0 {
            l4c += pelo_minuto(vinculo(p, contrato, flags));
        }
        if sem_valor == 0 {
            l4c = ajuste_da_reputacao(p, l4c);
        }
    }
    l4c = ajuste_dos_jogos(p, f, flags, da_base, l4c);
    let mut base = l40;
    if !da_base && clube != 0 {
        let nac = *((clube + 0x53) as *const usize);
        if nac != 0 && *((nac + 0x11c) as *const u8) != 0 {
            l4c -= 0x46;
            base = l40 - 0x78;
        }
    }
    l4c = no_proprio_clube(p, clube, l4c);
    l4c = combinar_nota(flags, base, l4c);
    if ferias != 0 && (pos & 1 == 0 || masc & 1 != 0) {
        l4c = bonus_das_ferias(p, clube, ferias, pos, base, sem_valor, valor, l4c);
    }
    l4c
}

/// O desconto da flag 0x4000 pelo histórico (0x62ed70, +0x2c).
unsafe fn desconto_do_historico_2c(p: usize, l4c: i32) -> i32 {
    let historico: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(0x62ed70usize);
    let h = historico(*(0xb63d28 as *const usize), p);
    if h == 0 { l4c } else { l4c - core::ptr::read_unaligned((h + 0x2c) as *const i16) as i32 }
}

/// O cansaço do jogador da partida `reg` a descontar do fôlego (+0x35): -2000 para o técnico humano
/// (+0x904d do lado, sem 0x5fd210, seleção ou 0x5fd480) com o jogador abaixo de 11 (+0); fora de
/// campo (+0x19 = -1) os minutos que faltam x 150 (até 3000; goleiro só +3500, os demais pelo menos
/// -2000); em campo, os minutos jogados (minuto - +0x1f) abaixo de 60 x 40.
unsafe fn folego_na_partida(reg: usize, goleiro: i32) -> i32 {
    let m = *((reg + 0x19e) as *const usize);
    let humano = if core::ptr::read_unaligned((m + 0x8ed4) as *const i16) == 0x1ef {
        true
    } else {
        let lado = *((reg + 0x27) as *const i8);
        let base = (m as isize + lado as isize * 0xd0) as usize;
        let t = *((base + 0x904d) as *const usize);
        let n = *(0xae2364 as *const i32);
        if t == 0 || *(t as *const i32) < n - 0x10 || *(t as *const i32) >= n || *((t + 0x5f) as *const u8) == 0 {
            false
        } else {
            let tecnicos = *(0xb63c98 as *const usize);
            let g9a01: unsafe extern "thiscall" fn(usize, usize) -> u32 = core::mem::transmute(0x5fd210usize);
            if g9a01(tecnicos, t) != 0 {
                false
            } else if *((base + 0x904b) as *const u8) != 0 {
                let c = *((*((m + 0x4792) as *const usize) + if lado == 0 { 0x1c } else { 0x20 }) as *const usize);
                let selecao: unsafe extern "C" fn(usize) -> u32 = core::mem::transmute(0x53b900usize);
                if selecao(c) != 0 {
                    true
                } else {
                    let g9a05: unsafe extern "thiscall" fn(usize, usize) -> u32 = core::mem::transmute(0x5fd480usize);
                    g9a05(tecnicos, *((base + 0x904d) as *const usize)) != 0
                }
            } else {
                true
            }
        }
    };
    let extra = if humano && *(reg as *const i8) < 0xb { -2000 } else { 0 };
    let estado = *((reg + 0x19) as *const i8);
    let minuto = core::ptr::read_unaligned((m + 0x8ed0) as *const i16) as i32 / 11;
    if estado == -1 {
        let e = extra + ((60 - minuto) * 150).min(3000);
        if goleiro > 1 { e + 0xdac } else { e.max(-2000) }
    } else if estado >= 0 {
        let jogados = (minuto as u8).wrapping_sub(*((reg + 0x1f) as *const u8)) as i8;
        if jogados < 0x3c { extra + (jogados as i32 - 60) * 40 } else { extra }
    } else {
        extra
    }
}

/// As marcas da tática (flag 0x8000): `marca` (o u64 das instruções, parte baixa), `bytes` (o
/// byte das instruções) e `tatica` contra os atributos da ficha.
unsafe fn ajuste_da_tatica(f: usize, lo: u32, b1: u8, tatica: u32, marcada: bool, mut l4c: i32) -> i32 {
    let fb = |k: usize| sb(f, k);
    let x = |k: usize, c: usize| ftol((fb(k) - 10) as f64 * f64_em(c));
    let t13 = tatica as u8;
    let um = lo & 1 != 0;
    if lo & 4 != 0 || (um && t13 & 2 != 0) {
        l4c += fb(0x37) / 7 - x(0x40, 0x96d5e8);
    } else if lo & 8 != 0 || (um && t13 & 4 != 0) {
        l4c += x(0x36, 0x968e00) - x(0x3c, 0x968fe8) - x(0x2e, 0x968fe8);
    } else if lo & 0x10 != 0 || (um && t13 & 8 != 0) {
        l4c += x(0x36, 0x96a670) - x(0x3c, 0x96d5e8) - x(0x2e, 0x96d5e8);
    }
    if marcada {
        let c = fb(0x3c) - 15;
        let d = fb(0x44) - 15;
        let x1 = ftol((c.abs() * c) as f64 * f64_em(0x968fe8));
        let x2 = ftol((d.abs() * d) as f64 * f64_em(0x968e00));
        l4c += fb(0x1e) / 10 + (x2 - x1);
    } else if b1 & 1 != 0 {
        l4c += fb(0x33) / 12 + (fb(0x43) / 12 - x(0x28, 0x96d5e8));
    }
    if b1 & 2 != 0 {
        l4c += fb(0x39) / 7;
    } else if b1 & 4 != 0 {
        l4c += fb(0x32) / 7;
    }
    if lo & 0x40 != 0 {
        l4c += ftol((fb(0x3b) - 20) as f64 * f64_em(0x96d5e0));
    } else if lo & 0x100 != 0 {
        l4c += ftol((fb(0x30) - 20) as f64 * f64_em(0x96d5e0));
    }
    if lo & 0x200000 != 0 {
        l4c += fb(0x1a) + fb(0x43) / 10 + fb(0x33) / 9 - 20;
    }
    if lo & 0x20000 != 0 {
        l4c += (fb(0x2e) - 10) / 4;
    } else if lo & 0x40000000 != 0 {
        l4c += (10 - fb(0x2e)) / 4;
    }
    if lo & 0x80000000 != 0 {
        l4c += (10 - fb(0x2e)) / 4;
    } else if lo & 0x80000 != 0 {
        l4c += (fb(0x2e) - 10) / 4;
    }
    if lo & 0x800000 != 0 {
        l4c += (fb(0x3c) - 10) / 2 + fb(0x43) / 15 + fb(0x27) / 15;
    }
    if lo & 0x2000000 != 0 {
        l4c += fb(0x26) / 7;
    }
    if lo & 0x8000000 != 0 {
        l4c += (fb(0x40) - 10) / 3 + (fb(0x3d) - 10) / 2;
    }
    if lo & 0x20000000 != 0 {
        l4c += (fb(0x28) - 10) / 2 + fb(0x31) / 14 + fb(0x27) / 14;
    }
    l4c
}

/// O bônus das férias: o jogador na lista (16 pares id, posição) ganha 40000 + 200 x a nota da
/// posição (pelo menos 10000) se estiver entre os 11 e o técnico (0x5fea50) aceitar a posição; senão
/// 200 x a nota (nunca negativa), com a nota negativa pela metade; pesado pelo valor do jogador.
#[allow(clippy::too_many_arguments)]
unsafe fn bonus_das_ferias(p: usize, clube: usize, ferias: usize, pos: u32, base: i32, sem_valor: u32, valor: i32, mut l4c: i32) -> i32 {
    let id = *(p as *const i32);
    let Some(k) = (0..16usize).find(|&k| *((ferias + 8 * k) as *const i32) == id) else {
        return l4c;
    };
    let aceita = || {
        let g: unsafe extern "thiscall" fn(usize, i8, usize) -> u8 = core::mem::transmute(0x5fea50usize);
        if g(*(0xb63c98 as *const usize), 2, *((clube + 0xcf) as *const usize)) == 0 {
            return true;
        }
        let w = *((ferias + 8 * k + 4) as *const i32);
        w == pos as i16 as i32 || w == -1
    };
    let mut bonus;
    if k < 0xb && aceita() {
        bonus = (base * 200).max(10000) + 40000;
        if l4c < 0 {
            l4c = 0;
        }
    } else {
        bonus = (base * 200).max(0);
        if l4c < 0 {
            l4c /= 2;
        }
    }
    if sem_valor == 0 {
        let v = valor as f64;
        let y = v * f64_em(0x968eb8);
        let z = if valor >= 0x251c {
            y * f64_em(0x96d568)
        } else if valor >= 0x222e {
            y * v * f64_em(0x968910)
        } else {
            v * (y * v)
        };
        bonus = ftol((z * f64_em(0x96a600) - f64_em(0x967890)) * bonus as f64);
    }
    if bonus > 0 {
        l4c += bonus;
    }
    l4c
}

unsafe extern "C" fn comparar_nota_fora_da_partida(p: usize, pos: u32, flags: u32, clube: usize, limite: i32, o: usize) -> i32 {
    let f = orig::<unsafe extern "C" fn(usize, u32, u32, usize, i32, usize) -> i32>(392);
    if gravando_no_topo() {
        return f(p, pos, flags, clube, limite, o);
    }
    // ponytail: sem as regiões do sorteador. A nota não sorteia: o único sorteio vem da 0x62ed70, que
    // atualiza o físico do jogador (0x62c680) só na primeira consulta e guarda; a cópia, depois da
    // original, não o refaz. Devolver o sorteador entre as duas acusava essa diferença de cache.
    let reg = vec![(0xae1080usize, 4usize)];
    let rastros = core::cell::RefCell::new((Vec::new(), Vec::new()));
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado(
        &reg,
        || {
            let (r, v) = crate::aleatorio::rastrear(|| f(p, pos, flags, clube, limite, o));
            rastros.borrow_mut().0 = v;
            r
        },
        || {
            let (r, v) = crate::aleatorio::rastrear(|| crate::aleatorio::sem_contar(|| nota_fora_da_partida(p, pos, flags, clube, limite, o)));
            rastros.borrow_mut().1 = v;
            r
        },
    );
    PLACAR.registrar(igual && r == n, || format!("nota_fora_da_partida({:#x}, pos {:#x}, flags {:#x}, limite {}) original={} rust={} sorteios {:?} x {:?} {:x?} x {:x?}", p, pos as u16, flags, limite, r, n, rastros.borrow().0, rastros.borrow().1, mo, mr));
    r
}

#[allow(clippy::too_many_arguments)]
unsafe extern "C" fn comparar_nota_para_a_vaga(
    p: usize, f: usize, reg: usize, pos: u32, flags: u32, clube: usize, lado: usize, tecnico: usize, limite: i32, marca: u32, marca_alta: u32,
    bytes: u32, tatica: u32, pos2: u32, ferias: usize,
) -> i32 {
    let o = orig::<unsafe extern "C" fn(usize, usize, usize, u32, u32, usize, usize, usize, i32, u32, u32, u32, u32, u32, usize) -> i32>(393);
    if gravando_no_topo() {
        return o(p, f, reg, pos, flags, clube, lado, tecnico, limite, marca, marca_alta, bytes, tatica, pos2, ferias);
    }
    // sem as regiões do sorteador, pelo mesmo motivo da nota fora da partida (0x62ed70 com cache)
    let regioes = vec![(0xae1080usize, 4usize)];
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado(
        &regioes,
        || o(p, f, reg, pos, flags, clube, lado, tecnico, limite, marca, marca_alta, bytes, tatica, pos2, ferias),
        || crate::aleatorio::sem_contar(|| nota_para_a_vaga(p, f, reg, pos, flags, clube, lado, tecnico, limite, marca, marca_alta, bytes, tatica, pos2, ferias)),
    );
    PLACAR.registrar(igual && r == n, || format!("nota_para_a_vaga({:#x}, pos {:#x}/{:#x}, flags {:#x}, marca {:#x}) original={} rust={} {:x?} x {:x?}", p, pos as u16, pos2 as u16, flags, marca, r, n, mo, mr));
    r
}

// ---------- 172a leva: o fechamento do motor (6): a leitura da narração, o nome do jogador e a habilidade vista ----------

/// Avança a posição de leitura da fila da narração (+0xc, anel de 12): marca a nova vaga (+0x3d =
/// −1, tira o bit 0x8000 do evento) e, chegando na de escrita (+8, e então +0x2d68 = −1) ou na
/// guardada (+0xa), desliga a fila (+5 = 0). Devolve se desligou.
unsafe fn avancar_leitura(t: usize) -> bool {
    let c = (t + 0xc) as *mut i16;
    *c = if c.read().wrapping_add(1) > 0xb { 0 } else { c.read().wrapping_add(1) };
    let p = t + 0x30 + *c as usize * 14;
    *((p + 0xd) as *mut u8) = 0xff;
    *(p as *mut u16) &= 0x7fff;
    let mut desligou = false;
    if *c == *((t + 8) as *const i16) {
        *((t + 0x2d68) as *mut u32) = u32::MAX;
        *((t + 5) as *mut u8) = 0;
        desligou = true;
    }
    if *c == *((t + 0xa) as *const i16) {
        *((t + 5) as *mut u8) = 0;
        desligou = true;
    }
    desligou
}

/// { 0x6d78b0 } (thiscall, ret 4, match_events.cpp): o próximo evento da narração a mostrar (0 com a
/// fila desligada, +5): pula as vagas vazias; no texto do evento (tabela [0xb68790 + 0x12 × (evento
/// − 8000)], registro +2 de 0x110 bytes, +0x108) anda até a próxima parte separada por `|` (a parte
/// atual em +0xd; o bit 0x8000 marca que há mais) e, acabado o texto, avança a leitura. Em `saida`,
/// o registro de 0x86 bytes da vaga (+0xd8).
unsafe extern "thiscall" fn proximo_evento(t: usize, saida: *mut usize) -> usize {
    if *((t + 5) as *const u8) == 0 {
        return 0;
    }
    crate::comparacao::ramo("narracao proximo evento");
    if !saida.is_null() {
        *saida = (t as isize + 0xd8 + *((t + 0xc) as *const i16) as isize * 0x86) as usize;
    }
    let vaga = |t: usize| t + 0x30 + *((t + 0xc) as *const i16) as usize * 14;
    let mut p = vaga(t);
    while *(p as *const u16) == 0 {
        if avancar_leitura(t) {
            return 0;
        }
        p = vaga(t);
    }
    let evento = (*(p as *const u16) & 0x7fff).wrapping_add(0xe0c0) as i16 as isize;
    let registro = *(p as *const i16).add(1) as isize;
    let tabela = *((0xb68790 + evento * 0x12) as *const isize);
    let texto = *((tabela + registro * 0x110 + 0x108) as *const *const u8);
    let n = {
        let mut k = 0usize;
        while *texto.add(k) != 0 {
            k += 1;
        }
        k as i16
    };
    let parte = (p + 0xd) as *mut i8;
    let mut c = *parte;
    let mut s = 0i16;
    while s < n {
        if *texto.offset(s as isize) == b'|' {
            if c == -1 {
                *parte = 0;
                break;
            }
            c = c.wrapping_sub(1);
            if c < 0 {
                s += 1;
                crate::comparacao::ramo("narracao texto em partes");
                *(p as *mut u16) |= 0x8000;
                *parte = (*parte).wrapping_add(1);
                break;
            }
        }
        s += 1;
    }
    if *parte != -1 {
        while s < n && *texto.offset(s as isize) != b'|' {
            s += 1;
        }
    }
    if n <= s {
        avancar_leitura(t);
    }
    p
}

/// { 0x6db2d0 } (cdecl, match_events.cpp): escreve em `buf` (`tam` bytes) o nome do jogador `jogador`
/// do lado `lado` da partida `pt` (registro de 0x49 bytes em +0x190: id e os três nomes +0x198..+0x1a0,
/// lados de 0x625 bytes) pela 0x53e140: com `curto` e sorteio(5) = 0 a forma 1; senão a forma 5, e se
/// algum dos 100 jogadores de um dos dois clubes (+0, +4; lista da 0x541f90) com outro id ou outro
/// nome tem a mesma forma 5, a forma `longa`.
#[allow(clippy::too_many_arguments)]
unsafe extern "C" fn nome_do_jogador_na_narracao(pt: usize, jogador: i8, lado: i8, buf: *mut u8, tam: u32, curto: u8, _x: u32, longa: u32) {
    let nome: unsafe extern "C" fn(u32, u32, u32, *mut u8, u32, u32, u32) = core::mem::transmute(0x53e140usize);
    let r = (pt as isize + jogador as isize * 0x49 + lado as isize * 0x625) as usize;
    let d = |o: usize| *((r + o) as *const u32);
    if curto != 0 && sortear(5) == 0 {
        nome(d(0x198), d(0x19c), d(0x1a0), buf, tam, 1, d(0x190));
        return;
    }
    crate::comparacao::ramo("narracao nome curto");
    nome(d(0x198), d(0x19c), d(0x1a0), buf, tam, 5, d(0x190));
    let lista: unsafe extern "C" fn(usize, *mut usize, u32) -> u32 = core::mem::transmute(0x541f90usize);
    let textos: unsafe extern "C" fn(*const u8, *const u8, i32, u32) -> i32 = core::mem::transmute(0x90c1d0usize);
    for k in 0..2 {
        let clube = *((pt + 4 * k) as *const u32) as usize;
        let mut l = [0usize; 100];
        lista(*(0xae23b4 as *const usize) + clube * 0x245, l.as_mut_ptr(), 1);
        for &q in l.iter() {
            if q == 0 {
                continue;
            }
            let n = |i: usize| *((*((q + 4 * i) as *const usize) + 0x33) as *const u32);
            if *(q as *const u32) == d(0x190) && n(1) == d(0x198) && n(2) == d(0x19c) && n(3) == d(0x1a0) {
                continue;
            }
            let mut outro = [0u8; 200];
            nome(n(1), n(2), n(3), outro.as_mut_ptr(), 200, 5, d(0x190));
            if textos(buf, outro.as_ptr(), 1, 0) == 0 {
                crate::comparacao::ramo("narracao nome forma longa");
                nome(d(0x198), d(0x19c), d(0x1a0), buf, tam, longa, d(0x190));
                return;
            }
        }
    }
}

/// { 0x6e86d0 } (cdecl, match_man.cpp): a habilidade do jogador `p` (2 = atual, senão potencial) como
/// o observador `o` (0 = o técnico do clube `c`, +0xcf) a vê: a reputação `rep` (negativa: pela
/// 0x5407e0) / 50 mistura com a habilidade verdadeira (ficha +0x61: +5 atual, +7 potencial) e um
/// ruído pseudoaleatório (id do jogador + [0xdd7120] + id do observador) que encolhe com o
/// conhecimento do observador (0x544410 da ficha +0x69, níveis +0x17/+0x18, até 20). Com a ficha
/// do observador, conhecimento alto e a semente favorável, a habilidade atual exata.
unsafe extern "C" fn habilidade_vista(o: usize, p: usize, c: usize, tipo: i8, rep: i16) -> i16 {
    let mut semente = (*(p as *const i32)).wrapping_add(*(0xdd7120 as *const i32));
    let mut rep = if rep > -1 {
        rep / 50
    } else {
        let relacao: unsafe extern "C" fn(usize, usize, u32) -> i16 = core::mem::transmute(0x5407e0usize);
        relacao(p, if o == 0 { *((c + 0xcf) as *const usize) } else { o }, 0) / 50
    };
    let ficha = *((p + 0x61) as *const usize);
    let idade = if tipo == 2 {
        0
    } else {
        (*((p + 0x18) as *const u8)).wrapping_sub(if *((ficha + 0xf) as *const u8) == 0x14 { 0x1a } else { 0x17 }) as i8
    };
    let mut conhece = 0usize;
    if o != 0 {
        conhece = *((o + 0x69) as *const usize);
        semente = semente.wrapping_add(*(o as *const i32));
        if conhece != 0 && tipo == 2 && rep > 0x32 {
            let k = chance_de_conhecer(conhece, *((conhece + 0x17) as *const i8)) as i8 as i32;
            if rep as i32 + (k - 10) * 10 > semente % 200 {
                return core::ptr::read_unaligned((ficha + 5) as *const i16);
            }
        }
    }
    let mut certeza: i8 = 1;
    if conhece != 0 {
        let f = ((semente % 101) as f64 * f64_em(0x967898)) as f32 as f64;
        let x = if semente % 10 == 0 {
            f * f32_em(0x96afb0) as f64
        } else {
            let nivel = *((conhece + if tipo == 2 { 0x17 } else { 0x18 }) as *const i8);
            (chance_de_conhecer(conhece, nivel) as i8 as f64) * f
        };
        certeza = (ftol(x + f64_em(0x968968)) as i8).min(0x14);
    }
    let c32 = certeza as i32;
    let ruido = (semente % ((0x15 - c32) * 2) + c32 - 0x15) as i16 as i32;
    let verdade = if tipo == 2 {
        core::ptr::read_unaligned((ficha + 5) as *const i16)
    } else {
        if idade > 0 {
            rep = rep.wrapping_sub((idade as i16).wrapping_mul(idade as i16));
        }
        core::ptr::read_unaligned((ficha + 7) as *const i16)
    } as i32;
    let peso = (c32 / 2 + 10) as i8 as i32;
    (((verdade + ruido) * peso + (20 - peso) * rep as i32) / 20) as i16
}

unsafe extern "C" fn comparar_habilidade_vista(o: usize, p: usize, c: usize, tipo: i8, rep: i16) -> i16 {
    let r = orig::<unsafe extern "C" fn(usize, usize, usize, i8, i16) -> i16>(390)(o, p, c, tipo, rep);
    let n = habilidade_vista(o, p, c, tipo, rep);
    PLACAR.registrar(r == n, || format!("habilidade_vista({:#x}, {:#x}, {}, {}) original={} rust={}", o, p, tipo, rep, r, n));
    r
}

unsafe extern "thiscall" fn comparar_proximo_evento(t: usize, saida: *mut usize) -> usize {
    let o = orig::<unsafe extern "thiscall" fn(usize, *mut usize) -> usize>(388);
    let mut reg = vec![(t, 0x2db4)];
    if !saida.is_null() {
        reg.push((saida as usize, 4));
    }
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(t, saida), || proximo_evento(t, saida));
    PLACAR.registrar(igual && r == n, || format!("proximo_evento({:#x}) original={:#x} rust={:#x} {:x?} x {:x?}", t, r, n, mo, mr));
    r
}

// ponytail: escreve em `buf` e chama a 0x53e140 e a 0x541f90 (efeitos fora); comparação pelo texto
#[allow(clippy::too_many_arguments)]
unsafe extern "C" fn comparar_nome_do_jogador_na_narracao(pt: usize, jogador: i8, lado: i8, buf: *mut u8, tam: u32, curto: u8, x: u32, longa: u32) {
    let o = orig::<unsafe extern "C" fn(usize, i8, i8, *mut u8, u32, u8, u32, u32)>(389);
    let mut reg = crate::aleatorio::REGIOES_DO_ESTADO.to_vec();
    reg.push((buf as usize, tam as usize));
    let (_, _, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(pt, jogador, lado, buf, tam, curto, x, longa), || crate::aleatorio::sem_contar(|| nome_do_jogador_na_narracao(pt, jogador, lado, buf, tam, curto, x, longa)));
    PLACAR.registrar(igual, || format!("nome_do_jogador_na_narracao({}, {}) {:x?} x {:x?}", jogador, lado, mo, mr));
}

// ---------- 171a leva: o fechamento do motor (5): a narração combinada e o comentário de contexto ----------

/// Os rótulos de desvio da 0x6d60b0 (o fim de cada um devolve ou segue para outro).
#[derive(Clone, Copy)]
enum Rotulo {
    R6cde,
    R6d1d,
    R69a6,
    R69f5,
    R6c95,
    R6cbf,
    Copiar,
}

/// { 0x6d60b0 } (thiscall, ret 8, match_events.cpp): combina o evento novo `e` (14 bytes: palavra do
/// evento; +5, +6 jogador e lado; +7, +8 o outro; +9 inteiro) com o último da fila (posição +8 − 1
/// no anel de 12, registros de 14 bytes em +0x30): devolve o evento combinado (negativo = troca o
/// anterior; 0 = sem combinação) e, nas combinações, copia o jogador, o lado, o outro e o inteiro do
/// anterior para `e`. `m` é o motor (0 fora da partida): dá o lado da posse (+0x8eab) e a bola na
/// área (0x6d58f0). As duas chamadas da 0x6cb960 do original não têm efeito e o valor delas é
/// descartado (ficam de fora).
unsafe extern "thiscall" fn combinar_com_o_anterior(t: usize, e: usize, m: usize) -> i16 {
    let sorteio: unsafe extern "C" fn(i32) -> i32 = core::mem::transmute(0x90cfc0usize);
    let b = |p: usize, o: usize| *((p + o) as *const i8);
    let w = |p: usize| core::ptr::read_unaligned(p as *const i16);
    let s2 = w(e);
    let (posse, area) = if m == 0 { (0, 0) } else { (b(m, 0x8eab), bola_na_area(m)) };
    if w(t + 8) == w(t + 6) {
        return 0;
    }
    let k = if w(t + 8) == 0 { 0xb } else { b(t, 8).wrapping_sub(1) };
    let q = (t as isize + 0x30 + k as isize * 14) as usize;
    let s3 = w(q);
    let igual = |o: usize| b(q, o) == b(e, o);
    let copiar = || core::ptr::copy((q as *const u8).add(5), (e as *mut u8).add(5), 8);
    // o anterior passa a ser o principal e o novo vira o outro (+7, +8)
    let trocar = |inteiro: bool| {
        *((e + 8) as *mut i8) = b(e, 6);
        *((e + 7) as *mut i8) = b(e, 5);
        *((e + 5) as *mut i8) = b(q, 5);
        *((e + 6) as *mut i8) = b(q, 6);
        if inteiro {
            core::ptr::write_unaligned((e + 9) as *mut u32, core::ptr::read_unaligned((q + 9) as *const u32));
        }
    };
    let contexto = |v: i16| (0x2021..=0x20d0).contains(&v);

    if s2 == 0x1f6f {
        if posse == b(e, 6) {
            return 0x21bb;
        }
    } else if s2 == 0x1f92 && (s3 == 0x1f6c || s3 == 0x1f6e) {
        return -0x1f9c;
    }
    if s3 == 0x1f7d && b(e, 6) != b(q, 6) && s2 == 0x1f46 {
        return -0x219d;
    }
    let chute = (0x1f87..=0x1fbd).contains(&s2);
    if (chute || (s2 == 0x1f5f && area != 0)) && s3 == 0x1f7e {
        core::ptr::write_unaligned(q as *mut i16, 0x219c);
        core::ptr::write_unaligned((q + 2) as *mut i16, sorteio(2) as i16);
        return 0;
    }
    if chute && s3 == 8000 {
        core::ptr::write_unaligned(q as *mut i16, 0x219b);
        return 0;
    }

    let mut r = 'escolha: {
        if s3 == 0x1f44 {
            if s2 == 0x1f43 {
                copiar();
                return 0x213f;
            }
            break 'escolha Rotulo::R6cde;
        }
        if s3 == 0x1f69 {
            if s2 == 0x1f9d {
                return if sorteio(3) != 0 { 0 } else { 0x2198 };
            }
            break 'escolha Rotulo::R6cde;
        }
        if contexto(s3) && matches!(s2, 0x1f46 | 0x213e | 0x1f60 | 0x1f5f) && b(e, 6) != b(q, 6) {
            let lado = b(q, 6);
            if (area == -1 && lado == 1) || (area == 1 && lado == 0) {
                return -0x2178;
            }
        }
        if s3 == 0x1f6f {
            if s2 == 0x1f46 {
                if igual(6) || area == 0 {
                    return 0;
                }
                trocar(false);
                return 0x2177;
            }
            break 'escolha Rotulo::R6cde;
        }
        for (de, para) in [(0x2111, 0x2140), (0x210f, 0x2141), (0x1fe6, 0x2142), (0x1fe7, 0x2142)] {
            if s3 == de {
                if s2 == 0x1f46 {
                    if !igual(5) || !igual(6) {
                        return 0;
                    }
                    copiar();
                    return para;
                }
                break 'escolha Rotulo::R6cde;
            }
        }
        if (s3 == 0x213e || s3 == 0x1f71) && s2 == 0x1f46 && igual(5) && igual(6) {
            copiar();
            return 0x1f46;
        }
        if s3 == 0x213e {
            if s2 == 0x1f41 {
                copiar();
                return 0x213e;
            }
            break 'escolha Rotulo::R69a6;
        }
        if s3 == 0x1f41 {
            if s2 == 0x1f46 {
                copiar();
                return 0x1f46;
            }
            break 'escolha Rotulo::R6cde;
        }
        if s3 == 0x2113 {
            if (0x1f86..=0x1fbe).contains(&s2) && sorteio(3) == 0 && igual(5) && igual(6) {
                copiar();
                return s2;
            }
            break 'escolha Rotulo::R6c95;
        }
        if s3 == 0x1f47 {
            if s2 == 0x1f44 || s2 == 0x1f43 {
                if !igual(5) || !igual(6) {
                    return 0;
                }
                copiar();
                return s2;
            }
            if (s2 == 0x1f45 || s2 == 0x20de) && igual(5) && igual(6) {
                copiar();
                return s2;
            }
            break 'escolha Rotulo::R6cde;
        }
        if s3 == 0x1f4d {
            if s2 == 0x1f4a {
                if sorteio(2) == 0 || !igual(5) {
                    return 0;
                }
                if (!igual(6) || !igual(7) || !igual(8)) && (!igual(6) || (b(q, 7) != -1 && b(e, 7) != -1)) {
                    return 0;
                }
                copiar();
                return 0x1f4a;
            }
            break 'escolha Rotulo::R6cde;
        }
        if s3 == 0x1f43 {
            if s2 == 0x1f9d {
                if sorteio(2) == 0 {
                    return 0;
                }
                copiar();
                return 0x1f43;
            }
            break 'escolha Rotulo::R6cde;
        }
        if matches!(s3, 0x1f62 | 0x1f63 | 0x2150) && s2 == 0x1f46 && igual(5) && igual(6) {
            break 'escolha Rotulo::Copiar;
        }
        if s3 == 0x1f5d {
            if s2 == 0x1f6f {
                copiar();
                return 0x2143;
            }
            break 'escolha Rotulo::R6cde;
        }
        if contexto(s3) && s2 == 0x1f46 && b(q, 7) == b(e, 5) && b(q, 8) == b(e, 6) {
            break 'escolha Rotulo::Copiar;
        }
        match s3 {
            0x1f60 if s2 == 0x1f6f => {
                copiar();
                return 0x1f6f;
            }
            0x1f46 if s2 == 0x1f70 => {
                copiar();
                return 0x1f70;
            }
            0x1f84 | 0x1f85 if s2 == 0x1f75 => {
                if sorteio(3) == 0 {
                    return 0;
                }
                copiar();
                return if s3 == 0x1f84 { 0x2144 } else { 0x2145 };
            }
            0x1f60 | 0x1f46 | 0x1f84 | 0x1f85 => {}
            0x1f80 => {
                if s2 == 0x1f46 {
                    if sorteio(2) != 0 && !igual(6) {
                        trocar(true);
                        return 0x2146;
                    }
                    break 'escolha Rotulo::Copiar;
                }
            }
            0x1f5e => break 'escolha Rotulo::R69a6,
            _ => break 'escolha Rotulo::R69f5,
        }
        Rotulo::R6cde
    };

    loop {
        r = match r {
            Rotulo::R69a6 => {
                if s2 == 0x1f46 && sorteio(5) != 0 && igual(6) && !igual(5) {
                    trocar(true);
                    return 0x2147;
                }
                Rotulo::R69f5
            }
            Rotulo::R69f5 => 'r: {
                for (de, para) in [(0x2148, 0x2149), (0x214a, 0x214b), (0x214c, 0x214d)] {
                    if s3 == de {
                        if s2 == 0x1f60 || s2 == 0x1f5f {
                            copiar();
                            return para;
                        }
                        break 'r Rotulo::R6cde;
                    }
                }
                if contexto(s3) {
                    let (ie, iq) = (core::ptr::read_unaligned((e + 9) as *const i32), core::ptr::read_unaligned((q + 9) as *const i32));
                    if contexto(s2) && (1..0x15).contains(&ie) && (1..0x15).contains(&iq) && b(e, 5) == b(q, 7) && b(e, 7) == b(q, 5) {
                        copiar();
                        return 0x214e;
                    }
                    if s2 == 0x1f47 && (1..0x15).contains(&iq) && sorteio(0x16 - iq) != 0 && b(q, 7) == b(e, 5) && b(q, 8) == b(e, 6) {
                        break 'r Rotulo::Copiar;
                    }
                }
                if s3 == 0x214f {
                    if s2 == 0x1f92 {
                        copiar();
                        return 0x214f;
                    }
                    break 'r Rotulo::R6cde;
                }
                if matches!(s3, 0x213e | 0x1f71 | 0x1f72) && s2 == 0x1f75 {
                    copiar();
                    return 0x2151;
                }
                if s3 == 8000 {
                    if s2 == 0x1f9d {
                        copiar();
                        return 0x1f9d;
                    }
                    break 'r Rotulo::R6cde;
                }
                if s3 != 0x2021 {
                    if s3 == 0x1f55 {
                        if s2 == 8000 {
                            return -0x2152;
                        }
                    } else if s3 == 0x2113 {
                        break 'r Rotulo::R6c95;
                    } else if contexto(s3) {
                        break 'r Rotulo::R6cbf;
                    }
                    break 'r Rotulo::R6cde;
                }
                if matches!(s2, 0x1f62 | 0x1f63 | 0x2150) {
                    return -0x2153;
                }
                Rotulo::R6cbf
            }
            Rotulo::R6cbf => {
                if s2 != 0x1f70 {
                    Rotulo::R6cde
                } else if igual(6) {
                    return -0x2157;
                } else {
                    Rotulo::R6d1d
                }
            }
            Rotulo::R6c95 => {
                if s2 == 0x1f62 || s2 == 0x2150 {
                    return -0x2153;
                }
                Rotulo::R6cde
            }
            Rotulo::R6cde => {
                if (0x2076..=0x20d0).contains(&s2) && s3 == 0x2113 {
                    return if igual(5) && igual(6) { -0x2159 } else { 0 };
                }
                Rotulo::R6d1d
            }
            Rotulo::R6d1d => {
                const GRUPO: [i16; 8] = [0x1f4b, 0x1f4c, 0x1f4e, 0x1f4f, 0x1f50, 0x1f51, 0x1f52, 0x1f53];
                if (0x215a..=0x215f).contains(&s3) && s2 == 0x1f70 {
                    return -0x2157;
                }
                if s3 == 0x1f70 {
                    if s2 == 0x1f76 && !igual(6) {
                        copiar();
                        return 0x2165;
                    }
                    return 0;
                }
                if s3 == 0x2150 {
                    if s2 != 0x1f75 {
                        return 0;
                    }
                    copiar();
                    return 0x2151;
                }
                if GRUPO.contains(&s3) && GRUPO.contains(&s2) && sorteio(2) != 0 {
                    return -0x2169;
                }
                if s3 == 0x216e {
                    return if s2 == 0x1f44 && igual(5) && igual(6) { 0x216e } else { 0 };
                }
                if matches!(s3, 0x1f80 | 0x2131 | 0x2130) && s2 == 0x1f46 {
                    Rotulo::Copiar
                } else if s3 != 0x1f73 && !(0x20b9..=0x20c4).contains(&s3) && s3 != 0x20d0 && s3 != 0x1f80 {
                    return 0;
                } else if s2 != 0x1f46 && s2 != 0x1f47 {
                    return 0;
                } else {
                    Rotulo::Copiar
                }
            }
            Rotulo::Copiar => {
                copiar();
                return s3;
            }
        }
    }
}

/// { 0x6d4b70 } (thiscall, ret 0xc, match_eng.cpp): o comentário de contexto `evento` (0x21a3..=0x21af:
/// a corrida da liga, as notícias recentes do clube) pode tocar agora para o `lado`? Fora da faixa
/// 8000..=0x21e4, já tocado (tabela de +0x21e por lado) ou sem competição (+0x4792 → +0x14), não. Pesa
/// o placar agregado (0x6ce310), a linha do clube na tabela da liga (0x4a4850: +0x19/+0x41 e
/// +0x2d/+0x55), o minuto (+0x8ed0 / 11), as notícias do clube nos últimos 10 ou 30 dias (0x757da0 na
/// mídia [0xb6b7c8]) e a média dos 20 jogadores do lado (+0x47cb, passo 0x1be, os marcados em −0x1c);
/// os da tabela gravam o valor em `saida`. Os eventos da faixa fora dos 13 casos: sim.
unsafe extern "thiscall" fn comentario_de_contexto(m: usize, lado: u32, evento: u32, saida: *mut i32) -> u32 {
    let hoje = 0xae2c90usize;
    let datar: unsafe extern "thiscall" fn(usize, *mut [u8; 8], u32) = core::mem::transmute(0x54c8e0usize);
    let (mut d10, mut d30) = ([0u8; 8], [0u8; 8]);
    datar(hoje, &mut d10, 10);
    datar(hoje, &mut d30, 0x1e);
    let ev = evento as u16 as i16 as i32;
    if !(8000..=0x21e4).contains(&ev) {
        return 0;
    }
    let l = lado as u8 as i8;
    if *((m as isize + ((ev + l as i32 * 1000) * 4) as isize - 0x7ae2) as *const u32) != 0 {
        return 0;
    }
    let c = *((m + 0x4792) as *const usize);
    if *((c + 0x14) as *const u32) == 0 {
        return 0;
    }
    let (mut casa, mut fora, mut classificado, mut ida, mut fase3) = (0i8, 0i8, 0u8, 0u8, 0u8);
    let agregado = placar_agregado(m, l, &mut casa, &mut fora, &mut classificado, &mut ida, &mut fase3, 0) as i8 as i32;
    let competicao = *((*(0xadadfc as *const usize)) as *const usize).add(*(c as *const u32) as usize);
    let clube = *((c + if l != 0 { 0x20 } else { 0x1c }) as *const usize);
    let mut linha = 0usize;
    if competicao != 0 && *((competicao + 8) as *const u32) != 0 {
        let busca: unsafe extern "thiscall" fn(usize, usize) -> usize = core::mem::transmute(0x4a4850usize);
        linha = busca(*((competicao + 8) as *const usize), clube);
    }
    let na_competicao = || {
        let f: unsafe extern "thiscall" fn(usize, usize) -> u32 = core::mem::transmute(0x48f150usize);
        f(competicao, clube) != 0
    };
    let noticia = |tipo: u32, data: &[u8; 8]| {
        let f: unsafe extern "thiscall" fn(usize, usize, usize, i32, u32, *const [u8; 8]) -> u32 = core::mem::transmute(0x757da0usize);
        let r = f(*(0xb6b7c8 as *const usize), 0, clube, -1, tipo, data) != 0;
        if r {
            crate::comparacao::ramo("contexto noticia");
        }
        r
    };
    // a média (16 bits) dos jogadores marcados do lado; None sem nenhum
    let media = || {
        let (mut s, mut n) = (0i32, 0i32);
        for k in 0..20 {
            let p = (m as isize + l as isize * 0x22d8 + 0x47cb + k * 0x1be) as usize;
            if *((p - 0x1c) as *const i8) < 0 {
                s += core::ptr::read_unaligned(p as *const i16) as i32;
                n += 1;
            }
        }
        if n == 0 { None } else { Some((s / n) as i16) }
    };
    let do_clube = || core::ptr::read_unaligned((clube + 0x57) as *const u32) == *((c + 0x14) as *const u32);
    let da_competicao = || core::ptr::read_unaligned((clube + 0x1db) as *const u32) == *(c as *const u32);
    let minuto = core::ptr::read_unaligned((m + 0x8ed0) as *const i16) as i32 / 11;
    // 0x6d587c / 0x6d5704: a linha da tabela (+o1, +o2) contra sorteios; grava +o2 em `saida`
    let tabela = |o1: usize, o2: usize| -> u32 {
        if linha == 0 || core::ptr::read_unaligned((linha + o1) as *const i32) <= sortear(3) + 1 {
            return 0;
        }
        let valor = core::ptr::read_unaligned((linha + o2) as *const i32);
        if valor <= sortear(5) + 8 {
            return 0;
        }
        if !saida.is_null() {
            *saida = valor;
        }
        1
    };
    let ate_media = |limite: i16| {
        crate::comparacao::ramo("contexto media");
        media().is_some_and(|v| v >= limite) as u32
    };
    let fim = || media().map_or(1, |v| (v <= 0x1a2b) as u32);
    let nao_trava = if fase3 as i8 != -3 { 3 } else { 0 };
    match ev {
        0x21a3 => {
            if !do_clube() || agregado <= sortear(3) || !na_competicao() {
                return 0;
            }
            if noticia(0x61, &d10) && media().is_some_and(|v| v > 8000) {
                return 1;
            }
            if noticia(0x62, &d10) && media().is_some_and(|v| v > 0x1e46) {
                return 1;
            }
            if !noticia(99, &d10) {
                return 0;
            }
            ate_media(0x1d4d)
        }
        0x21a4 | 0x21a5 => {
            if ev == 0x21a4 {
                if !da_competicao() || agregado <= sortear(nao_trava) {
                    return 0;
                }
            } else if !do_clube() || agregado <= sortear(3) {
                return 0;
            }
            let (tipo, data) = if ev == 0x21a4 { (0x5c, &d30) } else { (0x5f, &d10) };
            if !na_competicao() || !noticia(tipo, data) {
                return 0;
            }
            ate_media(0x1d4d)
        }
        0x21a6 | 0x21a7 | 0x21a9 => {
            if !do_clube() || sortear(-3) <= agregado || minuto < 0x1f || !na_competicao() {
                return 0;
            }
            if minuto == 0x1f {
                crate::comparacao::ramo("contexto minuto 31");
            }
            let tipos: &[u32] = match ev {
                0x21a6 => &[0x3f],
                0x21a7 => &[0x61, 0x62, 0x41, 99],
                _ => &[0x5f, 0x40],
            };
            if !tipos.iter().any(|&t| noticia(t, &d10)) {
                return 0;
            }
            fim()
        }
        0x21a8 => {
            if !da_competicao() || sortear(-nao_trava) <= agregado || !na_competicao() || !noticia(0x5c, &d30) {
                return 0;
            }
            fim()
        }
        0x21aa => {
            if !do_clube() || agregado <= sortear(3) || minuto < 0x1f || !na_competicao() {
                return 0;
            }
            if !noticia(0x3f, &d10) && !noticia(0x60, &d10) {
                return 0;
            }
            ate_media(0x1b59)
        }
        0x21ab => {
            if !do_clube() || agregado <= sortear(2) + 1 || minuto <= 0x1e {
                return 0;
            }
            tabela(0x19, 0x41)
        }
        0x21ac | 0x21ad => {
            if !do_clube() {
                return 0;
            }
            if ev == 0x21ac {
                if -1 - sortear(2) <= agregado {
                    return 0;
                }
            } else if agregado <= sortear(3) + 1 {
                return 0;
            }
            if minuto < 0x1f {
                return 0;
            }
            tabela(0x2d, 0x55)
        }
        0x21ae => {
            if !do_clube() || sortear(-3) <= agregado || minuto < 0x1f || (minuto > 0x4b && agregado < -1) {
                return 0;
            }
            tabela(0x19, 0x41)
        }
        0x21af => {
            if !do_clube() {
                return 0;
            }
            match agregado {
                -1 if minuto > 0x50 => tabela(0x19, 0x41),
                -2 if minuto > sortear(10) + 0x46 => tabela(0x19, 0x41),
                _ => 0,
            }
        }
        _ => 1,
    }
}

unsafe extern "thiscall" fn comparar_combinar_com_o_anterior(t: usize, e: usize, m: usize) -> i16 {
    let o = orig::<unsafe extern "thiscall" fn(usize, usize, usize) -> i16>(385);
    if gravando_no_topo() {
        return o(t, e, m);
    }
    let mut reg = crate::aleatorio::REGIOES_DO_ESTADO.to_vec();
    reg.extend([(e, 14), (t + 0x30, 12 * 14)]);
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(t, e, m), || crate::aleatorio::sem_contar(|| combinar_com_o_anterior(t, e, m)));
    PLACAR.registrar(igual && r == n, || format!("combinar_com_o_anterior({:#x}) original={:#x} rust={:#x} {:x?} x {:x?}", core::ptr::read_unaligned(e as *const u16), r, n, mo, mr));
    r
}

unsafe extern "thiscall" fn comparar_comentario_de_contexto(m: usize, lado: u32, evento: u32, saida: *mut i32) -> u32 {
    let o = orig::<unsafe extern "thiscall" fn(usize, u32, u32, *mut i32) -> u32>(386);
    if gravando_no_topo() {
        return o(m, lado, evento, saida);
    }
    let mut reg = crate::aleatorio::REGIOES_DO_ESTADO.to_vec();
    if !saida.is_null() {
        reg.push((saida as usize, 4));
    }
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(m, lado, evento, saida), || crate::aleatorio::sem_contar(|| comentario_de_contexto(m, lado, evento, saida)));
    PLACAR.registrar(igual && r == n, || format!("comentario_de_contexto({}, {:#x}) original={} rust={} {:x?} x {:x?}", lado as u8, evento as u16, r, n, mo, mr));
    sonda_do_comentario(m, o);
    r
}

/// Sonda de vizinhança do comentário de contexto: o jogo só pergunta pelo evento do gol, então cada
/// chamada real compara também os 13 comentários (0x21a3..=0x21af) nos dois lados e, com as notas
/// dos 20 jogadores do lado (+0x47cb) postas exatamente em cada limite de média (7501, 7001, 8000,
/// 7750, 6699), as fronteiras de `>=`/`>`; e, com uma mídia falsa (uma notícia de hoje de cada tipo
/// para os dois clubes) e o minuto 31, os caminhos que dependem das notícias. O estado do sorteador e as notas voltam ao que eram e os
/// sorteios não contam nem entram no rastro de uma comparação pela fita em curso (o chute, 0x702050,
/// chama esta rotina por dentro): a trajetória do jogo comparando não muda.
unsafe fn sonda_do_comentario(m: usize, o: unsafe extern "thiscall" fn(usize, u32, u32, *mut i32) -> u32) {
    let estado = crate::comparacao::Memoria::ler(&crate::aleatorio::REGIOES_DO_ESTADO);
    // a mídia falsa: no registro de notícias (0x757da0 busca por sujeito -1, id do clube, tipo -1 e
    // subtipo, registros de 0x17 bytes em ordem), uma notícia de hoje de cada subtipo que os
    // comentários consultam, para os dois clubes
    let c = *((m + 0x4792) as *const usize);
    let hoje = *(0xae2c90 as *const [u8; 8]);
    let mut registros: Vec<[u8; 0x17]> = Vec::new();
    for o_clube in [0x1c, 0x20] {
        let clube = *((c + o_clube) as *const usize);
        if clube == 0 {
            continue;
        }
        let id = *(clube as *const i32);
        for sub in [0x3fi16, 0x40, 0x41, 0x5c, 0x5f, 0x60, 0x61, 0x62, 99] {
            let mut r = [0u8; 0x17];
            r[..8].copy_from_slice(&hoje);
            r[8..0xc].copy_from_slice(&(-1i32).to_le_bytes());
            r[0xc..0x10].copy_from_slice(&id.to_le_bytes());
            r[0x11..0x13].copy_from_slice(&sub.to_le_bytes());
            r[0x13..0x17].copy_from_slice(&(-1i32).to_le_bytes());
            registros.push(r);
        }
    }
    let chave = |r: &[u8; 0x17]| (i32::from_le_bytes(r[0xc..0x10].try_into().unwrap()), i16::from_le_bytes(r[0x11..0x13].try_into().unwrap()));
    registros.sort_by_key(chave);
    registros.dedup_by_key(|r| chave(r));
    let falsa: [usize; 3] = [registros.as_ptr() as usize, 0, registros.len()];
    let midia = *(0xb6b7c8 as *const usize);
    let minuto = core::ptr::read_unaligned((m + 0x8ed0) as *const i16);
    crate::aleatorio::pausar_rastro(|| crate::aleatorio::sem_contar(|| {
        // 0: o estado real; 1: com as notícias; 2: com as notícias no minuto 31
        for cenario in 0..3 {
            *(0xb6b7c8 as *mut usize) = if cenario == 0 { midia } else { falsa.as_ptr() as usize };
            core::ptr::write_unaligned((m + 0x8ed0) as *mut i16, if cenario == 2 { 31 * 11 } else { minuto });
            for lado in 0..2u32 {
                let notas: Vec<(usize, usize)> = (0..20).map(|k| (m + lado as usize * 0x22d8 + 0x47cb + k * 0x1be, 2)).collect();
                let guardadas = crate::comparacao::Memoria::ler(&notas);
                for limite in [None, Some(0x1d4di16), Some(0x1b59), Some(8000), Some(0x1e46), Some(0x1a2b)] {
                    if let Some(v) = limite {
                        for &(a, _) in &notas {
                            core::ptr::write_unaligned(a as *mut i16, v);
                        }
                    }
                    for evento in 0x21a3..=0x21afu32 {
                        let mut saida = 0i32;
                        let ps = &mut saida as *mut i32;
                        let mut reg = crate::aleatorio::REGIOES_DO_ESTADO.to_vec();
                        reg.push((ps as usize, 4));
                        let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(m, lado, evento, ps), || comentario_de_contexto(m, lado, evento, ps));
                        PLACAR.registrar(igual && r == n, || format!("sonda comentario_de_contexto(cenario {}, {}, {:#x}, media {:?}) original={} rust={} {:x?} x {:x?}", cenario, lado, evento, limite, r, n, mo, mr));
                    }
                }
                guardadas.escrever();
            }
        }
        *(0xb6b7c8 as *mut usize) = midia;
        core::ptr::write_unaligned((m + 0x8ed0) as *mut i16, minuto);
    }));
    estado.escrever();
}

/// { 0x6eada0 } (thiscall, match_pl.cpp): o construtor do jogador da partida (0x1bc bytes): zera os
/// campos, com −1 em +0, +0x28, +0x2b e +0x5d/+0x61/+0x65, 0xfb em +0x19, 6 em +0x1b e 0x17d4 em +0x35.
/// Devolve `this`.
unsafe extern "thiscall" fn construir_jogador_da_partida(j: usize) -> usize {
    let b = |o: usize, v: u8| *((j + o) as *mut u8) = v;
    let w = |o: usize, v: u16| core::ptr::write_unaligned((j + o) as *mut u16, v);
    let d = |o: usize, v: u32| core::ptr::write_unaligned((j + o) as *mut u32, v);
    for o in [0x19e, 0x69, 0x6d, 0x55, 0x1a6, 0x1a2, 0x1aa, 0x1ae, 0x1b2, 0x1b6, 0x4d, 0xf9] {
        d(o, 0);
    }
    for o in [0x5d, 0x61, 0x65] {
        d(o, u32::MAX);
    }
    for o in [0x37, 0x29, 0x19c, 0x1ba] {
        w(o, 0);
    }
    for o in [0x27, 0x102, 0x103, 0x25, 0x26, 0x1c, 0xff, 0x1a, 0x101, 0xfe, 1, 0x24, 0x23, 0xfd] {
        b(o, 0);
    }
    for o in 2..=0x16 {
        b(o, 0);
    }
    b(0x19, 0xfb);
    b(0, 0xff);
    b(0x2b, 0xff);
    b(0x28, 0xff);
    b(0x1b, 6);
    w(0x35, 0x17d4);
    j
}

unsafe extern "thiscall" fn comparar_construir_jogador_da_partida(j: usize) -> usize {
    let o = orig::<unsafe extern "thiscall" fn(usize) -> usize>(387);
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado(&[(j, 0x1bc)], || o(j), || construir_jogador_da_partida(j));
    PLACAR.registrar(igual && r == n, || format!("construir_jogador_da_partida({:#x}) {:x?} x {:x?}", j, mo, mr));
    r
}

// ---------- 170a leva: o fechamento do motor (4): as ordens das partidas e dos jogadores e a troca do evento ----------

/// { 0x6b6510 } (cdecl, qsort): a ordem das partidas do dia (registros de 0x69 bytes): pela
/// competição (+4), depois +0x46 (byte), +0x36, +0x38 e +0x34 (palavras) e, empatando tudo, pelo nome
/// do primeiro clube (+0x20 → +0x38) na comparação de textos 0x90c1d0 (sem maiúsculas).
unsafe extern "C" fn ordem_das_partidas_do_dia(a: usize, b: usize) -> i32 {
    let d = core::ptr::read_unaligned((a + 4) as *const i32).wrapping_sub(core::ptr::read_unaligned((b + 4) as *const i32));
    if d != 0 {
        return d;
    }
    let d = *((a + 0x46) as *const i8) as i32 - *((b + 0x46) as *const i8) as i32;
    if d != 0 {
        return d;
    }
    for o in [0x36, 0x38, 0x34] {
        let d = core::ptr::read_unaligned((a + o) as *const i16) as i32 - core::ptr::read_unaligned((b + o) as *const i16) as i32;
        if d != 0 {
            return d;
        }
    }
    let textos: unsafe extern "C" fn(usize, usize, i32, u32) -> i32 = core::mem::transmute(0x90c1d0usize);
    let nome = |x: usize| core::ptr::read_unaligned((x + 0x20) as *const usize).wrapping_add(0x38);
    textos(nome(a), nome(b), 1, 0)
}

/// { 0x6bd840 } (cdecl, qsort, match_eng.cpp): a ordem dos jogadores na vez do motor ([0xb67a64]):
/// com +0x8eb2 ligado, o de +0xf582 vem primeiro; depois o de +0x91de; os demais pela força
/// (+0x104 + +0x105) × (+0x3b × 0,005 + 0,5) × +0x4d (f32), truncada, do maior para o menor.
unsafe extern "C" fn ordem_de_acao(a: *const usize, b: *const usize) -> i32 {
    let (pa, pb) = (*a, *b);
    let m = *(0xb67a64 as *const usize);
    if *((m + 0x8eb2) as *const u8) != 0 {
        let primeiro = core::ptr::read_unaligned((m + 0xf582) as *const usize);
        if pa == primeiro {
            return -1;
        }
        if pb == primeiro {
            return 1;
        }
    }
    let c = core::ptr::read_unaligned((m + 0x91de) as *const usize);
    if c == pa {
        return -1;
    }
    if c == pb {
        return 1;
    }
    let forca = |p: usize| {
        let s = *((p + 0x105) as *const i8) as i32 + *((p + 0x104) as *const i8) as i32;
        let w = core::ptr::read_unaligned((p + 0x3b) as *const i16) as f64;
        ftol(s as f64 * (w * f64_em(0x968ef0) + f64_em(0x968968)) * core::ptr::read_unaligned((p + 0x4d) as *const f32) as f64)
    };
    forca(pb).wrapping_sub(forca(pa))
}

/// { 0x6d5d80 } (stdcall, ret 0xc, match_events.cpp): troca o evento da narração por uma variante:
/// com sorteio(3) ≠ 0 fica o mesmo; senão, pelo tipo do lance `tipo` (1, 2, 8, 0x10, 0x20 — este com
/// outro sorteio(3)) há tabelas de troca; os lances 2..4 (byte baixo de `lados`) têm as suas, e o
/// byte de cima 3..5 troca 0x1f4b por 0x217e.
unsafe extern "system" fn variante_do_evento(e: *const i16, lados: u32, tipo: u8) -> i16 {
    let sorteio: unsafe extern "C" fn(i32) -> i32 = core::mem::transmute(0x90cfc0usize);
    if sorteio(3) != 0 {
        return *e;
    }
    let v = *e;
    let tabela: &[(i16, i16)] = match tipo {
        1 => &[(0x216f, 0x2199), (0x2150, 0x2197), (0x2112, 0x2195), (0x1fee, 0x218d), (0x1f49, 0x2182), (0x205a, 0x2190), (0x205b, 0x2191), (0x2079, 0x2192)],
        2 => &[(0x216f, 0x2199), (0x2150, 0x2197), (0x2112, 0x2195), (0x1fe6, 0x2193), (0x1fee, 0x218d), (0x1f48, 0x2181), (0x1f41, 0x2180), (0x1f44, 0x2187), (0x1f86, 0x2189), (0x1fa2, 0x218a)],
        8 => &[(0x216f, 0x2199), (0x2150, 0x2197), (0x2112, 0x2195), (0x1fe6, 0x2193), (0x1fee, 0x218d), (0x205a, 0x218e), (0x205b, 0x218f), (0x1f4b, 0x2183), (0x1f41, 0x2184), (0x1f4a, 0x2188)],
        0x10 => &[(0x1f48, 0x2185)],
        0x20 if sorteio(3) == 0 => &[(0x216f, 0x2199), (0x1fee, 0x218d), (0x1f42, 0x217c), (0x1f4b, 0x217d), (0x1f48, 0x2186)],
        _ => &[],
    };
    if let Some(&(_, n)) = tabela.iter().find(|&&(de, _)| de == v) {
        return n;
    }
    if matches!(lados as u8, 2..=4) {
        let lance: &[(i16, i16)] = &[(0x2112, 0x2196), (0x1fa6, 0x2194), (0x1f8b, 0x218b), (0x1fbf, 0x218c), (0x211f, 0x217f)];
        if let Some(&(_, n)) = lance.iter().find(|&&(de, _)| de == v) {
            return n;
        }
    }
    if matches!((lados >> 8) as u8, 3..=5) && v == 0x1f4b {
        return 0x217e;
    }
    v
}

unsafe extern "C" fn comparar_ordem_das_partidas_do_dia(a: usize, b: usize) -> i32 {
    let r = orig::<unsafe extern "C" fn(usize, usize) -> i32>(382)(a, b);
    let n = ordem_das_partidas_do_dia(a, b);
    PLACAR.registrar(r == n, || format!("ordem_das_partidas_do_dia({:#x}, {:#x}) original={} rust={}", a, b, r, n));
    r
}

unsafe extern "C" fn comparar_ordem_de_acao(a: *const usize, b: *const usize) -> i32 {
    let r = orig::<unsafe extern "C" fn(*const usize, *const usize) -> i32>(383)(a, b);
    let n = ordem_de_acao(a, b);
    PLACAR.registrar(r == n, || format!("ordem_de_acao({:#x}, {:#x}) original={} rust={}", *a, *b, r, n));
    r
}

unsafe extern "system" fn comparar_variante_do_evento(e: *const i16, lados: u32, tipo: u8) -> i16 {
    let o = orig::<unsafe extern "system" fn(*const i16, u32, u8) -> i16>(384);
    if gravando_no_topo() {
        return o(e, lados, tipo);
    }
    let reg = crate::aleatorio::REGIOES_DO_ESTADO.to_vec();
    let (r, n, igual, mo, mr) = crate::comparacao::lado_a_lado(&reg, || o(e, lados, tipo), || crate::aleatorio::sem_contar(|| variante_do_evento(e, lados, tipo)));
    PLACAR.registrar(igual && r == n, || format!("variante_do_evento({:#x}, {:#x}, {}) original={:#x} rust={:#x} {:x?} x {:x?}", *e, lados, tipo, r, n, mo, mr));
    r
}

// ---------- 169a leva: o fechamento do motor (3): a fila da narracao (match_events.cpp) ----------

/// { 0x6d5d00 } (thiscall, ret 0x1c, match_events.cpp): põe um evento na frente da fila da narração:
/// a posição de escrita (+8, anel de 12) recua uma casa (de 0 vai a 11); se o último da fila (+6
/// itens, palavra +0x712 de 14 bytes) é o mesmo evento da nova posição (+0x30), a fila perde um;
/// depois enfileira pela 0x6d6f70 com os mesmos 7 argumentos.
unsafe extern "thiscall" fn evento_na_frente(t: usize, a: u32, b: u32, c: u32, d: u32, e: u32, f: u32, g: u32) -> u32 {
    let w = |o: usize| core::ptr::read_unaligned((t + o) as *const i16);
    let pos = w(8);
    let pos = if pos == 0 { 0xb } else { pos.wrapping_sub(1) };
    core::ptr::write_unaligned((t + 8) as *mut i16, pos);
    let n = w(6);
    if n > 0 && w(0x712 + n as usize * 14) == w(0x30 + pos as usize * 14) {
        core::ptr::write_unaligned((t + 6) as *mut i16, n - 1);
    }
    let enfileirar: unsafe extern "thiscall" fn(usize, u32, u32, u32, u32, u32, u32, u32) -> u32 = core::mem::transmute(0x6d6f70usize);
    enfileirar(t, a, b, c, d, e, f, g)
}

/// { 0x6d5bf0 } (thiscall, ret 4, match_events.cpp): o construtor da fila da narração: zera a fila e
/// os campos (+0x2db0 = 125, +1 e +0xa = −1, +0x2d68 = −1), os globais de evento (0xb68670..), lê os
/// eventos (0x6d9e50), marca as 16 vagas (+0x10, +0x20) com −1 e zera os 16 tempos (+0x2d6c); com
/// `torcida`, toca o loop da torcida do lado da vez ([0xb77c7a]) pela 0x8025e0. Devolve `this`.
unsafe extern "thiscall" fn construir_fila_da_narracao(t: usize, torcida: u8) -> usize {
    let b = |o: usize, v: u8| *((t + o) as *mut u8) = v;
    let w = |o: usize, v: u16| core::ptr::write_unaligned((t + o) as *mut u16, v);
    w(0xa, 0xffff);
    core::ptr::write_unaligned((t + 0x2d68) as *mut u32, u32::MAX);
    for o in [6, 8, 0xc, 0xe] {
        w(o, 0);
    }
    b(5, 0);
    b(2, 0);
    b(0, 1);
    b(0x2db0, 0x7d);
    b(1, 0xff);
    b(3, 0);
    core::ptr::write_unaligned((t + 0x2dac) as *mut u32, 0);
    b(4, 0);
    *(0xb68670 as *mut u16) = 1;
    *(0xb68672 as *mut u16) = 0x2bc;
    *(0xb68674 as *mut u8) = 0;
    *(0xb68778 as *mut u32) = 0xad9c64;
    *(0xb6877c as *mut u32) = 0xad9c64;
    let ler_eventos_cfg: unsafe extern "C" fn() = core::mem::transmute(0x6d9e50usize);
    ler_eventos_cfg();
    for k in 0..16 {
        b(0x10 + k, 0xff);
        b(0x20 + k, 0xff);
        core::ptr::write_unaligned((t + 0x2d6c + 4 * k) as *mut u32, 0);
    }
    if torcida != 0 {
        let caminho: unsafe extern "C" fn(usize, usize) -> usize = core::mem::transmute(0x90bde0usize);
        let tocar: unsafe extern "thiscall" fn(usize, usize, u32, usize, u32) = core::mem::transmute(0x8025e0usize);
        let lado = *(0xb77c7a as *const i16) as isize;
        let nome = caminho(0x9c382c, 0xa159a0);
        tocar(0xb74450, (t as isize + 0x20 + lado) as usize, 2, nome, 1);
    }
    t
}

/// { 0x6d5b50 } (cdecl, match_events.cpp): libera as tabelas de eventos carregadas: em cada uma das
/// entradas de 0x12 bytes de 0xb68790 a 0xb6b72a com tabela própria (nem nula, nem a padrão
/// 0xb68670), os dois textos (+0x108, +0x10c) de cada registro de 0x110 bytes e a tabela; depois
/// zera 0xb6b723 e põe −1 em 0xa1599c.
unsafe extern "C" fn liberar_tabelas_de_eventos() {
    let liberar: unsafe extern "C" fn(usize) = core::mem::transmute(0x9452causize);
    let mut e = 0xb68790usize;
    while e < 0xb6b72a {
        let tabela = core::ptr::read_unaligned(e as *const usize);
        if tabela != 0xb68670 && tabela != 0 {
            let mut k = 0i32;
            while k < core::ptr::read_unaligned((e + 4) as *const i16) as i32 {
                let r = tabela + k as usize * 0x110;
                for o in [0x108, 0x10c] {
                    let p = core::ptr::read_unaligned((r + o) as *const usize);
                    if p != 0 {
                        liberar(p);
                    }
                }
                k += 1;
            }
            liberar(tabela);
            core::ptr::write_unaligned(e as *mut usize, 0);
        }
        e += 0x12;
    }
    *(0xb6b723 as *mut u8) = 0;
    *(0xa1599c as *mut u32) = u32::MAX;
}

